insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (577,4,84,'فَقَـٰتِلْ فِى سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ ۚ وَحَرِّضِ ٱلْمُؤْمِنِينَ ۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأْسَ ٱلَّذِينَ كَفَرُوا۟ ۚ وَٱللَّهُ أَشَدُّ بَأْسًا وَأَشَدُّ تَنكِيلًا','5681961aa4b1d80985288fb369a65ba1c9a2688407acbe181007b80104ae34b2',5,91,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (578,4,85,'مَّن يَشْفَعْ شَفَـٰعَةً حَسَنَةً يَكُن لَّهُۥ نَصِيبٌ مِّنْهَا ۖ وَمَن يَشْفَعْ شَفَـٰعَةً سَيِّئَةً يَكُن لَّهُۥ كِفْلٌ مِّنْهَا ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقِيتًا','2b972f205ca362ad51aa77014432513bab605edb318edd2af21ca4905f4ded4e',5,91,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (579,4,86,'وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا۟ بِأَحْسَنَ مِنْهَآ أَوْ رُدُّوهَآ ۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ حَسِيبًا','63cb44cf7f25ef49797e73366f4fb363e10650277c425179a7bc6c67a258c0a6',5,91,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (580,4,87,'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۗ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ حَدِيثًا','661c696dc71cca1f90c8655d5fefe3815c1856d8b76477c50dccc0ff114df2d2',5,92,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (581,4,88,'فَمَا لَكُمْ فِى ٱلْمُنَـٰفِقِينَ فِئَتَيْنِ وَٱللَّهُ أَرْكَسَهُم بِمَا كَسَبُوٓا۟ ۚ أَتُرِيدُونَ أَن تَهْدُوا۟ مَنْ أَضَلَّ ٱللَّهُ ۖ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا','716966242862b2e2a48314bd48df54f37f8b4ee944a99be01a1601aa1aa86c4d',5,92,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (582,4,89,'وَدُّوا۟ لَوْ تَكْفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَآءً ۖ فَلَا تَتَّخِذُوا۟ مِنْهُمْ أَوْلِيَآءَ حَتَّىٰ يُهَاجِرُوا۟ فِى سَبِيلِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ وَجَدتُّمُوهُمْ ۖ وَلَا تَتَّخِذُوا۟ مِنْهُمْ وَلِيًّا وَلَا نَصِيرًا','34f99b8910889d7555f5e7e8cad94aade28db180854f36c96492590fec387856',5,92,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (583,4,90,'إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ أَوْ جَآءُوكُمْ حَصِرَتْ صُدُورُهُمْ أَن يُقَـٰتِلُوكُمْ أَوْ يُقَـٰتِلُوا۟ قَوْمَهُمْ ۚ وَلَوْ شَآءَ ٱللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَـٰتَلُوكُمْ ۚ فَإِنِ ٱعْتَزَلُوكُمْ فَلَمْ يُقَـٰتِلُوكُمْ وَأَلْقَوْا۟ إِلَيْكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمْ عَلَيْهِمْ سَبِيلًا','a28fb2da1b2b3aeeba7946333efbe7b199a13adb51c6aead08868ec24d8e15cc',5,92,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (584,4,91,'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا۟ قَوْمَهُمْ كُلَّ مَا رُدُّوٓا۟ إِلَى ٱلْفِتْنَةِ أُرْكِسُوا۟ فِيهَا ۚ فَإِن لَّمْ يَعْتَزِلُوكُمْ وَيُلْقُوٓا۟ إِلَيْكُمُ ٱلسَّلَمَ وَيَكُفُّوٓا۟ أَيْدِيَهُمْ فَخُذُوهُمْ وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ ۚ وَأُو۟لَـٰٓئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَـٰنًا مُّبِينًا','54affdc4de257aa563c26f224881fe8852112d04a22b617c4b00f494e436e70b',5,92,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (585,4,92,'وَمَا كَانَ لِمُؤْمِنٍ أَن يَقْتُلَ مُؤْمِنًا إِلَّا خَطَـًٔا ۚ وَمَن قَتَلَ مُؤْمِنًا خَطَـًٔا فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ وَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦٓ إِلَّآ أَن يَصَّدَّقُوا۟ ۚ فَإِن كَانَ مِن قَوْمٍ عَدُوٍّ لَّكُمْ وَهُوَ مُؤْمِنٌ فَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ وَإِن كَانَ مِن قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ فَدِيَةٌ مُّسَلَّمَةٌ إِلَىٰٓ أَهْلِهِۦ وَتَحْرِيرُ رَقَبَةٍ مُّؤْمِنَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ تَوْبَةً مِّنَ ٱللَّهِ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','84561d849497480d6db40d1b6a8cbff0032fd49900bcdb13fffea1f530f66d48',5,93,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (586,4,93,'وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهُۥ جَهَنَّمُ خَـٰلِدًا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيْهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمًا','e8ebe5465e6624abeabf67ff400938fabf39b32e26cd731ea4b0a215f55d5f43',5,93,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (587,4,94,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَـٰمَ لَسْتَ مُؤْمِنًا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','fed25ccd96bc878e4ebb52fe6aaf4a96872e672d73fab7bd96ae0bdf1808dd2f',5,93,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (588,4,95,'لَّا يَسْتَوِى ٱلْقَـٰعِدُونَ مِنَ ٱلْمُؤْمِنِينَ غَيْرُ أُو۟لِى ٱلضَّرَرِ وَٱلْمُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ ۚ فَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ عَلَى ٱلْقَـٰعِدِينَ دَرَجَةً ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَفَضَّلَ ٱللَّهُ ٱلْمُجَـٰهِدِينَ عَلَى ٱلْقَـٰعِدِينَ أَجْرًا عَظِيمًا','f9accf86ab70132586dd5452b472349b85ceff4fd68b173a254c098fe7d4aee6',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (589,4,96,'دَرَجَـٰتٍ مِّنْهُ وَمَغْفِرَةً وَرَحْمَةً ۚ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','6ffa25f376344fa58af7a7007267aeb44426a070e8430cb7413adc2fbc2af759',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (590,4,97,'إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلْمَلَـٰٓئِكَةُ ظَالِمِىٓ أَنفُسِهِمْ قَالُوا۟ فِيمَ كُنتُمْ ۖ قَالُوا۟ كُنَّا مُسْتَضْعَفِينَ فِى ٱلْأَرْضِ ۚ قَالُوٓا۟ أَلَمْ تَكُنْ أَرْضُ ٱللَّهِ وَٰسِعَةً فَتُهَاجِرُوا۟ فِيهَا ۚ فَأُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ ۖ وَسَآءَتْ مَصِيرًا','1291df515398d5bcad188610a38f8adb538699b61e14aa48e287849e7f3ddb0d',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (591,4,98,'إِلَّا ٱلْمُسْتَضْعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلْوِلْدَٰنِ لَا يَسْتَطِيعُونَ حِيلَةً وَلَا يَهْتَدُونَ سَبِيلًا','b0fbbab6faa81fa9f252b0a31a34847dead8cae4e1a6d4547117730cafeb9ea9',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (592,4,99,'فَأُو۟لَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعْفُوَ عَنْهُمْ ۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورًا','e36be6b40bc04d9b46e60ae2c6b6e2d66184306cd1da1442eebab51e47b163cb',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (593,4,100,'وَمَن يُهَاجِرْ فِى سَبِيلِ ٱللَّهِ يَجِدْ فِى ٱلْأَرْضِ مُرَٰغَمًا كَثِيرًا وَسَعَةً ۚ وَمَن يَخْرُجْ مِنۢ بَيْتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدْرِكْهُ ٱلْمَوْتُ فَقَدْ وَقَعَ أَجْرُهُۥ عَلَى ٱللَّهِ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','778846ca86aa82957504902a51f8cf801e1c8983eb87fc93518ea3d6bab17bc6',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (594,4,101,'وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنْ خِفْتُمْ أَن يَفْتِنَكُمُ ٱلَّذِينَ كَفَرُوٓا۟ ۚ إِنَّ ٱلْكَـٰفِرِينَ كَانُوا۟ لَكُمْ عَدُوًّا مُّبِينًا','0347783457dbdb8cd55f2b10ce724ca2a7fd80a6693c84a651b939090fc7f72e',5,94,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (595,4,102,'وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ فَإِذَا سَجَدُوا۟ فَلْيَكُونُوا۟ مِن وَرَآئِكُمْ وَلْتَأْتِ طَآئِفَةٌ أُخْرَىٰ لَمْ يُصَلُّوا۟ فَلْيُصَلُّوا۟ مَعَكَ وَلْيَأْخُذُوا۟ حِذْرَهُمْ وَأَسْلِحَتَهُمْ ۗ وَدَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ تَغْفُلُونَ عَنْ أَسْلِحَتِكُمْ وَأَمْتِعَتِكُمْ فَيَمِيلُونَ عَلَيْكُم مَّيْلَةً وَٰحِدَةً ۚ وَلَا جُنَاحَ عَلَيْكُمْ إِن كَانَ بِكُمْ أَذًى مِّن مَّطَرٍ أَوْ كُنتُم مَّرْضَىٰٓ أَن تَضَعُوٓا۟ أَسْلِحَتَكُمْ ۖ وَخُذُوا۟ حِذْرَكُمْ ۗ إِنَّ ٱللَّهَ أَعَدَّ لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا','27838e8c73f3ecdda90179d17814fce1d874cf9aef82d3f80a3708ca54e910b3',5,95,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (596,4,103,'فَإِذَا قَضَيْتُمُ ٱلصَّلَوٰةَ فَٱذْكُرُوا۟ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ ۚ فَإِذَا ٱطْمَأْنَنتُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ ۚ إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَـٰبًا مَّوْقُوتًا','c6a016c1dbd89db8404f672c9acc98e3c0437bff99b0aafa1d11402a0944764a',5,95,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (597,4,104,'وَلَا تَهِنُوا۟ فِى ٱبْتِغَآءِ ٱلْقَوْمِ ۖ إِن تَكُونُوا۟ تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ ۖ وَتَرْجُونَ مِنَ ٱللَّهِ مَا لَا يَرْجُونَ ۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','7a1cd8a1172b758f1c62184016268d7183c9127ca3fd2ea5e508f049712dd526',5,95,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (598,4,105,'إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ لِتَحْكُمَ بَيْنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُ ۚ وَلَا تَكُن لِّلْخَآئِنِينَ خَصِيمًا','6d106c0645d17f96bec82ad49e9be7731413c578b6c7732e0e79b73819bb8085',5,95,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (599,4,106,'وَٱسْتَغْفِرِ ٱللَّهَ ۖ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا','d4da45d20fde681c6e78d693a030b8cbc3fdb751e023946d5e784ff703d2b0aa',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (600,4,107,'وَلَا تُجَـٰدِلْ عَنِ ٱلَّذِينَ يَخْتَانُونَ أَنفُسَهُمْ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا','a8cf63591507f3410208a0c7cd0f1272b0007061a06f0df42fb7f95ab720d06e',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (601,4,108,'يَسْتَخْفُونَ مِنَ ٱلنَّاسِ وَلَا يَسْتَخْفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمْ إِذْ يُبَيِّتُونَ مَا لَا يَرْضَىٰ مِنَ ٱلْقَوْلِ ۚ وَكَانَ ٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطًا','fe728fdf04d0617c3b6b89c0ae5496d8e2345e3ff59dd5306729b1913e8ebdfb',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (602,4,109,'هَـٰٓأَنتُمْ هَـٰٓؤُلَآءِ جَـٰدَلْتُمْ عَنْهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا فَمَن يُجَـٰدِلُ ٱللَّهَ عَنْهُمْ يَوْمَ ٱلْقِيَـٰمَةِ أَم مَّن يَكُونُ عَلَيْهِمْ وَكِيلًا','9feabd3896afd9e63f9d248eedac17f1a63261da636f2e24e6418e129012f9f1',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (603,4,110,'وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا','f8f7420a06c23b8c977cefede08548b53f97ceb05210565f97007f7e0b78b985',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (604,4,111,'وَمَن يَكْسِبْ إِثْمًا فَإِنَّمَا يَكْسِبُهُۥ عَلَىٰ نَفْسِهِۦ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','cc11e8f0d6cada632e12751ce89217e2e4f8de16b4640afe1314ebd91340a090',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (605,4,112,'وَمَن يَكْسِبْ خَطِيٓـَٔةً أَوْ إِثْمًا ثُمَّ يَرْمِ بِهِۦ بَرِيٓـًٔا فَقَدِ ٱحْتَمَلَ بُهْتَـٰنًا وَإِثْمًا مُّبِينًا','edc57aaa9b1c78c3c1a8bb1637e79ed46090647ec246efbed906cbfb0e9d9811',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (606,4,113,'وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكَ وَرَحْمَتُهُۥ لَهَمَّت طَّآئِفَةٌ مِّنْهُمْ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمْ ۖ وَمَا يَضُرُّونَكَ مِن شَىْءٍ ۚ وَأَنزَلَ ٱللَّهُ عَلَيْكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَعَلَّمَكَ مَا لَمْ تَكُن تَعْلَمُ ۚ وَكَانَ فَضْلُ ٱللَّهِ عَلَيْكَ عَظِيمًا','4e3b84abf9521f14d3c9aa6f2430218bb298004752b80ebdecf2a17e1d49f0ee',5,96,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (607,4,114,'لَّا خَيْرَ فِى كَثِيرٍ مِّن نَّجْوَىٰهُمْ إِلَّا مَنْ أَمَرَ بِصَدَقَةٍ أَوْ مَعْرُوفٍ أَوْ إِصْلَـٰحٍۭ بَيْنَ ٱلنَّاسِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ فَسَوْفَ نُؤْتِيهِ أَجْرًا عَظِيمًا','4be180c503e82b5d295fe199cf3e37668ff57416b1082652fb2f583a41d6d572',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (608,4,115,'وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعْدِ مَا تَبَيَّنَ لَهُ ٱلْهُدَىٰ وَيَتَّبِعْ غَيْرَ سَبِيلِ ٱلْمُؤْمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصْلِهِۦ جَهَنَّمَ ۖ وَسَآءَتْ مَصِيرًا','5d24d52fd589939a64624fa335b7323cf9d38842a012ed596e19fc78ed9a01c2',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (609,4,116,'إِنَّ ٱللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِۦ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُ ۚ وَمَن يُشْرِكْ بِٱللَّهِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا','959216d8e1408e17dabc26cef1292ccda108cccbbad9714e9ea7d4ffc6a066d3',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (610,4,117,'إِن يَدْعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَـٰثًا وَإِن يَدْعُونَ إِلَّا شَيْطَـٰنًا مَّرِيدًا','0165a94ef120523810d8051ef2e3ce53b35a047233943cce555521f69ade3254',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (611,4,118,'لَّعَنَهُ ٱللَّهُ ۘ وَقَالَ لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَّفْرُوضًا','af49a83e0fd84f707c9bd7d888dc60053652eca3dfa3a13473470203ffb53516',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (612,4,119,'وَلَأُضِلَّنَّهُمْ وَلَأُمَنِّيَنَّهُمْ وَلَـَٔامُرَنَّهُمْ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلْأَنْعَـٰمِ وَلَـَٔامُرَنَّهُمْ فَلَيُغَيِّرُنَّ خَلْقَ ٱللَّهِ ۚ وَمَن يَتَّخِذِ ٱلشَّيْطَـٰنَ وَلِيًّا مِّن دُونِ ٱللَّهِ فَقَدْ خَسِرَ خُسْرَانًا مُّبِينًا','6185afa4d0802d27d4fb15a27745c8d5a5608c7f4f1ea9354cbbcbe345deaab2',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (613,4,120,'يَعِدُهُمْ وَيُمَنِّيهِمْ ۖ وَمَا يَعِدُهُمُ ٱلشَّيْطَـٰنُ إِلَّا غُرُورًا','384b4cf4374017522b0641af60592bad5a96eeaf267d723a3dbc50ed641f51c1',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (614,4,121,'أُو۟لَـٰٓئِكَ مَأْوَىٰهُمْ جَهَنَّمُ وَلَا يَجِدُونَ عَنْهَا مَحِيصًا','18024ceb89b6f0c06a338764939613409f51008663366a9090c55463a37cd8d8',5,97,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (615,4,122,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ وَعْدَ ٱللَّهِ حَقًّا ۚ وَمَنْ أَصْدَقُ مِنَ ٱللَّهِ قِيلًا','80139ba216cf0cb06ea11c34bfa0e03a8740d7d9369111f37b8130b14b7eb0ce',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (616,4,123,'لَّيْسَ بِأَمَانِيِّكُمْ وَلَآ أَمَانِىِّ أَهْلِ ٱلْكِتَـٰبِ ۗ مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا','69fe611f06ca78fdb44ad5abd9fd1b267dd61c6722b8a81e318f03feecde18aa',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (617,4,124,'وَمَن يَعْمَلْ مِنَ ٱلصَّـٰلِحَـٰتِ مِن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَـٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ وَلَا يُظْلَمُونَ نَقِيرًا','158f488fe1923a9361d66d90d6c3d754e7dd8fac6f71c67c9fb7d7a9aa038df8',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (618,4,125,'وَمَنْ أَحْسَنُ دِينًا مِّمَّنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ وَٱتَّبَعَ مِلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۗ وَٱتَّخَذَ ٱللَّهُ إِبْرَٰهِيمَ خَلِيلًا','ca8631f02cb91f29135e8d4e69e821482cd97b94bb7350028bce0e0f24d20b55',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (619,4,126,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ مُّحِيطًا','fcaa4fa5b1a2c7766efa7bba9c013ede6516fab20a5d814354348d41a79d22cc',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (620,4,127,'وَيَسْتَفْتُونَكَ فِى ٱلنِّسَآءِ ۖ قُلِ ٱللَّهُ يُفْتِيكُمْ فِيهِنَّ وَمَا يُتْلَىٰ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ فِى يَتَـٰمَى ٱلنِّسَآءِ ٱلَّـٰتِى لَا تُؤْتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرْغَبُونَ أَن تَنكِحُوهُنَّ وَٱلْمُسْتَضْعَفِينَ مِنَ ٱلْوِلْدَٰنِ وَأَن تَقُومُوا۟ لِلْيَتَـٰمَىٰ بِٱلْقِسْطِ ۚ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمًا','c390022620dd4fcd2e158a22cf69aefab2ee7450fd01c48adeed34bc7985b793',5,98,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (621,4,128,'وَإِنِ ٱمْرَأَةٌ خَافَتْ مِنۢ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا ۚ وَٱلصُّلْحُ خَيْرٌ ۗ وَأُحْضِرَتِ ٱلْأَنفُسُ ٱلشُّحَّ ۚ وَإِن تُحْسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','33f36177038512ffac52be02ebd358ceadeda4c2787f801d4a2c6ba7c9f6559c',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (622,4,129,'وَلَن تَسْتَطِيعُوٓا۟ أَن تَعْدِلُوا۟ بَيْنَ ٱلنِّسَآءِ وَلَوْ حَرَصْتُمْ ۖ فَلَا تَمِيلُوا۟ كُلَّ ٱلْمَيْلِ فَتَذَرُوهَا كَٱلْمُعَلَّقَةِ ۚ وَإِن تُصْلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا','2042055ccf5b3b9765838bc07cf2dc5fddbd363ce49f499e6664228e24bffeca',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (623,4,130,'وَإِن يَتَفَرَّقَا يُغْنِ ٱللَّهُ كُلًّا مِّن سَعَتِهِۦ ۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمًا','5443aaf88a65250dcb5a51ddfa63fc9c105163288bf7825f00921d3b1462da2d',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (624,4,131,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَلَقَدْ وَصَّيْنَا ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَإِيَّاكُمْ أَنِ ٱتَّقُوا۟ ٱللَّهَ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدًا','0c1e56959110071984f053030939fffd02ff9375515389861e9e7a7ec364252f',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (625,4,132,'وَلِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','7f467f38c1b36c04669f14a1f6f23b4720604afc077614bc9cd54a3b25994c2c',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (626,4,133,'إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا ٱلنَّاسُ وَيَأْتِ بِـَٔاخَرِينَ ۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرًا','ad71b3e8d7ef7e8b51871f375f796e0a74c0f9c424dc1150594bed9707ad76a4',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (627,4,134,'مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنْيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ ۚ وَكَانَ ٱللَّهُ سَمِيعًۢا بَصِيرًا','1e91933c3a53c896ba015d1a73a474525e618c3dc2f9c352880cc562c5828dcf',5,99,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (628,4,135,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ بِٱلْقِسْطِ شُهَدَآءَ لِلَّهِ وَلَوْ عَلَىٰٓ أَنفُسِكُمْ أَوِ ٱلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ ۚ إِن يَكُنْ غَنِيًّا أَوْ فَقِيرًا فَٱللَّهُ أَوْلَىٰ بِهِمَا ۖ فَلَا تَتَّبِعُوا۟ ٱلْهَوَىٰٓ أَن تَعْدِلُوا۟ ۚ وَإِن تَلْوُۥٓا۟ أَوْ تُعْرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','5a23ddb37e263be2e8d28fbf08010fc8ea5dfbe6e210f3376e43f6d1ba06660f',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (629,4,136,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِى نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلْكِتَـٰبِ ٱلَّذِىٓ أَنزَلَ مِن قَبْلُ ۚ وَمَن يَكْفُرْ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَقَدْ ضَلَّ ضَلَـٰلًۢا بَعِيدًا','1e5178934b567344d57a1775978bdf3963d15795e773f38bb613cf6aaf2b3a3b',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (630,4,137,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزْدَادُوا۟ كُفْرًا لَّمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ سَبِيلًۢا','ee7e764ffcefcdeb57d5aaa25790f062002f3c7192fa32e209aefbc106e5f55f',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (631,4,138,'بَشِّرِ ٱلْمُنَـٰفِقِينَ بِأَنَّ لَهُمْ عَذَابًا أَلِيمًا','63f1bda9efa343687c3d86f4aad39462fd6bebdabeadb12a61c7e2c63b9b1024',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (632,4,139,'ٱلَّذِينَ يَتَّخِذُونَ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَيَبْتَغُونَ عِندَهُمُ ٱلْعِزَّةَ فَإِنَّ ٱلْعِزَّةَ لِلَّهِ جَمِيعًا','147c65d4984bf47e1c1c67cf9582c0e8b58973f93f22f693e9f598b011f33c58',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (633,4,140,'وَقَدْ نَزَّلَ عَلَيْكُمْ فِى ٱلْكِتَـٰبِ أَنْ إِذَا سَمِعْتُمْ ءَايَـٰتِ ٱللَّهِ يُكْفَرُ بِهَا وَيُسْتَهْزَأُ بِهَا فَلَا تَقْعُدُوا۟ مَعَهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦٓ ۚ إِنَّكُمْ إِذًا مِّثْلُهُمْ ۗ إِنَّ ٱللَّهَ جَامِعُ ٱلْمُنَـٰفِقِينَ وَٱلْكَـٰفِرِينَ فِى جَهَنَّمَ جَمِيعًا','9c726845e5f206467214612c214af9bd44421c85e2e800bbbfcbac9dd2dfaa01',5,100,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (634,4,141,'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمْ فَإِن كَانَ لَكُمْ فَتْحٌ مِّنَ ٱللَّهِ قَالُوٓا۟ أَلَمْ نَكُن مَّعَكُمْ وَإِن كَانَ لِلْكَـٰفِرِينَ نَصِيبٌ قَالُوٓا۟ أَلَمْ نَسْتَحْوِذْ عَلَيْكُمْ وَنَمْنَعْكُم مِّنَ ٱلْمُؤْمِنِينَ ۚ فَٱللَّهُ يَحْكُمُ بَيْنَكُمْ يَوْمَ ٱلْقِيَـٰمَةِ ۗ وَلَن يَجْعَلَ ٱللَّهُ لِلْكَـٰفِرِينَ عَلَى ٱلْمُؤْمِنِينَ سَبِيلًا','ed30b1e24cd6ca87d7a4719fe5a798ca3b551cf982c84c9f4b8ef0316d88cf36',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (635,4,142,'إِنَّ ٱلْمُنَـٰفِقِينَ يُخَـٰدِعُونَ ٱللَّهَ وَهُوَ خَـٰدِعُهُمْ وَإِذَا قَامُوٓا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذْكُرُونَ ٱللَّهَ إِلَّا قَلِيلًا','0035ef67cebf53bec038cb49da4459f61bbd152effc322827ff3eca1cd306358',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (636,4,143,'مُّذَبْذَبِينَ بَيْنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِ ۚ وَمَن يُضْلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلًا','1ff983611f699ab16ae441cf1c707dc9eb87be08076bdee35cdd04ea49cfe455',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (637,4,144,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْكَـٰفِرِينَ أَوْلِيَآءَ مِن دُونِ ٱلْمُؤْمِنِينَ ۚ أَتُرِيدُونَ أَن تَجْعَلُوا۟ لِلَّهِ عَلَيْكُمْ سُلْطَـٰنًا مُّبِينًا','5dabd05d9d154a8f152f3e9e6315b432f6a8753f34bdf61fb3e3d8bfcaa0ee7c',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (638,4,145,'إِنَّ ٱلْمُنَـٰفِقِينَ فِى ٱلدَّرْكِ ٱلْأَسْفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمْ نَصِيرًا','2c272de15ee0a3bb3245f8f15e4f2ac6ee2ee1dccd2252453831e699ef0ce065',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (639,4,146,'إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَٱعْتَصَمُوا۟ بِٱللَّهِ وَأَخْلَصُوا۟ دِينَهُمْ لِلَّهِ فَأُو۟لَـٰٓئِكَ مَعَ ٱلْمُؤْمِنِينَ ۖ وَسَوْفَ يُؤْتِ ٱللَّهُ ٱلْمُؤْمِنِينَ أَجْرًا عَظِيمًا','bba83fc16ba13e57d8101e3b7b43ca36f8498b3ee12dbd57c5e026f7b7a76327',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (640,4,147,'مَّا يَفْعَلُ ٱللَّهُ بِعَذَابِكُمْ إِن شَكَرْتُمْ وَءَامَنتُمْ ۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمًا','937629fc4e3dcd2fa32b173e7414546908d535cb0e1b85f2d972f6a81205002d',5,101,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (641,4,148,'لَّا يُحِبُّ ٱللَّهُ ٱلْجَهْرَ بِٱلسُّوٓءِ مِنَ ٱلْقَوْلِ إِلَّا مَن ظُلِمَ ۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا','77762e6df7939d7756163a515b104184d87a268f40404fea9a0c30c81b53fb94',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (642,4,149,'إِن تُبْدُوا۟ خَيْرًا أَوْ تُخْفُوهُ أَوْ تَعْفُوا۟ عَن سُوٓءٍ فَإِنَّ ٱللَّهَ كَانَ عَفُوًّا قَدِيرًا','6ba3c46151bd457e629afb95c4dec5b3fb68a757db91c8417675e3fa7258cf36',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (643,4,150,'إِنَّ ٱلَّذِينَ يَكْفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُوا۟ بَيْنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَن يَتَّخِذُوا۟ بَيْنَ ذَٰلِكَ سَبِيلًا','25574c4fe522d7c4546de65e545e43a02d0b664c812660b729c6848b2a492e00',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (644,4,151,'أُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ حَقًّا ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ عَذَابًا مُّهِينًا','46c89bf575dcf622426b1e11840bbb4e8df891111bdb9a1e1b8df97a9c45e39c',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (645,4,152,'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمْ يُفَرِّقُوا۟ بَيْنَ أَحَدٍ مِّنْهُمْ أُو۟لَـٰٓئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ ۗ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا','ece632334ff1646d2d56196b73928d9bfb42a8175406050dc6b9c657f09f991a',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (646,4,153,'يَسْـَٔلُكَ أَهْلُ ٱلْكِتَـٰبِ أَن تُنَزِّلَ عَلَيْهِمْ كِتَـٰبًا مِّنَ ٱلسَّمَآءِ ۚ فَقَدْ سَأَلُوا۟ مُوسَىٰٓ أَكْبَرَ مِن ذَٰلِكَ فَقَالُوٓا۟ أَرِنَا ٱللَّهَ جَهْرَةً فَأَخَذَتْهُمُ ٱلصَّـٰعِقَةُ بِظُلْمِهِمْ ۚ ثُمَّ ٱتَّخَذُوا۟ ٱلْعِجْلَ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَـٰتُ فَعَفَوْنَا عَن ذَٰلِكَ ۚ وَءَاتَيْنَا مُوسَىٰ سُلْطَـٰنًا مُّبِينًا','6573889f7982e1aec36565cf2ad703b652dd84948963c51840fddf06d1437760',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (647,4,154,'وَرَفَعْنَا فَوْقَهُمُ ٱلطُّورَ بِمِيثَـٰقِهِمْ وَقُلْنَا لَهُمُ ٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُلْنَا لَهُمْ لَا تَعْدُوا۟ فِى ٱلسَّبْتِ وَأَخَذْنَا مِنْهُم مِّيثَـٰقًا غَلِيظًا','f23135cbdcbc3cb0950e22ab4933b7a2cfb262ef384dc61d60539aa1759204b4',6,102,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (648,4,155,'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ وَكُفْرِهِم بِـَٔايَـٰتِ ٱللَّهِ وَقَتْلِهِمُ ٱلْأَنۢبِيَآءَ بِغَيْرِ حَقٍّ وَقَوْلِهِمْ قُلُوبُنَا غُلْفٌۢ ۚ بَلْ طَبَعَ ٱللَّهُ عَلَيْهَا بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا','896ff85c0377bfb568ff5f2a734d615b21fdd4d0b74847a7ba914678c9bf08cf',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (649,4,156,'وَبِكُفْرِهِمْ وَقَوْلِهِمْ عَلَىٰ مَرْيَمَ بُهْتَـٰنًا عَظِيمًا','49dea75ef03862cd3541a19beb19fe9a3ca80594261be7754a9fe82c9011847e',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (650,4,157,'وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا','fc004b96808838f7088aa02c92e9e151473fa972c87a58c96b5748945340be38',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (651,4,158,'بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','f77243533ad6cc9e21107b71dc7ac6dc984b418daa6613f51592187395ea3691',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (652,4,159,'وَإِن مِّنْ أَهْلِ ٱلْكِتَـٰبِ إِلَّا لَيُؤْمِنَنَّ بِهِۦ قَبْلَ مَوْتِهِۦ ۖ وَيَوْمَ ٱلْقِيَـٰمَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا','feae596dcf723454cad8c8fac77bd61026512fb9bb2fa9efe0ebc8e914136d7d',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (653,4,160,'فَبِظُلْمٍ مِّنَ ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا عَلَيْهِمْ طَيِّبَـٰتٍ أُحِلَّتْ لَهُمْ وَبِصَدِّهِمْ عَن سَبِيلِ ٱللَّهِ كَثِيرًا','130441807de68110e916784264244155c16c038de63fd87ce683ce1045b35782',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (654,4,161,'وَأَخْذِهِمُ ٱلرِّبَوٰا۟ وَقَدْ نُهُوا۟ عَنْهُ وَأَكْلِهِمْ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَـٰطِلِ ۚ وَأَعْتَدْنَا لِلْكَـٰفِرِينَ مِنْهُمْ عَذَابًا أَلِيمًا','ad485b6cce6f0554f029c808b4ec090f6e914ccb469e86178f0f359b4f0e79e2',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (655,4,162,'لَّـٰكِنِ ٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ مِنْهُمْ وَٱلْمُؤْمِنُونَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ ۚ وَٱلْمُقِيمِينَ ٱلصَّلَوٰةَ ۚ وَٱلْمُؤْتُونَ ٱلزَّكَوٰةَ وَٱلْمُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ أُو۟لَـٰٓئِكَ سَنُؤْتِيهِمْ أَجْرًا عَظِيمًا','b7eb8786ee7de7cd079481c300e442bdb6cb9ca24693f13ffcc37b4b15d2ec3a',6,103,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (656,4,163,'إِنَّآ أَوْحَيْنَآ إِلَيْكَ كَمَآ أَوْحَيْنَآ إِلَىٰ نُوحٍ وَٱلنَّبِيِّـۧنَ مِنۢ بَعْدِهِۦ ۚ وَأَوْحَيْنَآ إِلَىٰٓ إِبْرَٰهِيمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَـٰرُونَ وَسُلَيْمَـٰنَ ۚ وَءَاتَيْنَا دَاوُۥدَ زَبُورًا','7ee59fb532a3d25ffe54a251a0f0c60a483469c8a6d4b1c6e4656fde17251b7d',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (657,4,164,'وَرُسُلًا قَدْ قَصَصْنَـٰهُمْ عَلَيْكَ مِن قَبْلُ وَرُسُلًا لَّمْ نَقْصُصْهُمْ عَلَيْكَ ۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكْلِيمًا','f9fce3442705227c900834ab9a01d64cb2c601b416bb74b771d4a51da17ef110',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (658,4,165,'رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا','59f68449a590891bd71e67ac1de548db5a7fa85ff9cd40b5d4a04b79df6bd0e6',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (659,4,166,'لَّـٰكِنِ ٱللَّهُ يَشْهَدُ بِمَآ أَنزَلَ إِلَيْكَ ۖ أَنزَلَهُۥ بِعِلْمِهِۦ ۖ وَٱلْمَلَـٰٓئِكَةُ يَشْهَدُونَ ۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا','0229a5f23aa8eadcf9037a2bf22f253d135f577bc33f8af94fb7bc878239adb3',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (660,4,167,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ قَدْ ضَلُّوا۟ ضَلَـٰلًۢا بَعِيدًا','6dae4f6882e5647aa71d76417d593dc1cde860dd21f888b7bbfbf25a0924e4cb',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (661,4,168,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَظَلَمُوا۟ لَمْ يَكُنِ ٱللَّهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا','855ca25919b014e67071b99c77b24a4d7034974a08b0dea73de3d74c1828e703',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (662,4,169,'إِلَّا طَرِيقَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا','90d4f508d5a6dbc324e651043f163099fb32cef8101a952af5298b9639d52ffc',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (663,4,170,'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُمُ ٱلرَّسُولُ بِٱلْحَقِّ مِن رَّبِّكُمْ فَـَٔامِنُوا۟ خَيْرًا لَّكُمْ ۚ وَإِن تَكْفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا','cdfa07754692da4532774fbbb7dce6c6f6e786935ff5a24673a744acbc598bc5',6,104,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (664,4,171,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا','dd72d57651a1b41101fadf1623eecf89dcf0b75f1d9d5079f76830ea63747668',6,105,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (665,4,172,'لَّن يَسْتَنكِفَ ٱلْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّهِ وَلَا ٱلْمَلَـٰٓئِكَةُ ٱلْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِۦ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا','1a9ff4eb61a12abed4c107b02921a92c25b7da2ac00af9795cd39de8c0249389',6,105,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (666,4,173,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِۦ ۖ وَأَمَّا ٱلَّذِينَ ٱسْتَنكَفُوا۟ وَٱسْتَكْبَرُوا۟ فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا','fd50ef7b37c29f34c5c398824a349eec45830cb4328f26975c849da56cdd2b2e',6,105,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (667,4,174,'يَـٰٓأَيُّهَا ٱلنَّاسُ قَدْ جَآءَكُم بُرْهَـٰنٌ مِّن رَّبِّكُمْ وَأَنزَلْنَآ إِلَيْكُمْ نُورًا مُّبِينًا','b0fecfe2b9d51d92160ec13f4033c7b9606a3bd78bffeb4ad8294e33e50c9dee',6,105,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (668,4,175,'فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَٱعْتَصَمُوا۟ بِهِۦ فَسَيُدْخِلُهُمْ فِى رَحْمَةٍ مِّنْهُ وَفَضْلٍ وَيَهْدِيهِمْ إِلَيْهِ صِرَٰطًا مُّسْتَقِيمًا','2139b8c7345280f31b521128328f3831b0201a792b74574fb03f06541ba5334d',6,105,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (669,4,176,'يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَـٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌۢ','a84ecd87e5bcd8f437cb5398b4a5cae83aeb11862e721ca013be0b0741c55942',6,106,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (670,5,1,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ ٱلْأَنْعَـٰمِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ غَيْرَ مُحِلِّى ٱلصَّيْدِ وَأَنتُمْ حُرُمٌ ۗ إِنَّ ٱللَّهَ يَحْكُمُ مَا يُرِيدُ','1bfadd022e0d9ee99243cbbecdc8e7116c1b5f807f15eaec85f861ee5ee2baab',6,106,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (671,5,2,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهْرَ ٱلْحَرَامَ وَلَا ٱلْهَدْىَ وَلَا ٱلْقَلَـٰٓئِدَ وَلَآ ءَآمِّينَ ٱلْبَيْتَ ٱلْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَٰنًا ۚ وَإِذَا حَلَلْتُمْ فَٱصْطَادُوا۟ ۚ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ أَن صَدُّوكُمْ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ أَن تَعْتَدُوا۟ ۘ وَتَعَاوَنُوا۟ عَلَى ٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','5d8114e51d011892f69405d2db76a42d16d41266a1b1b122497f689e5547e146',6,106,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (672,5,3,'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَـٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَـٰمَ دِينًا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ ۙ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','719d586cab5c12d7d12c8f5ed2ab7ead4b5791cc2d33956e759034c86d33b8ba',6,107,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (673,5,4,'يَسْـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمْ ۖ قُلْ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۙ وَمَا عَلَّمْتُم مِّنَ ٱلْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُ ۖ فَكُلُوا۟ مِمَّآ أَمْسَكْنَ عَلَيْكُمْ وَٱذْكُرُوا۟ ٱسْمَ ٱللَّهِ عَلَيْهِ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ','b62842945553466ea8dcc5e2b75a4e500a555f27a688c5981b08ae90c0e3c2b5',6,107,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (674,5,5,'ٱلْيَوْمَ أُحِلَّ لَكُمُ ٱلطَّيِّبَـٰتُ ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ ۖ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلْمُؤْمِنَـٰتِ وَٱلْمُحْصَنَـٰتُ مِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَـٰفِحِينَ وَلَا مُتَّخِذِىٓ أَخْدَانٍ ۗ وَمَن يَكْفُرْ بِٱلْإِيمَـٰنِ فَقَدْ حَبِطَ عَمَلُهُۥ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ','043860c99a529b118d4820ce3cd59e5943b7545c17fb99802afb922008346b7a',6,107,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (675,5,6,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَـٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ','e15d6d5aaf6c25e876f3c9fab64f29d7a25546cd792960beebd7d5cbd0099dde',6,108,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (676,5,7,'وَٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ وَمِيثَـٰقَهُ ٱلَّذِى وَاثَقَكُم بِهِۦٓ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','c00fed1abadcdc30efd5e7eb458c5db6c4616d20b9d6636ee5f311f4105aa2d6',6,108,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (677,5,8,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ','22610fbf6cc792f9eb16a4bac4a7f4dcc68ab9ea0a45460ea58c3074346d4af8',6,108,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (678,5,9,'وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ۙ لَهُم مَّغْفِرَةٌ وَأَجْرٌ عَظِيمٌ','92a9a8dddb6d1344e470fd7961b8d2528b57cc52b5bddef9acf76ee92e7b95f2',6,108,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (679,5,10,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ','245108e65d3fe0558b4ee9c58594520c0b2e3f1d97f391b1e61e684edf205f77',6,109,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (680,5,11,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ هَمَّ قَوْمٌ أَن يَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ فَكَفَّ أَيْدِيَهُمْ عَنكُمْ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ','6cef383d3cdbeb902601f009b049b31af0ea0fc27a1b6c5d2fb906a1fcf62686',6,109,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (681,5,12,'وَلَقَدْ أَخَذَ ٱللَّهُ مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَبَعَثْنَا مِنْهُمُ ٱثْنَىْ عَشَرَ نَقِيبًا ۖ وَقَالَ ٱللَّهُ إِنِّى مَعَكُمْ ۖ لَئِنْ أَقَمْتُمُ ٱلصَّلَوٰةَ وَءَاتَيْتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِى وَعَزَّرْتُمُوهُمْ وَأَقْرَضْتُمُ ٱللَّهَ قَرْضًا حَسَنًا لَّأُكَفِّرَنَّ عَنكُمْ سَيِّـَٔاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ فَمَن كَفَرَ بَعْدَ ذَٰلِكَ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ','2db98b95e0b2e9a9b0ef7f32bc01e0b2302c94a1be18b815aff8fb9207f90fbe',6,109,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (682,5,13,'فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ لَعَنَّـٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَـٰسِيَةً ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ','8b67bdc17a944f571f3a9fda0d7c72ad6800b4f67d7a1444af2cce8096921fa5',6,109,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (683,5,14,'وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰٓ أَخَذْنَا مِيثَـٰقَهُمْ فَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ','d74184512325e8b3192bd890b7ebcfcc10a2950e27b65797f6b9cd1620ca5f7f',6,110,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (684,5,15,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ كَثِيرًا مِّمَّا كُنتُمْ تُخْفُونَ مِنَ ٱلْكِتَـٰبِ وَيَعْفُوا۟ عَن كَثِيرٍ ۚ قَدْ جَآءَكُم مِّنَ ٱللَّهِ نُورٌ وَكِتَـٰبٌ مُّبِينٌ','1afe478b7102c7d2c823293c0f4010067cb7242f4e36c446233ac4accbfac221',6,110,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (685,5,16,'يَهْدِى بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضْوَٰنَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَيُخْرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذْنِهِۦ وَيَهْدِيهِمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','8831c3406e5775ae73e6cd4296ad43ce19cc4652ed84cb1fa9bdb69d8e7f981e',6,110,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (686,5,17,'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۚ قُلْ فَمَن يَمْلِكُ مِنَ ٱللَّهِ شَيْـًٔا إِنْ أَرَادَ أَن يُهْلِكَ ٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَأُمَّهُۥ وَمَن فِى ٱلْأَرْضِ جَمِيعًا ۗ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۚ يَخْلُقُ مَا يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','ef9527d008a8acc775746854b6340e4154b8d144e94345af99dc71ff51851139',6,110,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (687,5,18,'وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَـٰرَىٰ نَحْنُ أَبْنَـٰٓؤُا۟ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ','124ce77f0727cc1d7d96321c299209e2daa811125b27e7eb1c2fddbf3633d143',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (688,5,19,'يَـٰٓأَهْلَ ٱلْكِتَـٰبِ قَدْ جَآءَكُمْ رَسُولُنَا يُبَيِّنُ لَكُمْ عَلَىٰ فَتْرَةٍ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَآءَنَا مِنۢ بَشِيرٍ وَلَا نَذِيرٍ ۖ فَقَدْ جَآءَكُم بَشِيرٌ وَنَذِيرٌ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','ac06244f7bec70f034d90029235b3a80d51f2d64818399a569ebaea97b0737d8',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (689,5,20,'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنۢبِيَآءَ وَجَعَلَكُم مُّلُوكًا وَءَاتَىٰكُم مَّا لَمْ يُؤْتِ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ','7662096209b5dc152441d759b428df4be0158e565b0330ec92d34e7499c01714',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (690,5,21,'يَـٰقَوْمِ ٱدْخُلُوا۟ ٱلْأَرْضَ ٱلْمُقَدَّسَةَ ٱلَّتِى كَتَبَ ٱللَّهُ لَكُمْ وَلَا تَرْتَدُّوا۟ عَلَىٰٓ أَدْبَارِكُمْ فَتَنقَلِبُوا۟ خَـٰسِرِينَ','4c2ed909536d1a044eaa57ec1096d383177fea9663e4a0885276f718dda47eec',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (691,5,22,'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَن نَّدْخُلَهَا حَتَّىٰ يَخْرُجُوا۟ مِنْهَا فَإِن يَخْرُجُوا۟ مِنْهَا فَإِنَّا دَٰخِلُونَ','6badfdfef548fc5fc017689171339d0711143bd3aa3729c3903062d7dd76b9fa',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (692,5,23,'قَالَ رَجُلَانِ مِنَ ٱلَّذِينَ يَخَافُونَ أَنْعَمَ ٱللَّهُ عَلَيْهِمَا ٱدْخُلُوا۟ عَلَيْهِمُ ٱلْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَـٰلِبُونَ ۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوٓا۟ إِن كُنتُم مُّؤْمِنِينَ','9ddfa853a7ea4b2cfc7383cf34629264af4b9b132395a76a59b1a5ff350dfa7d',6,111,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (693,5,24,'قَالُوا۟ يَـٰمُوسَىٰٓ إِنَّا لَن نَّدْخُلَهَآ أَبَدًا مَّا دَامُوا۟ فِيهَا ۖ فَٱذْهَبْ أَنتَ وَرَبُّكَ فَقَـٰتِلَآ إِنَّا هَـٰهُنَا قَـٰعِدُونَ','3899387491028a7e02184108c724491d149a0f6b3ad29bed0be8a09850bb607f',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (694,5,25,'قَالَ رَبِّ إِنِّى لَآ أَمْلِكُ إِلَّا نَفْسِى وَأَخِى ۖ فَٱفْرُقْ بَيْنَنَا وَبَيْنَ ٱلْقَوْمِ ٱلْفَـٰسِقِينَ','71b4e1af230ef194f230eca78e9327acef8d6c0c47518f6abc9127931abf5f96',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (695,5,26,'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ ۛ أَرْبَعِينَ سَنَةً ۛ يَتِيهُونَ فِى ٱلْأَرْضِ ۚ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْفَـٰسِقِينَ','f737b7844464e3d9317e3a580c5359c0cc8e3bbd490908ebb337244d1a97dcab',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (696,5,27,'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱبْنَىْ ءَادَمَ بِٱلْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ ٱلْـَٔاخَرِ قَالَ لَأَقْتُلَنَّكَ ۖ قَالَ إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلْمُتَّقِينَ','046b86fffe5a751c1a815030b51c126f9d865740056ad1158e4e75a48c5426b6',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (697,5,28,'لَئِنۢ بَسَطتَ إِلَىَّ يَدَكَ لِتَقْتُلَنِى مَآ أَنَا۠ بِبَاسِطٍ يَدِىَ إِلَيْكَ لِأَقْتُلَكَ ۖ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ','b9c515e8a7d45d4254a0adb19438a82ab85d20faead8bde7a70f5b9ebab2bbe8',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (698,5,29,'إِنِّىٓ أُرِيدُ أَن تَبُوٓأَ بِإِثْمِى وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَـٰبِ ٱلنَّارِ ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ','9af92b942a1c50ca182911af583318502ad3533145f1af676a5a7c739cfd725a',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (699,5,30,'فَطَوَّعَتْ لَهُۥ نَفْسُهُۥ قَتْلَ أَخِيهِ فَقَتَلَهُۥ فَأَصْبَحَ مِنَ ٱلْخَـٰسِرِينَ','31bcdf4e6c32afa452c71b4541b31781378f64b0620c5516cbef67cd2076aff4',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (700,5,31,'فَبَعَثَ ٱللَّهُ غُرَابًا يَبْحَثُ فِى ٱلْأَرْضِ لِيُرِيَهُۥ كَيْفَ يُوَٰرِى سَوْءَةَ أَخِيهِ ۚ قَالَ يَـٰوَيْلَتَىٰٓ أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَـٰذَا ٱلْغُرَابِ فَأُوَٰرِىَ سَوْءَةَ أَخِى ۖ فَأَصْبَحَ مِنَ ٱلنَّـٰدِمِينَ','3b1e3a1dda52f95960ce756d34e58ce8a1354ff27ffeb10437eddc7e998a1bda',6,112,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (701,5,32,'مِنْ أَجْلِ ذَٰلِكَ كَتَبْنَا عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنَّهُۥ مَن قَتَلَ نَفْسًۢا بِغَيْرِ نَفْسٍ أَوْ فَسَادٍ فِى ٱلْأَرْضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِيعًا وَمَنْ أَحْيَاهَا فَكَأَنَّمَآ أَحْيَا ٱلنَّاسَ جَمِيعًا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُنَا بِٱلْبَيِّنَـٰتِ ثُمَّ إِنَّ كَثِيرًا مِّنْهُم بَعْدَ ذَٰلِكَ فِى ٱلْأَرْضِ لَمُسْرِفُونَ','4650c4e13ce232d936eda38ca03d650f11d951836cf73baf50e477c99055282f',6,113,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (702,5,33,'إِنَّمَا جَزَٰٓؤُا۟ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا أَن يُقَتَّلُوٓا۟ أَوْ يُصَلَّبُوٓا۟ أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَـٰفٍ أَوْ يُنفَوْا۟ مِنَ ٱلْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْىٌ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ','71b6d88ad54704e9bcea46bd2a2b816d631332b5a097aead0630bfab532be995',6,113,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (703,5,34,'إِلَّا ٱلَّذِينَ تَابُوا۟ مِن قَبْلِ أَن تَقْدِرُوا۟ عَلَيْهِمْ ۖ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','629d0f5f0aaabbf71115889fe26a0ee11d7c25c452b7805909dc5d19161c7e15',6,113,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (704,5,35,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبْتَغُوٓا۟ إِلَيْهِ ٱلْوَسِيلَةَ وَجَـٰهِدُوا۟ فِى سَبِيلِهِۦ لَعَلَّكُمْ تُفْلِحُونَ','6909e5158d1cf24c61625805c2ad16f2a85ccea258299f0729090cb574f6d6ea',6,113,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (705,5,36,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَـٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ','7ec19861226b4964817d5fb1fc3cd19dd44cd41dd4a9227793f1cc67531cefe7',6,113,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (706,5,37,'يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَـٰرِجِينَ مِنْهَا ۖ وَلَهُمْ عَذَابٌ مُّقِيمٌ','4e6ca9e012f2b697e218119ee9931dbc307b654bdaaa0c93dadb2dbedf518425',6,114,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (707,5,38,'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقْطَعُوٓا۟ أَيْدِيَهُمَا جَزَآءًۢ بِمَا كَسَبَا نَكَـٰلًا مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','e1429e6affba9a339d38337ec847d7d88506a373a29f52faaf4a182a12e83776',6,114,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (708,5,39,'فَمَن تَابَ مِنۢ بَعْدِ ظُلْمِهِۦ وَأَصْلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيْهِ ۗ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','d63cadf150720af9265f5bda6db28ac21a9b62a5b77fb8cefcbe9a5a9c10428c',6,114,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (709,5,40,'أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ يُعَذِّبُ مَن يَشَآءُ وَيَغْفِرُ لِمَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','a34ff3e11067ed39fe6c7bbffd1de484fd4c3d36fbf04930610d331c2faa1bc9',6,114,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (710,5,41,'يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحْزُنكَ ٱلَّذِينَ يُسَـٰرِعُونَ فِى ٱلْكُفْرِ مِنَ ٱلَّذِينَ قَالُوٓا۟ ءَامَنَّا بِأَفْوَٰهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ ۛ وَمِنَ ٱلَّذِينَ هَادُوا۟ ۛ سَمَّـٰعُونَ لِلْكَذِبِ سَمَّـٰعُونَ لِقَوْمٍ ءَاخَرِينَ لَمْ يَأْتُوكَ ۖ يُحَرِّفُونَ ٱلْكَلِمَ مِنۢ بَعْدِ مَوَاضِعِهِۦ ۖ يَقُولُونَ إِنْ أُوتِيتُمْ هَـٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَٱحْذَرُوا۟ ۚ وَمَن يُرِدِ ٱللَّهُ فِتْنَتَهُۥ فَلَن تَمْلِكَ لَهُۥ مِنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَمْ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمْ ۚ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ','f388abb6ae878316a6cfe1d2e2f63083a5de86e5d879708c260f8512ea5d83e3',6,114,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (711,5,42,'سَمَّـٰعُونَ لِلْكَذِبِ أَكَّـٰلُونَ لِلسُّحْتِ ۚ فَإِن جَآءُوكَ فَٱحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ۖ وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْـًٔا ۖ وَإِنْ حَكَمْتَ فَٱحْكُم بَيْنَهُم بِٱلْقِسْطِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ','50e0b77a161689475467cd0b5cfe29b19f138d112b738da17452535cb15d9ed4',6,115,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (712,5,43,'وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوْرَىٰةُ فِيهَا حُكْمُ ٱللَّهِ ثُمَّ يَتَوَلَّوْنَ مِنۢ بَعْدِ ذَٰلِكَ ۚ وَمَآ أُو۟لَـٰٓئِكَ بِٱلْمُؤْمِنِينَ','23e754271debfa16e5e1835a79d82561b32cc19a0bae0eb3f9bd36a8d1ec3afc',6,115,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (713,5,44,'إِنَّآ أَنزَلْنَا ٱلتَّوْرَىٰةَ فِيهَا هُدًى وَنُورٌ ۚ يَحْكُمُ بِهَا ٱلنَّبِيُّونَ ٱلَّذِينَ أَسْلَمُوا۟ لِلَّذِينَ هَادُوا۟ وَٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ بِمَا ٱسْتُحْفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَيْهِ شُهَدَآءَ ۚ فَلَا تَخْشَوُا۟ ٱلنَّاسَ وَٱخْشَوْنِ وَلَا تَشْتَرُوا۟ بِـَٔايَـٰتِى ثَمَنًا قَلِيلًا ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْكَـٰفِرُونَ','f158e2064e536aa45f3210609c6a47e0796c10e8d5815f321315dcff5b7a71c7',6,115,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (714,5,45,'وَكَتَبْنَا عَلَيْهِمْ فِيهَآ أَنَّ ٱلنَّفْسَ بِٱلنَّفْسِ وَٱلْعَيْنَ بِٱلْعَيْنِ وَٱلْأَنفَ بِٱلْأَنفِ وَٱلْأُذُنَ بِٱلْأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلْجُرُوحَ قِصَاصٌ ۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةٌ لَّهُۥ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ','3fee573f2120e39f6dd96ad2c6cde85ebfea4cabda07f716ce6c9fe24690f039',6,115,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (715,5,46,'وَقَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِعِيسَى ٱبْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ ۖ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلتَّوْرَىٰةِ وَهُدًى وَمَوْعِظَةً لِّلْمُتَّقِينَ','a83be307602342bc7737bbc272dc2af95947e3ea43459a0e6849db3cc846b9e9',6,116,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (716,5,47,'وَلْيَحْكُمْ أَهْلُ ٱلْإِنجِيلِ بِمَآ أَنزَلَ ٱللَّهُ فِيهِ ۚ وَمَن لَّمْ يَحْكُم بِمَآ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ','461f03d5b556a13195596b79aa096bbd68cac96bd9278d8f894dbe3406f8a0e4',6,116,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (717,5,48,'وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَـٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','1860bf9ff3c5e229afa875b38d46b4c21158090f180327938e2bd92bc4b8155c',6,116,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (718,5,49,'وَأَنِ ٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَٱحْذَرْهُمْ أَن يَفْتِنُوكَ عَنۢ بَعْضِ مَآ أَنزَلَ ٱللَّهُ إِلَيْكَ ۖ فَإِن تَوَلَّوْا۟ فَٱعْلَمْ أَنَّمَا يُرِيدُ ٱللَّهُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ ۗ وَإِنَّ كَثِيرًا مِّنَ ٱلنَّاسِ لَفَـٰسِقُونَ','9a4a6cc8adf2b4ce73077bb34d9f1b2c6a49eb108865b2c964bda4a3c5cec736',6,116,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (719,5,50,'أَفَحُكْمَ ٱلْجَـٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ','7bfa19ee5e7b18c4dce607c93d8bd6ff13f6a2761c3e01915d7b3648e177d3c6',6,116,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (720,5,51,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلْيَهُودَ وَٱلنَّصَـٰرَىٰٓ أَوْلِيَآءَ ۘ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَمَن يَتَوَلَّهُم مِّنكُمْ فَإِنَّهُۥ مِنْهُمْ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','06bae745e3f1c990b585f9125bb291ad971f50144e9ea4fd42367518e7cabace',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (721,5,52,'فَتَرَى ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ يُسَـٰرِعُونَ فِيهِمْ يَقُولُونَ نَخْشَىٰٓ أَن تُصِيبَنَا دَآئِرَةٌ ۚ فَعَسَى ٱللَّهُ أَن يَأْتِىَ بِٱلْفَتْحِ أَوْ أَمْرٍ مِّنْ عِندِهِۦ فَيُصْبِحُوا۟ عَلَىٰ مَآ أَسَرُّوا۟ فِىٓ أَنفُسِهِمْ نَـٰدِمِينَ','37542a848388f0f8af41a5f6dd9c23589a5b28545a03e663b45afbdfb00fec6b',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (722,5,53,'وَيَقُولُ ٱلَّذِينَ ءَامَنُوٓا۟ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ ۙ إِنَّهُمْ لَمَعَكُمْ ۚ حَبِطَتْ أَعْمَـٰلُهُمْ فَأَصْبَحُوا۟ خَـٰسِرِينَ','51a54301571cfc3d57c208ad2be5505882fb5a217888903d1a25be90110d674b',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (723,5,54,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ مَن يَرْتَدَّ مِنكُمْ عَن دِينِهِۦ فَسَوْفَ يَأْتِى ٱللَّهُ بِقَوْمٍ يُحِبُّهُمْ وَيُحِبُّونَهُۥٓ أَذِلَّةٍ عَلَى ٱلْمُؤْمِنِينَ أَعِزَّةٍ عَلَى ٱلْكَـٰفِرِينَ يُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ وَلَا يَخَافُونَ لَوْمَةَ لَآئِمٍ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ','466de453348966ccaf8a473b0b7ef193043683c6791fe61d3250c2b0cb30f38d',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (724,5,55,'إِنَّمَا وَلِيُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُمْ رَٰكِعُونَ','bc9022bbc063d00dcac60b35747e09bfe227777d82e3f173aaf58e74a932ecea',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (725,5,56,'وَمَن يَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِينَ ءَامَنُوا۟ فَإِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْغَـٰلِبُونَ','03569a2b1c823d8dd318d5120ab9cfa2fe725ec5d4e15023e3e28a273ab7e1ce',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (726,5,57,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَكُمْ هُزُوًا وَلَعِبًا مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلِكُمْ وَٱلْكُفَّارَ أَوْلِيَآءَ ۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ','bf098d695a9b9aee15e52c1a787953163d4cedc3fc94b517cefd5a6e3577995a',6,117,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (727,5,58,'وَإِذَا نَادَيْتُمْ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوًا وَلَعِبًا ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ','e523a16ee6c03484dee3e2bb5fecc0272ed3c5beb572cf5370e588da9296e608',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (728,5,59,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ هَلْ تَنقِمُونَ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ مِن قَبْلُ وَأَنَّ أَكْثَرَكُمْ فَـٰسِقُونَ','524355822bd24ca1289a62758c13bfcdc2c02323c64c246f39dd7f24ef9630ab',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (729,5,60,'قُلْ هَلْ أُنَبِّئُكُم بِشَرٍّ مِّن ذَٰلِكَ مَثُوبَةً عِندَ ٱللَّهِ ۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَيْهِ وَجَعَلَ مِنْهُمُ ٱلْقِرَدَةَ وَٱلْخَنَازِيرَ وَعَبَدَ ٱلطَّـٰغُوتَ ۚ أُو۟لَـٰٓئِكَ شَرٌّ مَّكَانًا وَأَضَلُّ عَن سَوَآءِ ٱلسَّبِيلِ','8e5d3c462ca634a8ca7e6b435f22198a427abb994d50213166f24b0afd06b82e',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (730,5,61,'وَإِذَا جَآءُوكُمْ قَالُوٓا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلْكُفْرِ وَهُمْ قَدْ خَرَجُوا۟ بِهِۦ ۚ وَٱللَّهُ أَعْلَمُ بِمَا كَانُوا۟ يَكْتُمُونَ','79b713b7d9b8a44975d21bf7b3e94c76897133e262fb0c9a6a403ff9a4e04f8c',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (731,5,62,'وَتَرَىٰ كَثِيرًا مِّنْهُمْ يُسَـٰرِعُونَ فِى ٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَعْمَلُونَ','aae193e35613aaf1e947ed75032b2c0dc0246e96d43a5fa8429e3c5e183b8c02',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (732,5,63,'لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّـٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ','f6e14513dbde8ce18336c73e989b63c25a60a154349b54c111369b7fa03a9282',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (733,5,64,'وَقَالَتِ ٱلْيَهُودُ يَدُ ٱللَّهِ مَغْلُولَةٌ ۚ غُلَّتْ أَيْدِيهِمْ وَلُعِنُوا۟ بِمَا قَالُوا۟ ۘ بَلْ يَدَاهُ مَبْسُوطَتَانِ يُنفِقُ كَيْفَ يَشَآءُ ۚ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۚ وَأَلْقَيْنَا بَيْنَهُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۚ كُلَّمَآ أَوْقَدُوا۟ نَارًا لِّلْحَرْبِ أَطْفَأَهَا ٱللَّهُ ۚ وَيَسْعَوْنَ فِى ٱلْأَرْضِ فَسَادًا ۚ وَٱللَّهُ لَا يُحِبُّ ٱلْمُفْسِدِينَ','a40aab1d84fc7c2e3b0f5a70030273f20fe1ce5cdfdb9da945fff11e68107c25',6,118,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (734,5,65,'وَلَوْ أَنَّ أَهْلَ ٱلْكِتَـٰبِ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَكَفَّرْنَا عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأَدْخَلْنَـٰهُمْ جَنَّـٰتِ ٱلنَّعِيمِ','ad985b0289343ff021c14a713f32a885b80641603417a0a5e8b929a80e135c2c',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (735,5,66,'وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌ مُّقْتَصِدَةٌ ۖ وَكَثِيرٌ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ','a9fceda2c4c33f1a9a08cd465b50c7ebac675911cf409d954f90cc6593be8546',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (736,5,67,'يَـٰٓأَيُّهَا ٱلرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ ۖ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُۥ ۚ وَٱللَّهُ يَعْصِمُكَ مِنَ ٱلنَّاسِ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَـٰفِرِينَ','54c012639afcc2195a3ee5a9f12b95e0afe3a870aee7a445b617a3beab2540d3',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (737,5,68,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَسْتُمْ عَلَىٰ شَىْءٍ حَتَّىٰ تُقِيمُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ ۗ وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَـٰنًا وَكُفْرًا ۖ فَلَا تَأْسَ عَلَى ٱلْقَوْمِ ٱلْكَـٰفِرِينَ','5e8010ec9a442f379d1f233d65653f8ec6d50df10bf7a079373c9114a5407140',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (738,5,69,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَـٰرَىٰ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَـٰلِحًا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','ba3cf7dcf6a09c6c7806d4c0a5757abc812b27f0b369e114d5f15c5e432e6f14',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (739,5,70,'لَقَدْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ وَأَرْسَلْنَآ إِلَيْهِمْ رُسُلًا ۖ كُلَّمَا جَآءَهُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُهُمْ فَرِيقًا كَذَّبُوا۟ وَفَرِيقًا يَقْتُلُونَ','b15c4e79205d8c3897066f5391a8e5ae978f2fecf75d94707ce72aa177732b12',6,119,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (740,5,71,'وَحَسِبُوٓا۟ أَلَّا تَكُونَ فِتْنَةٌ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَيْهِمْ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِيرٌ مِّنْهُمْ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ','96814b02246aa6cd2b4f4dc068845a29f830d640b13480d8c85fdf3679bc1620',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (741,5,72,'لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ','9ab5faa974f403c4656d8b55f530eff5cf20d913b0716bbfb8c391b5b3f61744',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (742,5,73,'لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةٍ ۘ وَمَا مِنْ إِلَـٰهٍ إِلَّآ إِلَـٰهٌ وَٰحِدٌ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ','4a9347a3acdb44b493e8c75d5258981460234e8f051fc926d058b1126e0f6787',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (743,5,74,'أَفَلَا يَتُوبُونَ إِلَى ٱللَّهِ وَيَسْتَغْفِرُونَهُۥ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','8a2f9b2b6479fb83d9b10574bc8997bfbc76239d692f27f48562bb95259d6587',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (744,5,75,'مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَـٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ','054cf9860641e245e5bb08245210ca875c4004b30ae2d1543e0a55a482be6f96',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (745,5,76,'قُلْ أَتَعْبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمْلِكُ لَكُمْ ضَرًّا وَلَا نَفْعًا ۚ وَٱللَّهُ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','2c3c6d5f7dab573c9edf1cc967402a1f0c034bc38a4591649d86bf43e47992c3',6,120,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (746,5,77,'قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ','3a17069571e259658ca97990f2fd3a33fc0c903efbe4c545aa6afb9bbcdc2326',6,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (747,5,78,'لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ','7b7034fe41308c331987ced7b20d4b2b9e5b917f35c226060e1c78b0c5f45daf',6,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (748,5,79,'كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ','cacd357fc29fe50f1f7cf6b8fa8e1b0dd2e967bce52ced0549e649448e926900',6,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (749,5,80,'تَرَىٰ كَثِيرًا مِّنْهُمْ يَتَوَلَّوْنَ ٱلَّذِينَ كَفَرُوا۟ ۚ لَبِئْسَ مَا قَدَّمَتْ لَهُمْ أَنفُسُهُمْ أَن سَخِطَ ٱللَّهُ عَلَيْهِمْ وَفِى ٱلْعَذَابِ هُمْ خَـٰلِدُونَ','3cdbeda6c6480b1acd7fff85a6389bac0208cb48fdafcda7505a73ea6093a8bb',6,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (750,5,81,'وَلَوْ كَانُوا۟ يُؤْمِنُونَ بِٱللَّهِ وَٱلنَّبِىِّ وَمَآ أُنزِلَ إِلَيْهِ مَا ٱتَّخَذُوهُمْ أَوْلِيَآءَ وَلَـٰكِنَّ كَثِيرًا مِّنْهُمْ فَـٰسِقُونَ','a140064eaf31850222ca3134c7fe4f1b17e1940efb0c1264d08190351870e459',6,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (751,5,82,'لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَٰوَةً لِّلَّذِينَ ءَامَنُوا۟ ٱلْيَهُودَ وَٱلَّذِينَ أَشْرَكُوا۟ ۖ وَلَتَجِدَنَّ أَقْرَبَهُم مَّوَدَّةً لِّلَّذِينَ ءَامَنُوا۟ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَـٰرَىٰ ۚ ذَٰلِكَ بِأَنَّ مِنْهُمْ قِسِّيسِينَ وَرُهْبَانًا وَأَنَّهُمْ لَا يَسْتَكْبِرُونَ','9e801a5f1847d1b453fe4d265062cf444ef74ba3da78134503a18ef707fe084e',7,121,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (752,5,83,'وَإِذَا سَمِعُوا۟ مَآ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰٓ أَعْيُنَهُمْ تَفِيضُ مِنَ ٱلدَّمْعِ مِمَّا عَرَفُوا۟ مِنَ ٱلْحَقِّ ۖ يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱكْتُبْنَا مَعَ ٱلشَّـٰهِدِينَ','5f61f627c181d954de68997f79a35c49282932d78f7acf07d8642c90deea6234',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (753,5,84,'وَمَا لَنَا لَا نُؤْمِنُ بِٱللَّهِ وَمَا جَآءَنَا مِنَ ٱلْحَقِّ وَنَطْمَعُ أَن يُدْخِلَنَا رَبُّنَا مَعَ ٱلْقَوْمِ ٱلصَّـٰلِحِينَ','bd8edaecd8dd8878daa2c12b9ca7bc93c9e895870739c6be090ab9d22669e730',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (754,5,85,'فَأَثَـٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ وَذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ','1a363a749fc250700ead9e5bc0bba776e0716cc237a489b8e87033f57013c56b',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (755,5,86,'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ','245108e65d3fe0558b4ee9c58594520c0b2e3f1d97f391b1e61e684edf205f77',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (756,5,87,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَيِّبَـٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوٓا۟ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ','f8c4c3aacd39a69b7e3a12cde6c3e451e4375e6eaedd176f4dafcef013cee774',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (757,5,88,'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ','488caa6d819bcff560a0752a8a2e2089b94193d44c7c91aa2ceb2279c0465506',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (758,5,89,'لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَـٰنِكُمْ وَلَـٰكِن يُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلْأَيْمَـٰنَ ۖ فَكَفَّـٰرَتُهُۥٓ إِطْعَامُ عَشَرَةِ مَسَـٰكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ ۖ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ ۚ ذَٰلِكَ كَفَّـٰرَةُ أَيْمَـٰنِكُمْ إِذَا حَلَفْتُمْ ۚ وَٱحْفَظُوٓا۟ أَيْمَـٰنَكُمْ ۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَـٰتِهِۦ لَعَلَّكُمْ تَشْكُرُونَ','efd5966cb920fec23f3cbd3dfe3484952a57fb37e76a1fc566b0b452b20990f9',7,122,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (759,5,90,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَـٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَـٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ','c12b0b3e444a641931359eea0304e34b9e6f0709c10ea3c91c0302a9a312e51e',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (760,5,91,'إِنَّمَا يُرِيدُ ٱلشَّيْطَـٰنُ أَن يُوقِعَ بَيْنَكُمُ ٱلْعَدَٰوَةَ وَٱلْبَغْضَآءَ فِى ٱلْخَمْرِ وَٱلْمَيْسِرِ وَيَصُدَّكُمْ عَن ذِكْرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِ ۖ فَهَلْ أَنتُم مُّنتَهُونَ','f5a299413dd53cb9fa17753a33b077ac86bc1064a343e772156778fa0692eaf7',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (761,5,92,'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ','f7b045a842d5f4cd71c0487fcda3c03c6446f524503dcb3f8a21f02db51b092f',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (762,5,93,'لَيْسَ عَلَى ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جُنَاحٌ فِيمَا طَعِمُوٓا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحْسَنُوا۟ ۗ وَٱللَّهُ يُحِبُّ ٱلْمُحْسِنِينَ','a07a8f1f4e4e7c6233af0a591cdaa746592ba82213636e5c36ec092aea96de76',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (763,5,94,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَيَبْلُوَنَّكُمُ ٱللَّهُ بِشَىْءٍ مِّنَ ٱلصَّيْدِ تَنَالُهُۥٓ أَيْدِيكُمْ وَرِمَاحُكُمْ لِيَعْلَمَ ٱللَّهُ مَن يَخَافُهُۥ بِٱلْغَيْبِ ۚ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ','56393c4f91698e50987ac89a61cd8fa85e4c082a0d449d49015e578d0077c346',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (764,5,95,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْتُلُوا۟ ٱلصَّيْدَ وَأَنتُمْ حُرُمٌ ۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدًا فَجَزَآءٌ مِّثْلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ يَحْكُمُ بِهِۦ ذَوَا عَدْلٍ مِّنكُمْ هَدْيًۢا بَـٰلِغَ ٱلْكَعْبَةِ أَوْ كَفَّـٰرَةٌ طَعَامُ مَسَـٰكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِۦ ۗ عَفَا ٱللَّهُ عَمَّا سَلَفَ ۚ وَمَنْ عَادَ فَيَنتَقِمُ ٱللَّهُ مِنْهُ ۗ وَٱللَّهُ عَزِيزٌ ذُو ٱنتِقَامٍ','c03bc11d6a024ae68c0848213409348c70e0e1806ca2ee45163c90070d82d1c5',7,123,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (765,5,96,'أُحِلَّ لَكُمْ صَيْدُ ٱلْبَحْرِ وَطَعَامُهُۥ مَتَـٰعًا لَّكُمْ وَلِلسَّيَّارَةِ ۖ وَحُرِّمَ عَلَيْكُمْ صَيْدُ ٱلْبَرِّ مَا دُمْتُمْ حُرُمًا ۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ','328329d6fd85d13509008ea3c9eaa01f464cbd9f2c7921df9a398c1d2b1d1e35',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (766,5,97,'جَعَلَ ٱللَّهُ ٱلْكَعْبَةَ ٱلْبَيْتَ ٱلْحَرَامَ قِيَـٰمًا لِّلنَّاسِ وَٱلشَّهْرَ ٱلْحَرَامَ وَٱلْهَدْىَ وَٱلْقَلَـٰٓئِدَ ۚ ذَٰلِكَ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ','19bbb35fb625002a9865e6de6f01c71882d4d6fda4e42894e88f799f555bc7e8',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (767,5,98,'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ وَأَنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','5ec4ec966a48c9aa89299437e9b6cf9607c10283ebe6c77b72ace5ed345f824a',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (768,5,99,'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَـٰغُ ۗ وَٱللَّهُ يَعْلَمُ مَا تُبْدُونَ وَمَا تَكْتُمُونَ','f412ddb0c9a1a9c6a9aae2e13fe97550a9b0514e1304c32e46f30796da29c7ce',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (769,5,100,'قُل لَّا يَسْتَوِى ٱلْخَبِيثُ وَٱلطَّيِّبُ وَلَوْ أَعْجَبَكَ كَثْرَةُ ٱلْخَبِيثِ ۚ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ لَعَلَّكُمْ تُفْلِحُونَ','cb62d436318727a528a6e39616013fe7b07f93680a7bafe5a8cd3689d38fa4a5',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (770,5,101,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِن تَسْـَٔلُوا۟ عَنْهَا حِينَ يُنَزَّلُ ٱلْقُرْءَانُ تُبْدَ لَكُمْ عَفَا ٱللَّهُ عَنْهَا ۗ وَٱللَّهُ غَفُورٌ حَلِيمٌ','895e01e5d2c394f4511877dc3b3521de0db45709c022cd997344829bd3be38b4',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (771,5,102,'قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا۟ بِهَا كَـٰفِرِينَ','54f13bb427232b4cc236604f2bcdf9da6635388e2d87ea8bc6fb8208681f65ca',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (772,5,103,'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِيرَةٍ وَلَا سَآئِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ ۙ وَلَـٰكِنَّ ٱلَّذِينَ كَفَرُوا۟ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ ۖ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ','aec0223b2f2f614f72a282347388fdcaf1c14bcf88dba162f41294f383ab5ed4',7,124,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (773,5,104,'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًٔا وَلَا يَهْتَدُونَ','8a88e98181e5c06660caa36117afa797113e0dce9133f62a6d0c353d9b7840f4',7,125,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (774,5,105,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ عَلَيْكُمْ أَنفُسَكُمْ ۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','1d5dfac8ad249c9bfae3a07598fe0efc84aeba725f6c0d2bcf866cbea2fd1c46',7,125,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (775,5,106,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ شَهَـٰدَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ أَوْ ءَاخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِى ٱلْأَرْضِ فَأَصَـٰبَتْكُم مُّصِيبَةُ ٱلْمَوْتِ ۚ تَحْبِسُونَهُمَا مِنۢ بَعْدِ ٱلصَّلَوٰةِ فَيُقْسِمَانِ بِٱللَّهِ إِنِ ٱرْتَبْتُمْ لَا نَشْتَرِى بِهِۦ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ ۙ وَلَا نَكْتُمُ شَهَـٰدَةَ ٱللَّهِ إِنَّآ إِذًا لَّمِنَ ٱلْـَٔاثِمِينَ','572d65cb08cbf05f5e574bbfa9e93595da1453ae73b5fab025bad0318c247adf',7,125,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (776,5,107,'فَإِنْ عُثِرَ عَلَىٰٓ أَنَّهُمَا ٱسْتَحَقَّآ إِثْمًا فَـَٔاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِينَ ٱسْتَحَقَّ عَلَيْهِمُ ٱلْأَوْلَيَـٰنِ فَيُقْسِمَانِ بِٱللَّهِ لَشَهَـٰدَتُنَآ أَحَقُّ مِن شَهَـٰدَتِهِمَا وَمَا ٱعْتَدَيْنَآ إِنَّآ إِذًا لَّمِنَ ٱلظَّـٰلِمِينَ','d5baa8b00f0205e8e0c37dfcaa8341b2cd5a56e7f2e21703dda5ca25b4188c3a',7,125,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (777,5,108,'ذَٰلِكَ أَدْنَىٰٓ أَن يَأْتُوا۟ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجْهِهَآ أَوْ يَخَافُوٓا۟ أَن تُرَدَّ أَيْمَـٰنٌۢ بَعْدَ أَيْمَـٰنِهِمْ ۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسْمَعُوا۟ ۗ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ','846cbd3b4aac3aec73a999ebacb5dfbf163212da3c7ebf7bf6a0ae6dd1b3e69e',7,125,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (778,5,109,'يَوْمَ يَجْمَعُ ٱللَّهُ ٱلرُّسُلَ فَيَقُولُ مَاذَآ أُجِبْتُمْ ۖ قَالُوا۟ لَا عِلْمَ لَنَآ ۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ','7eb01733fecb2a9d15385b171200574fbed4b556f75f5b59dcdd3fc26dc1a6d4',7,126,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (779,5,110,'إِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ٱذْكُرْ نِعْمَتِى عَلَيْكَ وَعَلَىٰ وَٰلِدَتِكَ إِذْ أَيَّدتُّكَ بِرُوحِ ٱلْقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِى ٱلْمَهْدِ وَكَهْلًا ۖ وَإِذْ عَلَّمْتُكَ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ ۖ وَإِذْ تَخْلُقُ مِنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ بِإِذْنِى فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًۢا بِإِذْنِى ۖ وَتُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ بِإِذْنِى ۖ وَإِذْ تُخْرِجُ ٱلْمَوْتَىٰ بِإِذْنِى ۖ وَإِذْ كَفَفْتُ بَنِىٓ إِسْرَٰٓءِيلَ عَنكَ إِذْ جِئْتَهُم بِٱلْبَيِّنَـٰتِ فَقَالَ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ','9fc3eeeb3ece64dc5cdbaf27697f6d4053fad0566ba83aaba77baaf52e1e161f',7,126,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (780,5,111,'وَإِذْ أَوْحَيْتُ إِلَى ٱلْحَوَارِيِّـۧنَ أَنْ ءَامِنُوا۟ بِى وَبِرَسُولِى قَالُوٓا۟ ءَامَنَّا وَٱشْهَدْ بِأَنَّنَا مُسْلِمُونَ','52c8542afe4217cb25102db1d153b9a45d8ae917e39c40880d6de99126c1e9c3',7,126,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (781,5,112,'إِذْ قَالَ ٱلْحَوَارِيُّونَ يَـٰعِيسَى ٱبْنَ مَرْيَمَ هَلْ يَسْتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ ۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤْمِنِينَ','7a4e05a0d1d4688ffe3f1b96db2cac39b93dbb84e5040f03545b579b8b252e61',7,126,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (782,5,113,'قَالُوا۟ نُرِيدُ أَن نَّأْكُلَ مِنْهَا وَتَطْمَئِنَّ قُلُوبُنَا وَنَعْلَمَ أَن قَدْ صَدَقْتَنَا وَنَكُونَ عَلَيْهَا مِنَ ٱلشَّـٰهِدِينَ','ec1ff6d805e121976f301f2294941b32254b0a97d4cc155f18c4a12edba8fa46',7,126,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (783,5,114,'قَالَ عِيسَى ٱبْنُ مَرْيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلْ عَلَيْنَا مَآئِدَةً مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدًا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةً مِّنكَ ۖ وَٱرْزُقْنَا وَأَنتَ خَيْرُ ٱلرَّٰزِقِينَ','733bcef720e58c468437e54ad657ab7bbc1e687667e01c75fec192cb3b246934',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (784,5,115,'قَالَ ٱللَّهُ إِنِّى مُنَزِّلُهَا عَلَيْكُمْ ۖ فَمَن يَكْفُرْ بَعْدُ مِنكُمْ فَإِنِّىٓ أُعَذِّبُهُۥ عَذَابًا لَّآ أُعَذِّبُهُۥٓ أَحَدًا مِّنَ ٱلْعَـٰلَمِينَ','b9469396032d59666ccea53a2ed404f3ff0a407ce6b5b90cfb64d98635a62d6d',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (785,5,116,'وَإِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَـٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَـٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ','e80592e9b33ed242b84499cfef60c92a327c7cdeafe5c5766a2f0feb658cd763',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (786,5,117,'مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ','413e0074019746f938fbbd5c437627e0e691289c2cdb4e5df165d55d2438651e',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (787,5,118,'إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ','c9c0c933977a9961d1e6abb2755d11bc3c0a63d916503a45714e7b17cef969b7',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (788,5,119,'قَالَ ٱللَّهُ هَـٰذَا يَوْمُ يَنفَعُ ٱلصَّـٰدِقِينَ صِدْقُهُمْ ۚ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ','f152fbd39b6b2cc1c9cdc2cceb750d55c1fe6a9ae3c42c629e83d681a65c2597',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (789,5,120,'لِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا فِيهِنَّ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌۢ','12f4e989736c96b11289a7a371f6debdde051daf6b14aeee54825ca00bd8a498',7,127,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (790,6,1,'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ','efff9db8dadcd5676b5f763ce7924eb60c80643815e7c569d9c6980098e272ac',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (791,6,2,'هُوَ ٱلَّذِى خَلَقَكُم مِّن طِينٍ ثُمَّ قَضَىٰٓ أَجَلًا ۖ وَأَجَلٌ مُّسَمًّى عِندَهُۥ ۖ ثُمَّ أَنتُمْ تَمْتَرُونَ','c554c6f80da8808022231953eca8626e6cef3c1ed99a0a38d83943de6a29de52',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (792,6,3,'وَهُوَ ٱللَّهُ فِى ٱلسَّمَـٰوَٰتِ وَفِى ٱلْأَرْضِ ۖ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ وَيَعْلَمُ مَا تَكْسِبُونَ','85be47c1bc44f279bab31d5f6072e769bb2677ea1252a3bcc5c07109283b3f14',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (793,6,4,'وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَـٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ','07303f0d66b5bf6153a44d2faeca6ae8dc638adf691f4ba5ce626b417cbabe78',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (794,6,5,'فَقَدْ كَذَّبُوا۟ بِٱلْحَقِّ لَمَّا جَآءَهُمْ ۖ فَسَوْفَ يَأْتِيهِمْ أَنۢبَـٰٓؤُا۟ مَا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','c1447d39d02f59ae38ff20e371739cc971dc26d4da4357502ffcd5520e39f19b',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (795,6,6,'أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ مَّكَّنَّـٰهُمْ فِى ٱلْأَرْضِ مَا لَمْ نُمَكِّن لَّكُمْ وَأَرْسَلْنَا ٱلسَّمَآءَ عَلَيْهِم مِّدْرَارًا وَجَعَلْنَا ٱلْأَنْهَـٰرَ تَجْرِى مِن تَحْتِهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَنشَأْنَا مِنۢ بَعْدِهِمْ قَرْنًا ءَاخَرِينَ','59ecf593e182846bd59a4d024ffb83c3ecaebaf8ebbde75fc2bd1f91e31cbaeb',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (796,6,7,'وَلَوْ نَزَّلْنَا عَلَيْكَ كِتَـٰبًا فِى قِرْطَاسٍ فَلَمَسُوهُ بِأَيْدِيهِمْ لَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّا سِحْرٌ مُّبِينٌ','0a6874e64acdf943ea9935d83b5a7673af4495b0166a079ed991bf839ff66b33',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (797,6,8,'وَقَالُوا۟ لَوْلَآ أُنزِلَ عَلَيْهِ مَلَكٌ ۖ وَلَوْ أَنزَلْنَا مَلَكًا لَّقُضِىَ ٱلْأَمْرُ ثُمَّ لَا يُنظَرُونَ','843e955820d40bc01a94ddb38af81d370252339fe5c8afc156a3dd4374012924',7,128,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (798,6,9,'وَلَوْ جَعَلْنَـٰهُ مَلَكًا لَّجَعَلْنَـٰهُ رَجُلًا وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُونَ','1453531a656c0ab0f1641ef24a8d1e7e1b2be5c74ef65ee4a35d06b2f163cb7a',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (799,6,10,'وَلَقَدِ ٱسْتُهْزِئَ بِرُسُلٍ مِّن قَبْلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُوا۟ مِنْهُم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ','c26ef020836af375cca527f6e1683337d66425da65ce922fe53f8e4f76866e36',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (800,6,11,'قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ ثُمَّ ٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ','84493fc639330da834a99d34fb014286c4a7cf45bddd484ac571d2ef2773a668',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (801,6,12,'قُل لِّمَن مَّا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُل لِّلَّهِ ۚ كَتَبَ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۚ لَيَجْمَعَنَّكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ ۚ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ','cde1940211ad699f86a4a790a0747fe9b14dc81fa8d7e453a9b6176e80cf92ee',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (802,6,13,'وَلَهُۥ مَا سَكَنَ فِى ٱلَّيْلِ وَٱلنَّهَارِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','75deda09de80c79877e289738d44dc907811133f33ded744d47d18bb46e84fde',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (803,6,14,'قُلْ أَغَيْرَ ٱللَّهِ أَتَّخِذُ وَلِيًّا فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَهُوَ يُطْعِمُ وَلَا يُطْعَمُ ۗ قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَكُونَ أَوَّلَ مَنْ أَسْلَمَ ۖ وَلَا تَكُونَنَّ مِنَ ٱلْمُشْرِكِينَ','2143f01964204719daab562b4cf7641a16d6340908f1e936fab87c89e8ed4434',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (804,6,15,'قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ','f06309ac89f947b69e5580500c3c2361ffa81838839304310e2fea2130c7f193',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (805,6,16,'مَّن يُصْرَفْ عَنْهُ يَوْمَئِذٍ فَقَدْ رَحِمَهُۥ ۚ وَذَٰلِكَ ٱلْفَوْزُ ٱلْمُبِينُ','67c21ae028952c410bfff08c2a0ac7e4af9eef3553402ad4737cae1d998578aa',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (806,6,17,'وَإِن يَمْسَسْكَ ٱللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُۥٓ إِلَّا هُوَ ۖ وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','1820dcd4ec5d1e70cb79980a93467b3e31f1249d1142ae7b8c325b285e41d777',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (807,6,18,'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ','540e48233de57910fba15fd3117cf98f2b54ee69a72b22f94a6b4f63918bb1da',7,129,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (808,6,19,'قُلْ أَىُّ شَىْءٍ أَكْبَرُ شَهَـٰدَةً ۖ قُلِ ٱللَّهُ ۖ شَهِيدٌۢ بَيْنِى وَبَيْنَكُمْ ۚ وَأُوحِىَ إِلَىَّ هَـٰذَا ٱلْقُرْءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَ ۚ أَئِنَّكُمْ لَتَشْهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخْرَىٰ ۚ قُل لَّآ أَشْهَدُ ۚ قُلْ إِنَّمَا هُوَ إِلَـٰهٌ وَٰحِدٌ وَإِنَّنِى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ','0766449984ed5ae84c6d02c947fc3483e69e7b2d6e84f65fb0509c4ee0a4604f',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (809,6,20,'ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمُ ۘ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ فَهُمْ لَا يُؤْمِنُونَ','b1e77e9451baf227449bee4aab651f8a3ae983fd819ab3367de9e65a5f4c9ae6',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (810,6,21,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ','56ef5ed4dffa0c8e5a79405658ac1bc35420cf5c208d063c77401a391c50fb58',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (811,6,22,'وَيَوْمَ نَحْشُرُهُمْ جَمِيعًا ثُمَّ نَقُولُ لِلَّذِينَ أَشْرَكُوٓا۟ أَيْنَ شُرَكَآؤُكُمُ ٱلَّذِينَ كُنتُمْ تَزْعُمُونَ','4c6602550bc63cf798c5f626a59b408fe4d496ba19bff3103374b2c2faeb51a5',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (812,6,23,'ثُمَّ لَمْ تَكُن فِتْنَتُهُمْ إِلَّآ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ','af5506661c51b69dc8172ade44730bf5710b4a4e570304dc624ff0a3a34384d9',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (813,6,24,'ٱنظُرْ كَيْفَ كَذَبُوا۟ عَلَىٰٓ أَنفُسِهِمْ ۚ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','a4b39cd4e05a3e667c42fab1ff7a291feaab4bbd04d9d113f69c5ebc55c81fe0',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (814,6,25,'وَمِنْهُم مَّن يَسْتَمِعُ إِلَيْكَ ۖ وَجَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِىٓ ءَاذَانِهِمْ وَقْرًا ۚ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا ۚ حَتَّىٰٓ إِذَا جَآءُوكَ يُجَـٰدِلُونَكَ يَقُولُ ٱلَّذِينَ كَفَرُوٓا۟ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','5cbb865b2f33bec5db8174e6feb60321a365416f9f7b0f011a9b2adc212aec9a',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (815,6,26,'وَهُمْ يَنْهَوْنَ عَنْهُ وَيَنْـَٔوْنَ عَنْهُ ۖ وَإِن يُهْلِكُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ','20238ff5f00004a5f9cff2ddf7294d7220da629892f35d659c9e0c41977ddbb1',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (816,6,27,'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ يَـٰلَيْتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔايَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلْمُؤْمِنِينَ','8ab9e1a23164e041d8da7f874f8cdba6032f384a0477be028b3aeae1eb6bf4e1',7,130,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (817,6,28,'بَلْ بَدَا لَهُم مَّا كَانُوا۟ يُخْفُونَ مِن قَبْلُ ۖ وَلَوْ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنْهُ وَإِنَّهُمْ لَكَـٰذِبُونَ','8fc86af2b2d108e36576f074ab08bff73f0ef7ea640a97d1f5bf321c9ddbbbf1',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (818,6,29,'وَقَالُوٓا۟ إِنْ هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا وَمَا نَحْنُ بِمَبْعُوثِينَ','539ade3298d756d4af439fc47a0a14a12b9ee33bc8f1178c34ec5c5f3d140851',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (819,6,30,'وَلَوْ تَرَىٰٓ إِذْ وُقِفُوا۟ عَلَىٰ رَبِّهِمْ ۚ قَالَ أَلَيْسَ هَـٰذَا بِٱلْحَقِّ ۚ قَالُوا۟ بَلَىٰ وَرَبِّنَا ۚ قَالَ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','c04b8fc48b7ac1f4077610f2ce12234980c3bb282edf7e17b25dfe6a8daf3c6b',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (820,6,31,'قَدْ خَسِرَ ٱلَّذِينَ كَذَّبُوا۟ بِلِقَآءِ ٱللَّهِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمُ ٱلسَّاعَةُ بَغْتَةً قَالُوا۟ يَـٰحَسْرَتَنَا عَلَىٰ مَا فَرَّطْنَا فِيهَا وَهُمْ يَحْمِلُونَ أَوْزَارَهُمْ عَلَىٰ ظُهُورِهِمْ ۚ أَلَا سَآءَ مَا يَزِرُونَ','7705c8ebd922c086a78bbb8631f9e985c5d77cc51003a98ee78b95b1812322b6',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (821,6,32,'وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا لَعِبٌ وَلَهْوٌ ۖ وَلَلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ','900a8a4f831926782122be96b1a720d932671bcd1b0028b234af46f80adaf409',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (822,6,33,'قَدْ نَعْلَمُ إِنَّهُۥ لَيَحْزُنُكَ ٱلَّذِى يَقُولُونَ ۖ فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِينَ بِـَٔايَـٰتِ ٱللَّهِ يَجْحَدُونَ','8a7df727d208d22fcfcb9e9e909de3376b84702ac18d7f3399461bb340c60381',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (823,6,34,'وَلَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰٓ أَتَىٰهُمْ نَصْرُنَا ۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِ ۚ وَلَقَدْ جَآءَكَ مِن نَّبَإِى۟ ٱلْمُرْسَلِينَ','7dec2510f0642567ac7881f3a689d0971aaf2375f10cb4e5259ae9b3b17155ea',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (824,6,35,'وَإِن كَانَ كَبُرَ عَلَيْكَ إِعْرَاضُهُمْ فَإِنِ ٱسْتَطَعْتَ أَن تَبْتَغِىَ نَفَقًا فِى ٱلْأَرْضِ أَوْ سُلَّمًا فِى ٱلسَّمَآءِ فَتَأْتِيَهُم بِـَٔايَةٍ ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَمَعَهُمْ عَلَى ٱلْهُدَىٰ ۚ فَلَا تَكُونَنَّ مِنَ ٱلْجَـٰهِلِينَ','8fecacd330b9c5db9196d95d06bf9b0d8add38cdaeee09436e638f816dc5ea14',7,131,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (825,6,36,'إِنَّمَا يَسْتَجِيبُ ٱلَّذِينَ يَسْمَعُونَ ۘ وَٱلْمَوْتَىٰ يَبْعَثُهُمُ ٱللَّهُ ثُمَّ إِلَيْهِ يُرْجَعُونَ','93a5d1c204fa0f6f6b28667d6f045f155d727a241dbc2ad1c6d3c3bb32724727',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (826,6,37,'وَقَالُوا۟ لَوْلَا نُزِّلَ عَلَيْهِ ءَايَةٌ مِّن رَّبِّهِۦ ۚ قُلْ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰٓ أَن يُنَزِّلَ ءَايَةً وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','77263fcbe6622b8bbf6658465a9b14a1f14a9ac725e5f980f873355efb13cfda',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (827,6,38,'وَمَا مِن دَآبَّةٍ فِى ٱلْأَرْضِ وَلَا طَـٰٓئِرٍ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَـٰبِ مِن شَىْءٍ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَ','bffca29bcbe63e180e3944b09c131e18e4f589ed2ac886a28a1e8f823da48b6b',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (828,6,39,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا صُمٌّ وَبُكْمٌ فِى ٱلظُّلُمَـٰتِ ۗ مَن يَشَإِ ٱللَّهُ يُضْلِلْهُ وَمَن يَشَأْ يَجْعَلْهُ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','5809628b0b43c3f1208030266224a9bb6e6cf863711e2ca59c2cb830085c9e23',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (829,6,40,'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ أَوْ أَتَتْكُمُ ٱلسَّاعَةُ أَغَيْرَ ٱللَّهِ تَدْعُونَ إِن كُنتُمْ صَـٰدِقِينَ','ae24e7ea0d3fa6556ba950599025e1926a60ebb2f65075093c92a00f9326efae',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (830,6,41,'بَلْ إِيَّاهُ تَدْعُونَ فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِن شَآءَ وَتَنسَوْنَ مَا تُشْرِكُونَ','052e24be2cad1ea86a26f91c7632d4c326f92971cc78167a45f22c5806bb49f9',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (831,6,42,'وَلَقَدْ أَرْسَلْنَآ إِلَىٰٓ أُمَمٍ مِّن قَبْلِكَ فَأَخَذْنَـٰهُم بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَتَضَرَّعُونَ','ce507bf0fe180f2d1713a0b2e910174c179bac568e4379364e1cb158531235d2',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (832,6,43,'فَلَوْلَآ إِذْ جَآءَهُم بَأْسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتْ قُلُوبُهُمْ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ مَا كَانُوا۟ يَعْمَلُونَ','c5cfd0b349d47552d3536e8cc50e5aa97355d1ada6a2d683159b8e21f7d16a9e',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (833,6,44,'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَـٰهُم بَغْتَةً فَإِذَا هُم مُّبْلِسُونَ','3139495d411739a6fe58bf1a53b7b00a6e4a2f380099d0f8e58d13abdfab9cac',7,132,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (834,6,45,'فَقُطِعَ دَابِرُ ٱلْقَوْمِ ٱلَّذِينَ ظَلَمُوا۟ ۚ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','f206d9cec5a21629d7671cf6f8db928df90b26ab6dd03ae278c3e9bd202f7b64',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (835,6,46,'قُلْ أَرَءَيْتُمْ إِنْ أَخَذَ ٱللَّهُ سَمْعَكُمْ وَأَبْصَـٰرَكُمْ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنْ إِلَـٰهٌ غَيْرُ ٱللَّهِ يَأْتِيكُم بِهِ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ ثُمَّ هُمْ يَصْدِفُونَ','1d59b41fd7e245483fa483801b3a3511e414e21cc6c11d44b6acc9b25c318b61',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (836,6,47,'قُلْ أَرَءَيْتَكُمْ إِنْ أَتَىٰكُمْ عَذَابُ ٱللَّهِ بَغْتَةً أَوْ جَهْرَةً هَلْ يُهْلَكُ إِلَّا ٱلْقَوْمُ ٱلظَّـٰلِمُونَ','44770acf5149d72fa2cf6861ef0dbc2e7657a3708749c8bbd59fc4199c7ccb06',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (837,6,48,'وَمَا نُرْسِلُ ٱلْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ ۖ فَمَنْ ءَامَنَ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','f7dc5f16441fb5c5d9988035afe9e24b099e8b2f1a848d6df26a30a23ee9ddd6',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (838,6,49,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا يَمَسُّهُمُ ٱلْعَذَابُ بِمَا كَانُوا۟ يَفْسُقُونَ','a300f1f0c8b09bf65facd7a9235cf98bc17b0411c51bffca97e5e799e4eb9af2',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (839,6,50,'قُل لَّآ أَقُولُ لَكُمْ عِندِى خَزَآئِنُ ٱللَّهِ وَلَآ أَعْلَمُ ٱلْغَيْبَ وَلَآ أَقُولُ لَكُمْ إِنِّى مَلَكٌ ۖ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَىَّ ۚ قُلْ هَلْ يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ ۚ أَفَلَا تَتَفَكَّرُونَ','5d22ca53619a39d5e93e4e67930ced79d02506050ad4b6263ebace833eb15e2e',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (840,6,51,'وَأَنذِرْ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحْشَرُوٓا۟ إِلَىٰ رَبِّهِمْ ۙ لَيْسَ لَهُم مِّن دُونِهِۦ وَلِىٌّ وَلَا شَفِيعٌ لَّعَلَّهُمْ يَتَّقُونَ','134613c329bd85a9c824ecfa85393bb323c003e0ed931ee3c995245a773a47cf',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (841,6,52,'وَلَا تَطْرُدِ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ ۖ مَا عَلَيْكَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَمَا مِنْ حِسَابِكَ عَلَيْهِم مِّن شَىْءٍ فَتَطْرُدَهُمْ فَتَكُونَ مِنَ ٱلظَّـٰلِمِينَ','9494b4f7f64d6b228d389c2f15f12ef29c6994aad103cf961543dc1d528e6874',7,133,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (842,6,53,'وَكَذَٰلِكَ فَتَنَّا بَعْضَهُم بِبَعْضٍ لِّيَقُولُوٓا۟ أَهَـٰٓؤُلَآءِ مَنَّ ٱللَّهُ عَلَيْهِم مِّنۢ بَيْنِنَآ ۗ أَلَيْسَ ٱللَّهُ بِأَعْلَمَ بِٱلشَّـٰكِرِينَ','19358006fc84e12a18659e854674f10e9edfdf82f17aa7cd2f0e8b56932eb977',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (843,6,54,'وَإِذَا جَآءَكَ ٱلَّذِينَ يُؤْمِنُونَ بِـَٔايَـٰتِنَا فَقُلْ سَلَـٰمٌ عَلَيْكُمْ ۖ كَتَبَ رَبُّكُمْ عَلَىٰ نَفْسِهِ ٱلرَّحْمَةَ ۖ أَنَّهُۥ مَنْ عَمِلَ مِنكُمْ سُوٓءًۢا بِجَهَـٰلَةٍ ثُمَّ تَابَ مِنۢ بَعْدِهِۦ وَأَصْلَحَ فَأَنَّهُۥ غَفُورٌ رَّحِيمٌ','3038f9e60eb2c1ee2b363c50e6bbd1bd4ac09c2fd9b4ac9ea3d323025f3787a4',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (844,6,55,'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلِتَسْتَبِينَ سَبِيلُ ٱلْمُجْرِمِينَ','3fa71a33878946e74a1b5234381852c1b03b16522fb119ee18dea9feeb4fe607',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (845,6,56,'قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ ۚ قُل لَّآ أَتَّبِعُ أَهْوَآءَكُمْ ۙ قَدْ ضَلَلْتُ إِذًا وَمَآ أَنَا۠ مِنَ ٱلْمُهْتَدِينَ','0fc3e70e05beeeaac1fa8c8ef601eec3a88aa2802ec5c7261b5cd134445a44d6',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (846,6,57,'قُلْ إِنِّى عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَكَذَّبْتُم بِهِۦ ۚ مَا عِندِى مَا تَسْتَعْجِلُونَ بِهِۦٓ ۚ إِنِ ٱلْحُكْمُ إِلَّا لِلَّهِ ۖ يَقُصُّ ٱلْحَقَّ ۖ وَهُوَ خَيْرُ ٱلْفَـٰصِلِينَ','4f6cf2819c676969e18e484426fdbbfbb25d1749bbbb66311ee8ef819c0ba4fa',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (847,6,58,'قُل لَّوْ أَنَّ عِندِى مَا تَسْتَعْجِلُونَ بِهِۦ لَقُضِىَ ٱلْأَمْرُ بَيْنِى وَبَيْنَكُمْ ۗ وَٱللَّهُ أَعْلَمُ بِٱلظَّـٰلِمِينَ','baa10dedb7062976fbba881009789a9fb390aa0a52adbdbd063fb980c4965b6d',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (848,6,59,'وَعِندَهُۥ مَفَاتِحُ ٱلْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَ ۚ وَيَعْلَمُ مَا فِى ٱلْبَرِّ وَٱلْبَحْرِ ۚ وَمَا تَسْقُطُ مِن وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِى ظُلُمَـٰتِ ٱلْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ','8d634e840853e69a059a9994d917f21cf6ce23367627d53cec09d28ccaaa0d7d',7,134,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (849,6,60,'وَهُوَ ٱلَّذِى يَتَوَفَّىٰكُم بِٱلَّيْلِ وَيَعْلَمُ مَا جَرَحْتُم بِٱلنَّهَارِ ثُمَّ يَبْعَثُكُمْ فِيهِ لِيُقْضَىٰٓ أَجَلٌ مُّسَمًّى ۖ ثُمَّ إِلَيْهِ مَرْجِعُكُمْ ثُمَّ يُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ','6a8130c64b739224c128c793c9116c41c0029800b34a27a5025c33dafe7737b8',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (850,6,61,'وَهُوَ ٱلْقَاهِرُ فَوْقَ عِبَادِهِۦ ۖ وَيُرْسِلُ عَلَيْكُمْ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَهُمْ لَا يُفَرِّطُونَ','ce80bf00773e256ed86107039e5911ff927f5d352c15cb2bb930d7cc3c855529',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (851,6,62,'ثُمَّ رُدُّوٓا۟ إِلَى ٱللَّهِ مَوْلَىٰهُمُ ٱلْحَقِّ ۚ أَلَا لَهُ ٱلْحُكْمُ وَهُوَ أَسْرَعُ ٱلْحَـٰسِبِينَ','f2598926e4a71fd7cfb0fbde17015d57162712e4b0d6e78b2bfb2bebcbb98999',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (852,6,63,'قُلْ مَن يُنَجِّيكُم مِّن ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ تَدْعُونَهُۥ تَضَرُّعًا وَخُفْيَةً لَّئِنْ أَنجَىٰنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ','3c3ca7d2eacf40633fe13f3b7b40a53846bdcec27b69d1b2ff80084f4125aaf9',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (853,6,64,'قُلِ ٱللَّهُ يُنَجِّيكُم مِّنْهَا وَمِن كُلِّ كَرْبٍ ثُمَّ أَنتُمْ تُشْرِكُونَ','ef5768d4802d41c19d3c3a34cc8692e89efe9d7f6d613b6fdcfef9e546e28732',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (854,6,65,'قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لَعَلَّهُمْ يَفْقَهُونَ','00a9867f57f28c2af412da239e6628cc2ac2a5aa5a7bd3cd856dcc5f0545f6ae',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (855,6,66,'وَكَذَّبَ بِهِۦ قَوْمُكَ وَهُوَ ٱلْحَقُّ ۚ قُل لَّسْتُ عَلَيْكُم بِوَكِيلٍ','b7d7288f1487704620d5f36d091981310aab86b946d29640baa72bac83364c05',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (856,6,67,'لِّكُلِّ نَبَإٍ مُّسْتَقَرٌّ ۚ وَسَوْفَ تَعْلَمُونَ','533839aa594935b1ae52a008c328dfabc7899f0efdcda49f31bd97f28eee5298',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (857,6,68,'وَإِذَا رَأَيْتَ ٱلَّذِينَ يَخُوضُونَ فِىٓ ءَايَـٰتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّىٰ يَخُوضُوا۟ فِى حَدِيثٍ غَيْرِهِۦ ۚ وَإِمَّا يُنسِيَنَّكَ ٱلشَّيْطَـٰنُ فَلَا تَقْعُدْ بَعْدَ ٱلذِّكْرَىٰ مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','b5b0e7607352a328cf78702f40e1cad9bfa92eb6de153fda081dd045d8d50f42',7,135,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (858,6,69,'وَمَا عَلَى ٱلَّذِينَ يَتَّقُونَ مِنْ حِسَابِهِم مِّن شَىْءٍ وَلَـٰكِن ذِكْرَىٰ لَعَلَّهُمْ يَتَّقُونَ','45da52d496a83319a6958a60b8aed59ac95a7594ebf284cd4d63b4c5987bb0dd',7,136,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (859,6,70,'وَذَرِ ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَعِبًا وَلَهْوًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ وَذَكِّرْ بِهِۦٓ أَن تُبْسَلَ نَفْسٌۢ بِمَا كَسَبَتْ لَيْسَ لَهَا مِن دُونِ ٱللَّهِ وَلِىٌّ وَلَا شَفِيعٌ وَإِن تَعْدِلْ كُلَّ عَدْلٍ لَّا يُؤْخَذْ مِنْهَآ ۗ أُو۟لَـٰٓئِكَ ٱلَّذِينَ أُبْسِلُوا۟ بِمَا كَسَبُوا۟ ۖ لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْفُرُونَ','249dc624b65101c3d136edc142eac1108ca56b2dad23366d1909caea113053db',7,136,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (860,6,71,'قُلْ أَنَدْعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَىٰٓ أَعْقَابِنَا بَعْدَ إِذْ هَدَىٰنَا ٱللَّهُ كَٱلَّذِى ٱسْتَهْوَتْهُ ٱلشَّيَـٰطِينُ فِى ٱلْأَرْضِ حَيْرَانَ لَهُۥٓ أَصْحَـٰبٌ يَدْعُونَهُۥٓ إِلَى ٱلْهُدَى ٱئْتِنَا ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۖ وَأُمِرْنَا لِنُسْلِمَ لِرَبِّ ٱلْعَـٰلَمِينَ','cc5a618ca907a3080a469a14cb16a7ebdfe8daa756b1f20d0c174d65be71fefb',7,136,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (861,6,72,'وَأَنْ أَقِيمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُ ۚ وَهُوَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ','81cb4ce5e258c7314d1365173b39387f6f544563b3933f60efa7db68fa6dac40',7,136,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (862,6,73,'وَهُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ ۖ وَيَوْمَ يَقُولُ كُن فَيَكُونُ ۚ قَوْلُهُ ٱلْحَقُّ ۚ وَلَهُ ٱلْمُلْكُ يَوْمَ يُنفَخُ فِى ٱلصُّورِ ۚ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۚ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ','5cf1902347bf8bff16c8aee01ce6a00d829ee41d63343aac7584fdd86253f329',7,136,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (863,6,74,'وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَـٰلٍ مُّبِينٍ','1d8b0697b81618d021629f6fd47b96259078da414c928b05094036f6264f5d07',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (864,6,75,'وَكَذَٰلِكَ نُرِىٓ إِبْرَٰهِيمَ مَلَكُوتَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلِيَكُونَ مِنَ ٱلْمُوقِنِينَ','8cd582429f5202cec48e93e6dfb63be17a3a4dd385b198c915f44666ed545bc8',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (865,6,76,'فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا ۖ قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ','ec4a4614de44fba988419ed80a74767e94336aef8866bb29932ab3944a4923b6',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (866,6,77,'فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ','4dc447ff05691764d407998c5ac0b0b003b2f7cf3f657050e76ce58a20030929',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (867,6,78,'فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَـٰذَا رَبِّى هَـٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَـٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ','8bb3a1247e35e8ba6ed45b3e52eb56b49a4621b194ff93201f1d4de3d8aa3665',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (868,6,79,'إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ','58c091e62f42d8bcf24270b7ad1bda367a3fe88bd7bc196002d94758caf6c1bd',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (869,6,80,'وَحَآجَّهُۥ قَوْمُهُۥ ۚ قَالَ أَتُحَـٰٓجُّوٓنِّى فِى ٱللَّهِ وَقَدْ هَدَىٰنِ ۚ وَلَآ أَخَافُ مَا تُشْرِكُونَ بِهِۦٓ إِلَّآ أَن يَشَآءَ رَبِّى شَيْـًٔا ۗ وَسِعَ رَبِّى كُلَّ شَىْءٍ عِلْمًا ۗ أَفَلَا تَتَذَكَّرُونَ','a03575d8082c86ccdc43c136e74ae5db1cb9dcdd46afcdfee16aaf6d3d34bbf7',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (870,6,81,'وَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلَا تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ عَلَيْكُمْ سُلْطَـٰنًا ۚ فَأَىُّ ٱلْفَرِيقَيْنِ أَحَقُّ بِٱلْأَمْنِ ۖ إِن كُنتُمْ تَعْلَمُونَ','310cae66f2ede631b60b26093b214b5bffe21d6a7e0028881dfdcb6a5bcffd79',7,137,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (871,6,82,'ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَـٰنَهُم بِظُلْمٍ أُو۟لَـٰٓئِكَ لَهُمُ ٱلْأَمْنُ وَهُم مُّهْتَدُونَ','725dec66493dd03c5d2b2aad8c308ce40424da41e971a6cbc10df3588fe111c7',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (872,6,83,'وَتِلْكَ حُجَّتُنَآ ءَاتَيْنَـٰهَآ إِبْرَٰهِيمَ عَلَىٰ قَوْمِهِۦ ۚ نَرْفَعُ دَرَجَـٰتٍ مَّن نَّشَآءُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ','e58dac4688590f584efa0f62f4a9a83678c512271a6551bfb29316b4c020cc66',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (873,6,84,'وَوَهَبْنَا لَهُۥٓ إِسْحَـٰقَ وَيَعْقُوبَ ۚ كُلًّا هَدَيْنَا ۚ وَنُوحًا هَدَيْنَا مِن قَبْلُ ۖ وَمِن ذُرِّيَّتِهِۦ دَاوُۥدَ وَسُلَيْمَـٰنَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَـٰرُونَ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ','8669bf87551ec555b7b8fc36b8270d542d7e71db85712fa6bde08ec11e52b076',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (874,6,85,'وَزَكَرِيَّا وَيَحْيَىٰ وَعِيسَىٰ وَإِلْيَاسَ ۖ كُلٌّ مِّنَ ٱلصَّـٰلِحِينَ','96cf73b07e3e4034528d4c9cd07ccb2955bd3dfe3852f58449884a7ecb25550a',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (875,6,86,'وَإِسْمَـٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًا ۚ وَكُلًّا فَضَّلْنَا عَلَى ٱلْعَـٰلَمِينَ','50574840d689d35cada06b6bbe2280561fd09dd4180bd124e770c37bb3f132ee',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (876,6,87,'وَمِنْ ءَابَآئِهِمْ وَذُرِّيَّـٰتِهِمْ وَإِخْوَٰنِهِمْ ۖ وَٱجْتَبَيْنَـٰهُمْ وَهَدَيْنَـٰهُمْ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ','5c94cfd044ce6289132706a44102e2ba8e4db9e66e75f88db85bb37ccfb058b0',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (877,6,88,'ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ مِنْ عِبَادِهِۦ ۚ وَلَوْ أَشْرَكُوا۟ لَحَبِطَ عَنْهُم مَّا كَانُوا۟ يَعْمَلُونَ','913e2c636cb780db7c5cb03b322e98d58e569746fb8ec4bfaad0a8e40066ac5c',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (878,6,89,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ وَٱلْحُكْمَ وَٱلنُّبُوَّةَ ۚ فَإِن يَكْفُرْ بِهَا هَـٰٓؤُلَآءِ فَقَدْ وَكَّلْنَا بِهَا قَوْمًا لَّيْسُوا۟ بِهَا بِكَـٰفِرِينَ','61cb52a6055723a5d017452cca0adcc10b26c93ba035d036c6943b9bf6451284',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (879,6,90,'أُو۟لَـٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُ ۖ فَبِهُدَىٰهُمُ ٱقْتَدِهْ ۗ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا ۖ إِنْ هُوَ إِلَّا ذِكْرَىٰ لِلْعَـٰلَمِينَ','fb136dce27843b93a4083ced0ddef98f5843eb6d3a261d6d31a5bb0fec24f88a',7,138,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (880,6,91,'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦٓ إِذْ قَالُوا۟ مَآ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرٍ مِّن شَىْءٍ ۗ قُلْ مَنْ أَنزَلَ ٱلْكِتَـٰبَ ٱلَّذِى جَآءَ بِهِۦ مُوسَىٰ نُورًا وَهُدًى لِّلنَّاسِ ۖ تَجْعَلُونَهُۥ قَرَاطِيسَ تُبْدُونَهَا وَتُخْفُونَ كَثِيرًا ۖ وَعُلِّمْتُم مَّا لَمْ تَعْلَمُوٓا۟ أَنتُمْ وَلَآ ءَابَآؤُكُمْ ۖ قُلِ ٱللَّهُ ۖ ثُمَّ ذَرْهُمْ فِى خَوْضِهِمْ يَلْعَبُونَ','b11f942c580b5bfbd2950448f463a2dc2d30882d435dd0adadcbbf01296b8912',7,139,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (881,6,92,'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ مُّصَدِّقُ ٱلَّذِى بَيْنَ يَدَيْهِ وَلِتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا ۚ وَٱلَّذِينَ يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ يُؤْمِنُونَ بِهِۦ ۖ وَهُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ','bec34fcb7b3105af4bc30cb6ba436693c4488d36c51e329de47499129878108d',7,139,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (882,6,93,'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ قَالَ أُوحِىَ إِلَىَّ وَلَمْ يُوحَ إِلَيْهِ شَىْءٌ وَمَن قَالَ سَأُنزِلُ مِثْلَ مَآ أَنزَلَ ٱللَّهُ ۗ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّـٰلِمُونَ فِى غَمَرَٰتِ ٱلْمَوْتِ وَٱلْمَلَـٰٓئِكَةُ بَاسِطُوٓا۟ أَيْدِيهِمْ أَخْرِجُوٓا۟ أَنفُسَكُمُ ۖ ٱلْيَوْمَ تُجْزَوْنَ عَذَابَ ٱلْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى ٱللَّهِ غَيْرَ ٱلْحَقِّ وَكُنتُمْ عَنْ ءَايَـٰتِهِۦ تَسْتَكْبِرُونَ','af595ab31a011b4ac23b9f97ec4f4f197394c533afac42d37bf43b97e430769e',7,139,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (883,6,94,'وَلَقَدْ جِئْتُمُونَا فُرَٰدَىٰ كَمَا خَلَقْنَـٰكُمْ أَوَّلَ مَرَّةٍ وَتَرَكْتُم مَّا خَوَّلْنَـٰكُمْ وَرَآءَ ظُهُورِكُمْ ۖ وَمَا نَرَىٰ مَعَكُمْ شُفَعَآءَكُمُ ٱلَّذِينَ زَعَمْتُمْ أَنَّهُمْ فِيكُمْ شُرَكَـٰٓؤُا۟ ۚ لَقَد تَّقَطَّعَ بَيْنَكُمْ وَضَلَّ عَنكُم مَّا كُنتُمْ تَزْعُمُونَ','8162f6721d6b6f7b398d410ee5888cfbcaedb1e67004c05bbc08711c1b17b99a',7,139,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (884,6,95,'إِنَّ ٱللَّهَ فَالِقُ ٱلْحَبِّ وَٱلنَّوَىٰ ۖ يُخْرِجُ ٱلْحَىَّ مِنَ ٱلْمَيِّتِ وَمُخْرِجُ ٱلْمَيِّتِ مِنَ ٱلْحَىِّ ۚ ذَٰلِكُمُ ٱللَّهُ ۖ فَأَنَّىٰ تُؤْفَكُونَ','fbeaab3d726b9aad39c97b40bcac672f056235897d9ceb76868536ac678c69b6',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (885,6,96,'فَالِقُ ٱلْإِصْبَاحِ وَجَعَلَ ٱلَّيْلَ سَكَنًا وَٱلشَّمْسَ وَٱلْقَمَرَ حُسْبَانًا ۚ ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ','7c9eb9d0ff494c36d9da5028cdf36bd53e7f185075b784ea9dab4daab90d36e0',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (886,6,97,'وَهُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهْتَدُوا۟ بِهَا فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','17357bbf89079eb77b9c7d25eadc583230ae83d904fc1c023531b2967ef92cbd',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (887,6,98,'وَهُوَ ٱلَّذِىٓ أَنشَأَكُم مِّن نَّفْسٍ وَٰحِدَةٍ فَمُسْتَقَرٌّ وَمُسْتَوْدَعٌ ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَفْقَهُونَ','681e25b3d11ef952fa273a4d6ed29b567775ef5d721b10e52b26e1ee7db75729',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (888,6,99,'وَهُوَ ٱلَّذِىٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ نَبَاتَ كُلِّ شَىْءٍ فَأَخْرَجْنَا مِنْهُ خَضِرًا نُّخْرِجُ مِنْهُ حَبًّا مُّتَرَاكِبًا وَمِنَ ٱلنَّخْلِ مِن طَلْعِهَا قِنْوَانٌ دَانِيَةٌ وَجَنَّـٰتٍ مِّنْ أَعْنَابٍ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُشْتَبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۗ ٱنظُرُوٓا۟ إِلَىٰ ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَيَنْعِهِۦٓ ۚ إِنَّ فِى ذَٰلِكُمْ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ','d8e4d499f605c4cd660e315693da4255585c3d94a14bdf278a4776caec72f6d1',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (889,6,100,'وَجَعَلُوا۟ لِلَّهِ شُرَكَآءَ ٱلْجِنَّ وَخَلَقَهُمْ ۖ وَخَرَقُوا۟ لَهُۥ بَنِينَ وَبَنَـٰتٍۭ بِغَيْرِ عِلْمٍ ۚ سُبْحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا يَصِفُونَ','e98d93a4aa73707bc888ddefd16f2376fbd3007682252c3578155883a961a5ff',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (890,6,101,'بَدِيعُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٌ وَلَمْ تَكُن لَّهُۥ صَـٰحِبَةٌ ۖ وَخَلَقَ كُلَّ شَىْءٍ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ','0c6e07d5a1f9a2008e8cda42cfc98c8e34832996d3152cd4f24a76dbe9214983',7,140,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (891,6,102,'ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ خَـٰلِقُ كُلِّ شَىْءٍ فَٱعْبُدُوهُ ۚ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ','40e8a486a69167d7c2c40378df088fc2a951198c274da0897457ac22a6233dc5',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (892,6,103,'لَّا تُدْرِكُهُ ٱلْأَبْصَـٰرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَـٰرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ','f5a2d43483fc39c9070ffb1d885e9f1d92e15883dfe167189a2f831b22117bd5',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (893,6,104,'قَدْ جَآءَكُم بَصَآئِرُ مِن رَّبِّكُمْ ۖ فَمَنْ أَبْصَرَ فَلِنَفْسِهِۦ ۖ وَمَنْ عَمِىَ فَعَلَيْهَا ۚ وَمَآ أَنَا۠ عَلَيْكُم بِحَفِيظٍ','3c1bed99bc4cda29debf3aad98ee5966a407efae875b6f03f44c2ed8ec48c962',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (894,6,105,'وَكَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ وَلِيَقُولُوا۟ دَرَسْتَ وَلِنُبَيِّنَهُۥ لِقَوْمٍ يَعْلَمُونَ','d0bf2d9e8f08fcc6ec3f6c6915ab59817c41e3de5723e933466307decb1519f7',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (895,6,106,'ٱتَّبِعْ مَآ أُوحِىَ إِلَيْكَ مِن رَّبِّكَ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ ۖ وَأَعْرِضْ عَنِ ٱلْمُشْرِكِينَ','ec134dbe23e52e378dffc2a372478cc8058e9d91db7b5d8dd38154e32b247c95',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (896,6,107,'وَلَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكُوا۟ ۗ وَمَا جَعَلْنَـٰكَ عَلَيْهِمْ حَفِيظًا ۖ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ','222422499142061ec3e7dc349b3b7830f4ef3e58456359ee1cdb513431d5c7cf',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (897,6,108,'وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ','556632bb21375556a8c73bcc77b1ce4d079fa6ecfff0e68b69672bb54f5cf029',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (898,6,109,'وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَـٰنِهِمْ لَئِن جَآءَتْهُمْ ءَايَةٌ لَّيُؤْمِنُنَّ بِهَا ۚ قُلْ إِنَّمَا ٱلْـَٔايَـٰتُ عِندَ ٱللَّهِ ۖ وَمَا يُشْعِرُكُمْ أَنَّهَآ إِذَا جَآءَتْ لَا يُؤْمِنُونَ','bdbf3e6edd71d498ea5b643f115b404fc16cf5629a91fd420615f11b146aa03e',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (899,6,110,'وَنُقَلِّبُ أَفْـِٔدَتَهُمْ وَأَبْصَـٰرَهُمْ كَمَا لَمْ يُؤْمِنُوا۟ بِهِۦٓ أَوَّلَ مَرَّةٍ وَنَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','8b2638a248cec92b6f7eb04d6d5cc87b765522bc7521a8e1fc729f2cd7bdeddb',7,141,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (900,6,111,'وَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ ٱلْمَلَـٰٓئِكَةَ وَكَلَّمَهُمُ ٱلْمَوْتَىٰ وَحَشَرْنَا عَلَيْهِمْ كُلَّ شَىْءٍ قُبُلًا مَّا كَانُوا۟ لِيُؤْمِنُوٓا۟ إِلَّآ أَن يَشَآءَ ٱللَّهُ وَلَـٰكِنَّ أَكْثَرَهُمْ يَجْهَلُونَ','afedb8acbd825e20e62cb2b865928a5c0fd5cbf469694cf5feb995755630cecf',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (901,6,112,'وَكَذَٰلِكَ جَعَلْنَا لِكُلِّ نَبِىٍّ عَدُوًّا شَيَـٰطِينَ ٱلْإِنسِ وَٱلْجِنِّ يُوحِى بَعْضُهُمْ إِلَىٰ بَعْضٍ زُخْرُفَ ٱلْقَوْلِ غُرُورًا ۚ وَلَوْ شَآءَ رَبُّكَ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ','35bcd02247731636b7ec4b34be3333c004e79f106421a690af2428557bb93182',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (902,6,113,'وَلِتَصْغَىٰٓ إِلَيْهِ أَفْـِٔدَةُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَلِيَرْضَوْهُ وَلِيَقْتَرِفُوا۟ مَا هُم مُّقْتَرِفُونَ','b8300744cbc24a1ec308131f9cfbc748096df5449d0bc364805747763df63729',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (903,6,114,'أَفَغَيْرَ ٱللَّهِ أَبْتَغِى حَكَمًا وَهُوَ ٱلَّذِىٓ أَنزَلَ إِلَيْكُمُ ٱلْكِتَـٰبَ مُفَصَّلًا ۚ وَٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْلَمُونَ أَنَّهُۥ مُنَزَّلٌ مِّن رَّبِّكَ بِٱلْحَقِّ ۖ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ','a92f420b87bc56ae4aac0a36b8a855ef7d93ef2fdb22d955415802b4fd3c79ec',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (904,6,115,'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا ۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','95b9edf72116da3addf6a867409d8a23d8f2f010c76a8b85bb764ed03ffc5367',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (905,6,116,'وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ','325385f6769758f861fa46c010872d15fab426441b9f97f80f921f5ca1592433',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (906,6,117,'إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ','f381e56ab45ca0aa9c30d9f7e9288f144d4433011d372edf559d9e5972253546',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (907,6,118,'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَـٰتِهِۦ مُؤْمِنِينَ','5f7bb26560c56bf8b383d49a77fd575c3a06f3d2c9156cb0687cdd5a38fbd6fd',8,142,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (908,6,119,'وَمَا لَكُمْ أَلَّا تَأْكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ ۗ وَإِنَّ كَثِيرًا لَّيُضِلُّونَ بِأَهْوَآئِهِم بِغَيْرِ عِلْمٍ ۗ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِٱلْمُعْتَدِينَ','2a5b9c0d9a131f3a11311398c8d10d018171ceb07e3040682964889e5194667e',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (909,6,120,'وَذَرُوا۟ ظَـٰهِرَ ٱلْإِثْمِ وَبَاطِنَهُۥٓ ۚ إِنَّ ٱلَّذِينَ يَكْسِبُونَ ٱلْإِثْمَ سَيُجْزَوْنَ بِمَا كَانُوا۟ يَقْتَرِفُونَ','6cd46a147e272bcbde75fb1cdd5930ecf3361de580db365fa508b80365836bb6',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (910,6,121,'وَلَا تَأْكُلُوا۟ مِمَّا لَمْ يُذْكَرِ ٱسْمُ ٱللَّهِ عَلَيْهِ وَإِنَّهُۥ لَفِسْقٌ ۗ وَإِنَّ ٱلشَّيَـٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوْلِيَآئِهِمْ لِيُجَـٰدِلُوكُمْ ۖ وَإِنْ أَطَعْتُمُوهُمْ إِنَّكُمْ لَمُشْرِكُونَ','f9344edd9a6eadfff570a104c67b9ab22ce4ad6ee33f14b7c53903e57ee453e0',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (911,6,122,'أَوَمَن كَانَ مَيْتًا فَأَحْيَيْنَـٰهُ وَجَعَلْنَا لَهُۥ نُورًا يَمْشِى بِهِۦ فِى ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِى ٱلظُّلُمَـٰتِ لَيْسَ بِخَارِجٍ مِّنْهَا ۚ كَذَٰلِكَ زُيِّنَ لِلْكَـٰفِرِينَ مَا كَانُوا۟ يَعْمَلُونَ','a6d716ae0c63617d58874101585eb8ded4f97547cdd1ba7ffdb780a82570cc0d',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (912,6,123,'وَكَذَٰلِكَ جَعَلْنَا فِى كُلِّ قَرْيَةٍ أَكَـٰبِرَ مُجْرِمِيهَا لِيَمْكُرُوا۟ فِيهَا ۖ وَمَا يَمْكُرُونَ إِلَّا بِأَنفُسِهِمْ وَمَا يَشْعُرُونَ','2190e2f2cf98d95ca907a5fc64fbdd510c0ed59d29b05ffd5d65d84f9f66e904',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (913,6,124,'وَإِذَا جَآءَتْهُمْ ءَايَةٌ قَالُوا۟ لَن نُّؤْمِنَ حَتَّىٰ نُؤْتَىٰ مِثْلَ مَآ أُوتِىَ رُسُلُ ٱللَّهِ ۘ ٱللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُۥ ۗ سَيُصِيبُ ٱلَّذِينَ أَجْرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابٌ شَدِيدٌۢ بِمَا كَانُوا۟ يَمْكُرُونَ','5d52723d194b3809d3f14c40968126291014fed314457f8c8a017bf0853258f6',8,143,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (914,6,125,'فَمَن يُرِدِ ٱللَّهُ أَن يَهْدِيَهُۥ يَشْرَحْ صَدْرَهُۥ لِلْإِسْلَـٰمِ ۖ وَمَن يُرِدْ أَن يُضِلَّهُۥ يَجْعَلْ صَدْرَهُۥ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِى ٱلسَّمَآءِ ۚ كَذَٰلِكَ يَجْعَلُ ٱللَّهُ ٱلرِّجْسَ عَلَى ٱلَّذِينَ لَا يُؤْمِنُونَ','43c3026f82468c8611bb6b826ae414e4f17b64f691d0da2c239274126cdf70f7',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (915,6,126,'وَهَـٰذَا صِرَٰطُ رَبِّكَ مُسْتَقِيمًا ۗ قَدْ فَصَّلْنَا ٱلْـَٔايَـٰتِ لِقَوْمٍ يَذَّكَّرُونَ','f66958892e9bdee1f1c7be9ffaa382650998145c5b2da76b19c46f647dd9addd',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (916,6,127,'لَهُمْ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمْ ۖ وَهُوَ وَلِيُّهُم بِمَا كَانُوا۟ يَعْمَلُونَ','bf6e71c3f4e004b8ef59a10392537a70bc4d004c0ab6f831b1f1430d6d4ee3d6',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (917,6,128,'وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا يَـٰمَعْشَرَ ٱلْجِنِّ قَدِ ٱسْتَكْثَرْتُم مِّنَ ٱلْإِنسِ ۖ وَقَالَ أَوْلِيَآؤُهُم مِّنَ ٱلْإِنسِ رَبَّنَا ٱسْتَمْتَعَ بَعْضُنَا بِبَعْضٍ وَبَلَغْنَآ أَجَلَنَا ٱلَّذِىٓ أَجَّلْتَ لَنَا ۚ قَالَ ٱلنَّارُ مَثْوَىٰكُمْ خَـٰلِدِينَ فِيهَآ إِلَّا مَا شَآءَ ٱللَّهُ ۗ إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ','8e9dd73bad017c721a8873d83525308d6549350aac37355e3d064372570a5c57',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (918,6,129,'وَكَذَٰلِكَ نُوَلِّى بَعْضَ ٱلظَّـٰلِمِينَ بَعْضًۢا بِمَا كَانُوا۟ يَكْسِبُونَ','27f5b4610c81cc58bc570e441f24d32fdd83a4831809de30306398e684d017c1',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (919,6,130,'يَـٰمَعْشَرَ ٱلْجِنِّ وَٱلْإِنسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَـٰذَا ۚ قَالُوا۟ شَهِدْنَا عَلَىٰٓ أَنفُسِنَا ۖ وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ','a79643c12228c3397d8247d513a43af196f041926c5a9f25901da3ad845f0b18',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (920,6,131,'ذَٰلِكَ أَن لَّمْ يَكُن رَّبُّكَ مُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍ وَأَهْلُهَا غَـٰفِلُونَ','d4177016d7b35343ca6cb0662eac65442a154b7aac5303731e53c7afc3119c18',8,144,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (921,6,132,'وَلِكُلٍّ دَرَجَـٰتٌ مِّمَّا عَمِلُوا۟ ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ','dc5f143513d3f20d3e34f7b805239c0aa87ebf804ee9dcfff4fe0e87f50a078a',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (922,6,133,'وَرَبُّكَ ٱلْغَنِىُّ ذُو ٱلرَّحْمَةِ ۚ إِن يَشَأْ يُذْهِبْكُمْ وَيَسْتَخْلِفْ مِنۢ بَعْدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوْمٍ ءَاخَرِينَ','80cd3a5c9163a2b42160751fe848c9e689ee5c80d0be830d48ef3ea819273d14',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (923,6,134,'إِنَّ مَا تُوعَدُونَ لَـَٔاتٍ ۖ وَمَآ أَنتُم بِمُعْجِزِينَ','2e36b55907961ab32929f8c89b8d19ec5126ae5fffccc2c1b0322eba6b3311b2',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (924,6,135,'قُلْ يَـٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَامِلٌ ۖ فَسَوْفَ تَعْلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِ ۗ إِنَّهُۥ لَا يُفْلِحُ ٱلظَّـٰلِمُونَ','d1414dec9c9bae0b1130529f161bee21d81f3b94ae8f48572826c98f9ef9b906',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (925,6,136,'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلْحَرْثِ وَٱلْأَنْعَـٰمِ نَصِيبًا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَـٰذَا لِشُرَكَآئِنَا ۖ فَمَا كَانَ لِشُرَكَآئِهِمْ فَلَا يَصِلُ إِلَى ٱللَّهِ ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمْ ۗ سَآءَ مَا يَحْكُمُونَ','4071e529878ed554f10bbf3ef8e40454970661a1c81bb4b0b712034d1160f787',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (926,6,137,'وَكَذَٰلِكَ زَيَّنَ لِكَثِيرٍ مِّنَ ٱلْمُشْرِكِينَ قَتْلَ أَوْلَـٰدِهِمْ شُرَكَآؤُهُمْ لِيُرْدُوهُمْ وَلِيَلْبِسُوا۟ عَلَيْهِمْ دِينَهُمْ ۖ وَلَوْ شَآءَ ٱللَّهُ مَا فَعَلُوهُ ۖ فَذَرْهُمْ وَمَا يَفْتَرُونَ','500e0ed5f435a08219b3b2d9086aad20c725518900f91f963a449be2af927e7f',8,145,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (927,6,138,'وَقَالُوا۟ هَـٰذِهِۦٓ أَنْعَـٰمٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَآ إِلَّا مَن نَّشَآءُ بِزَعْمِهِمْ وَأَنْعَـٰمٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَـٰمٌ لَّا يَذْكُرُونَ ٱسْمَ ٱللَّهِ عَلَيْهَا ٱفْتِرَآءً عَلَيْهِ ۚ سَيَجْزِيهِم بِمَا كَانُوا۟ يَفْتَرُونَ','e1f20dbc0a91f6fb2bcdaf65665f580ed9744a319efb88bd7106a45bd8d64d3b',8,146,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (928,6,139,'وَقَالُوا۟ مَا فِى بُطُونِ هَـٰذِهِ ٱلْأَنْعَـٰمِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزْوَٰجِنَا ۖ وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَآءُ ۚ سَيَجْزِيهِمْ وَصْفَهُمْ ۚ إِنَّهُۥ حَكِيمٌ عَلِيمٌ','f6a1d97900f26493009b7671aec8ddd18bc22dd20a16291aa72e94c57ba94e7e',8,146,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (929,6,140,'قَدْ خَسِرَ ٱلَّذِينَ قَتَلُوٓا۟ أَوْلَـٰدَهُمْ سَفَهًۢا بِغَيْرِ عِلْمٍ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفْتِرَآءً عَلَى ٱللَّهِ ۚ قَدْ ضَلُّوا۟ وَمَا كَانُوا۟ مُهْتَدِينَ','df38685f1e59c27109600b577037b8305502cfe3504cd0dc354cdd2e6d12e4dc',8,146,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (930,6,141,'وَهُوَ ٱلَّذِىٓ أَنشَأَ جَنَّـٰتٍ مَّعْرُوشَـٰتٍ وَغَيْرَ مَعْرُوشَـٰتٍ وَٱلنَّخْلَ وَٱلزَّرْعَ مُخْتَلِفًا أُكُلُهُۥ وَٱلزَّيْتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهًا وَغَيْرَ مُتَشَـٰبِهٍ ۚ كُلُوا۟ مِن ثَمَرِهِۦٓ إِذَآ أَثْمَرَ وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ ۖ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ','19d0749bbcf19eb0b20175d081e9449730321b4e739654921c1f9d5fe5854ddd',8,146,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (931,6,142,'وَمِنَ ٱلْأَنْعَـٰمِ حَمُولَةً وَفَرْشًا ۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَـٰنِ ۚ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ','d9bd91bd3914106c84593e4161521569c27982e08ac11dc3d30c276b966a8b05',8,146,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (932,6,143,'ثَمَـٰنِيَةَ أَزْوَٰجٍ ۖ مِّنَ ٱلضَّأْنِ ٱثْنَيْنِ وَمِنَ ٱلْمَعْزِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ نَبِّـُٔونِى بِعِلْمٍ إِن كُنتُمْ صَـٰدِقِينَ','ea23b9616786b4c7c7871254ca902cefb70397179c6e80c736fb44ec513fc927',8,147,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (933,6,144,'وَمِنَ ٱلْإِبِلِ ٱثْنَيْنِ وَمِنَ ٱلْبَقَرِ ٱثْنَيْنِ ۗ قُلْ ءَآلذَّكَرَيْنِ حَرَّمَ أَمِ ٱلْأُنثَيَيْنِ أَمَّا ٱشْتَمَلَتْ عَلَيْهِ أَرْحَامُ ٱلْأُنثَيَيْنِ ۖ أَمْ كُنتُمْ شُهَدَآءَ إِذْ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَا ۚ فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيْرِ عِلْمٍ ۗ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ','9630131919a1bcde16db01e6712911673d35feb96f3ef49932ae56e232e9be95',8,147,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (934,6,145,'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ أَوْ فِسْقًا أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ ۚ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ رَبَّكَ غَفُورٌ رَّحِيمٌ','d07959963857e1bed569dfdb268738512063763998b41781385f3587fa020604',8,147,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (935,6,146,'وَعَلَى ٱلَّذِينَ هَادُوا۟ حَرَّمْنَا كُلَّ ذِى ظُفُرٍ ۖ وَمِنَ ٱلْبَقَرِ وَٱلْغَنَمِ حَرَّمْنَا عَلَيْهِمْ شُحُومَهُمَآ إِلَّا مَا حَمَلَتْ ظُهُورُهُمَآ أَوِ ٱلْحَوَايَآ أَوْ مَا ٱخْتَلَطَ بِعَظْمٍ ۚ ذَٰلِكَ جَزَيْنَـٰهُم بِبَغْيِهِمْ ۖ وَإِنَّا لَصَـٰدِقُونَ','4aa38377ea452852930a0c4a88f32789f14667cf2641b86cc120bb20b558218b',8,147,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (936,6,147,'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمْ ذُو رَحْمَةٍ وَٰسِعَةٍ وَلَا يُرَدُّ بَأْسُهُۥ عَنِ ٱلْقَوْمِ ٱلْمُجْرِمِينَ','7cb38af130fc2f6833cd793218fe67179afa5a8546cbbfccdefee78f8ce20653',8,148,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (937,6,148,'سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ','d042aa75436387be9c04a76447a0987f5b78751c35dc65ddaaab0539b81b31b3',8,148,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (938,6,149,'قُلْ فَلِلَّهِ ٱلْحُجَّةُ ٱلْبَـٰلِغَةُ ۖ فَلَوْ شَآءَ لَهَدَىٰكُمْ أَجْمَعِينَ','e99558ad2a864f71a67d9778a8d440cc19b7d10b4063b0087954d98e002c8e0f',8,148,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (939,6,150,'قُلْ هَلُمَّ شُهَدَآءَكُمُ ٱلَّذِينَ يَشْهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَا ۖ فَإِن شَهِدُوا۟ فَلَا تَشْهَدْ مَعَهُمْ ۚ وَلَا تَتَّبِعْ أَهْوَآءَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَهُم بِرَبِّهِمْ يَعْدِلُونَ','6642f45582ce7f6eae7a16c1499c08cb3a728467cc9e7c454d1b84a903115639',8,148,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (940,6,151,'قُلْ تَعَالَوْا۟ أَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمْ ۖ أَلَّا تُشْرِكُوا۟ بِهِۦ شَيْـًٔا ۖ وَبِٱلْوَٰلِدَيْنِ إِحْسَـٰنًا ۖ وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُم مِّنْ إِمْلَـٰقٍ ۖ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ ۖ وَلَا تَقْرَبُوا۟ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ۖ وَلَا تَقْتُلُوا۟ ٱلنَّفْسَ ٱلَّتِى حَرَّمَ ٱللَّهُ إِلَّا بِٱلْحَقِّ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَعْقِلُونَ','f5326b62c507cf1b5e5b3cfc97f559abaf2a5ab8fd50754389f0e617b721b2d5',8,148,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (941,6,152,'وَلَا تَقْرَبُوا۟ مَالَ ٱلْيَتِيمِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ حَتَّىٰ يَبْلُغَ أَشُدَّهُۥ ۖ وَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ بِٱلْقِسْطِ ۖ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَا ۖ وَإِذَا قُلْتُمْ فَٱعْدِلُوا۟ وَلَوْ كَانَ ذَا قُرْبَىٰ ۖ وَبِعَهْدِ ٱللَّهِ أَوْفُوا۟ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَذَكَّرُونَ','cb24204b4e3b77d1f392c5b10f7fceaa36d34873240b5528f783d361fa4ad1b5',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (942,6,153,'وَأَنَّ هَـٰذَا صِرَٰطِى مُسْتَقِيمًا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ','3c6257e8884c8d4d0febe0289535884cd827cf0725fb936f5a34997f444ee9d6',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (943,6,154,'ثُمَّ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِىٓ أَحْسَنَ وَتَفْصِيلًا لِّكُلِّ شَىْءٍ وَهُدًى وَرَحْمَةً لَّعَلَّهُم بِلِقَآءِ رَبِّهِمْ يُؤْمِنُونَ','ca19a1cb84a4f275e6a25eed318020a7d275f85edb3244f90cdbba552ea67643',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (944,6,155,'وَهَـٰذَا كِتَـٰبٌ أَنزَلْنَـٰهُ مُبَارَكٌ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمْ تُرْحَمُونَ','1af7d56a91545695e502cdc821acfdcc6665fca2defe0da94b26817de0564763',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (945,6,156,'أَن تَقُولُوٓا۟ إِنَّمَآ أُنزِلَ ٱلْكِتَـٰبُ عَلَىٰ طَآئِفَتَيْنِ مِن قَبْلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمْ لَغَـٰفِلِينَ','5662baf54819f53c81a46e461f2ad456c559ccad4d05e2258f88acb61e6770b6',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (946,6,157,'أَوْ تَقُولُوا۟ لَوْ أَنَّآ أُنزِلَ عَلَيْنَا ٱلْكِتَـٰبُ لَكُنَّآ أَهْدَىٰ مِنْهُمْ ۚ فَقَدْ جَآءَكُم بَيِّنَةٌ مِّن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ ۚ فَمَنْ أَظْلَمُ مِمَّن كَذَّبَ بِـَٔايَـٰتِ ٱللَّهِ وَصَدَفَ عَنْهَا ۗ سَنَجْزِى ٱلَّذِينَ يَصْدِفُونَ عَنْ ءَايَـٰتِنَا سُوٓءَ ٱلْعَذَابِ بِمَا كَانُوا۟ يَصْدِفُونَ','6b26925234a2ec91dd6ca67e2be5576928196e53159f24558e5b5021b1c91f05',8,149,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (947,6,158,'هَلْ يَنظُرُونَ إِلَّآ أَن تَأْتِيَهُمُ ٱلْمَلَـٰٓئِكَةُ أَوْ يَأْتِىَ رَبُّكَ أَوْ يَأْتِىَ بَعْضُ ءَايَـٰتِ رَبِّكَ ۗ يَوْمَ يَأْتِى بَعْضُ ءَايَـٰتِ رَبِّكَ لَا يَنفَعُ نَفْسًا إِيمَـٰنُهَا لَمْ تَكُنْ ءَامَنَتْ مِن قَبْلُ أَوْ كَسَبَتْ فِىٓ إِيمَـٰنِهَا خَيْرًا ۗ قُلِ ٱنتَظِرُوٓا۟ إِنَّا مُنتَظِرُونَ','8e88f93c725a4dc750a177ca3658196baff6747026e5579f59151702562f971b',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (948,6,159,'إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ','fa8301354e7f27a9e650a14afee0dcc3b1ebdff1c26a93210917079255872cc4',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (949,6,160,'مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ أَمْثَالِهَا ۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَهُمْ لَا يُظْلَمُونَ','3dbb1a94b1cfaf00ead7beed1e05947cb764560f0aca3250e96e532ac4d4a9d5',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (950,6,161,'قُلْ إِنَّنِى هَدَىٰنِى رَبِّىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ دِينًا قِيَمًا مِّلَّةَ إِبْرَٰهِيمَ حَنِيفًا ۚ وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ','59fca2654a5b0f7bfa133a62368031c69188d647114be29f1d44d91880581aea',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (951,6,162,'قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ','64d5643f93d0cc78be1b17ec299a45d819bc1e28ddfda2afc3a6a675bb83c5c3',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (952,6,163,'لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ','8ed4e577d1f615daa6111851e58a0c63406d462543cb4b7b62cb1763edcf5fa6',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (953,6,164,'قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ','5852927be5572c74c804ceb1894af96648b3171a43556915d33ea857e9eae40a',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (954,6,165,'وَهُوَ ٱلَّذِى جَعَلَكُمْ خَلَـٰٓئِفَ ٱلْأَرْضِ وَرَفَعَ بَعْضَكُمْ فَوْقَ بَعْضٍ دَرَجَـٰتٍ لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۗ إِنَّ رَبَّكَ سَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌۢ','e2ff08b4d71b3995c2e1a6b775bc6e25f38874b5f65b2842d6d4e433e8129d48',8,150,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (955,7,1,'الٓمٓصٓ','ab3efaf0d357b9410b079d6a661dea89e6d213a0f944bfb76276c7ea00ff0794',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (956,7,2,'كِتَـٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ','273505f58449ff5eb07e0a22c13d5209eae4172111194dfb1b859d1b30340d95',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (957,7,3,'ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًا مَّا تَذَكَّرُونَ','8c472e67b5fd0df80bac194acdbf0442c8df3bb98cd0f343e2934ab7ca2f23d7',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (958,7,4,'وَكَم مِّن قَرْيَةٍ أَهْلَكْنَـٰهَا فَجَآءَهَا بَأْسُنَا بَيَـٰتًا أَوْ هُمْ قَآئِلُونَ','c9857de0094d43dd1340a3e72fd1ca00e25650e0d2c4b95a9991a43c02920110',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (959,7,5,'فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَـٰلِمِينَ','0f2ec6a3ee39a2fb7d12e31e65ce91d616653353644f462c8aa5c558b1242f17',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (960,7,6,'فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ','47a160357beff1a2fb98496fee132c8857109749d72275384710a93031a99d79',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (961,7,7,'فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ ۖ وَمَا كُنَّا غَآئِبِينَ','f1528bddeac46d19cf2a55a0ef3339eb5c5cac06a37fe984b1ae8b8af5b536ad',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (962,7,8,'وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ ۚ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','11dafdfb7c48f749b87134b284051c20fdc2eb58c4890a08e9c81c87c934f80c',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (963,7,9,'وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَظْلِمُونَ','5f0307ebf0fd43ace0ea526e04f3124bc7815bfa122e0a1233d07781954af0f9',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (964,7,10,'وَلَقَدْ مَكَّنَّـٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَـٰيِشَ ۗ قَلِيلًا مَّا تَشْكُرُونَ','233b924b7cbe14b812fc8f51d2681f4686c1b246596e6f243229745baf28b03a',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (965,7,11,'وَلَقَدْ خَلَقْنَـٰكُمْ ثُمَّ صَوَّرْنَـٰكُمْ ثُمَّ قُلْنَا لِلْمَلَـٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّـٰجِدِينَ','50f62dd81f019ff5c31e7261fb17618439c49e19534076c4596cbefe6775f249',8,151,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (966,7,12,'قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ ۖ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ','d4285bbd86be4d34a87def58b9207c3599cdf01e6382c5d9532a4fa3af8c241c',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (967,7,13,'قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ','111d5f9c20a69a9bab16c26fbc74331bf51564a7f34036a68deaf9045cf26137',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (968,7,14,'قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ','b0f6397bd2385fd04579e96ec16170c6e6c572d2c777b012936658e1419037f8',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (969,7,15,'قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ','884cc7cf68fd321f05db3107310def3aab1e9cdff3b829ad66f50b018d7d5e73',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (970,7,16,'قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ','e65b5449b4be8447b6c8df57ba235d16c6eb864672a1205c1959501e31566fd2',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (971,7,17,'ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَـٰنِهِمْ وَعَن شَمَآئِلِهِمْ ۖ وَلَا تَجِدُ أَكْثَرَهُمْ شَـٰكِرِينَ','43a9860341423c1484ae8a6cb465d16ccc6f3457efaafdfc3ed1cce16b0def74',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (972,7,18,'قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا ۖ لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ','08cc0d770223e70d1fa3cb5e0634b6025f10db2ba257231a9955bec2e9291bfa',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (973,7,19,'وَيَـٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ','c6d36d804efef3b1d62c781ba441892bdf69ea925859b63a7aaa38dc4084b68a',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (974,7,20,'فَوَسْوَسَ لَهُمَا ٱلشَّيْطَـٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَـٰلِدِينَ','259362283a18055a726efc3d8c95036f9fe6e5c7138394dd914cf5fc328c6267',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (975,7,21,'وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ','349fd17f860aad02071034d91da603e547c024da6671f968ef46176064cc81db',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (976,7,22,'فَدَلَّىٰهُمَا بِغُرُورٍ ۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَـٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ','97cd4b5b67e5975be52c3195c4569ab9484a33311d917edb026bb05c4be76da1',8,152,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (977,7,23,'قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ','87106c2a6bf56f5f3d816ea85fa7c1fdc21971327af61d4c910b037a4208f639',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (978,7,24,'قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَـٰعٌ إِلَىٰ حِينٍ','be169f75f191954ac4ab9e50b20f6a5be31a77d97567c5cc9b766c4606b1385b',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (979,7,25,'قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ','c847c4de790d45f751bfed4c7bdefdd79872f4631bb366ac2e8893d78e1b93f3',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (980,7,26,'يَـٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ۚ ذَٰلِكَ مِنْ ءَايَـٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ','e3c7052c7f2cfb21b08752772662e00df5d809efb339f429670192e6b966bb11',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (981,7,27,'يَـٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَـٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ ۗ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ ۗ إِنَّا جَعَلْنَا ٱلشَّيَـٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ','f28436920c267a33be68c9fb5a3d16479bc3617e19c283c69602b5b71d9bb7a8',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (982,7,28,'وَإِذَا فَعَلُوا۟ فَـٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','2049d3c9c8a3c42491cc7e70e21ee6a5dea069106800d85b02022b1dd658b4ea',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (983,7,29,'قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ ۖ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ۚ كَمَا بَدَأَكُمْ تَعُودُونَ','23f485cdd9c2afd36d6d3f3bcf49a88be7e51bbd55d567da348aca3fad2b9b78',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (984,7,30,'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَـٰلَةُ ۗ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَـٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ','b00f3dc735f30ce4d7ffa25e4f2ca90d0e5b921bffe8b016e7b0b86cd22782bb',8,153,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (985,7,31,'يَـٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ','8ea30463dc91283278ec73559a8fc3726267e338cf94eed50b402a8eff6f0c07',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (986,7,32,'قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَـٰتِ مِنَ ٱلرِّزْقِ ۚ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَـٰمَةِ ۗ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','450a81d44e4c22a3a95bfe727ca4444f30070d3a437eb1a1452bebbf4a8ee9f2',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (987,7,33,'قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَـٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ','789401405da9a5627159609bfcf0ce944df17080f29596392f56aa32437067b4',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (988,7,34,'وَلِكُلِّ أُمَّةٍ أَجَلٌ ۖ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً ۖ وَلَا يَسْتَقْدِمُونَ','19cf6cc90d43447a167d85484e76f0c680e297c0609e6ddf7b1048ca488f3037',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (989,7,35,'يَـٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَـٰتِى ۙ فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ','d12d83aa4af54e6262b31e97f2345789bf365039d0b10723c309e1c0f0db8f1c',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (990,7,36,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','7a8bba26a361632ebceb2029786e536d402a7b06920406168b61cdf6e73c42da',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (991,7,37,'فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَـٰتِهِۦٓ ۚ أُو۟لَـٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَـٰبِ ۖ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ ۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَـٰفِرِينَ','b68a966a7cf09e770c139591be4406210e737c588d8a84563ee353517a0d8646',8,154,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (992,7,38,'قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ ۖ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا ۖ حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ ۖ قَالَ لِكُلٍّ ضِعْفٌ وَلَـٰكِن لَّا تَعْلَمُونَ','ef02e3e85067b0b7dd8b3a9f1d5440b861f3f692ca8544ac78cadb3f3be7f137',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (993,7,39,'وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ','67434324d09556338d729d8e8f97d329cdbdc1ad42da6908409b2241dbfa000a',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (994,7,40,'إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ','ebcf9b083c137044ac91e71144e511a63e98d216d32e2a730924687852ee7a41',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (995,7,41,'لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ ۚ وَكَذَٰلِكَ نَجْزِى ٱلظَّـٰلِمِينَ','3c392ffda3fbd4651f2e3c943c5b47ec55dd9948dcb2de8fdb29a4ddc5e7c81b',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (996,7,42,'وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَنَّةِ ۖ هُمْ فِيهَا خَـٰلِدُونَ','90258b0f373ed4b63098dbed217c04e991e860611f8f36588ea82d5b42ee3394',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (997,7,43,'وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَـٰرُ ۖ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَـٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ ۖ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ ۖ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ','16518cc8b9a1f37d78a1ffe363738dcac7808a1d4935cbd0d496b7d6bfab648e',8,155,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (998,7,44,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْجَنَّةِ أَصْحَـٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا ۖ قَالُوا۟ نَعَمْ ۚ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ','d6a8ee71879ce29f9b14ad91f7cda38d175b6781727c7bf4cd26b3fdf906a645',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (999,7,45,'ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَـٰفِرُونَ','6dab2eb411bc5eff3130ee4db6f1cd90a75cfc85dd1c90260aec74387b8c028c',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1000,7,46,'وَبَيْنَهُمَا حِجَابٌ ۚ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ ۚ وَنَادَوْا۟ أَصْحَـٰبَ ٱلْجَنَّةِ أَن سَلَـٰمٌ عَلَيْكُمْ ۚ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ','049b5f6bf91cbea94c7fdabe909b559eae39081df21cf5f5e8dcdf2140ab655f',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1001,7,47,'وَإِذَا صُرِفَتْ أَبْصَـٰرُهُمْ تِلْقَآءَ أَصْحَـٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','1604051b0a6d6d052777bf660f91c7cecbf33d3f589ce10765bd1011179a989e',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1002,7,48,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ','362a32b03f80d329b60bcd48595714d1d39bba9884b9b8e693c98c1df2a871f1',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1003,7,49,'أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ۚ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ','791d082fcd581ceffad6a6ca5f143f2f54e5f92b706d3f95ed86663297f30f2e',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1004,7,50,'وَنَادَىٰٓ أَصْحَـٰبُ ٱلنَّارِ أَصْحَـٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ ۚ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَـٰفِرِينَ','9c2bca34b802d1b6b7f1530238540d6c8d4d94258705286e1464b61cb6137406',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1005,7,51,'ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۚ فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَـٰذَا وَمَا كَانُوا۟ بِـَٔايَـٰتِنَا يَجْحَدُونَ','f2cad8cd58f3404b8d9349be946cdba64d8b4de01503de0aca18b049baaaccf6',8,156,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1006,7,52,'وَلَقَدْ جِئْنَـٰهُم بِكِتَـٰبٍ فَصَّلْنَـٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ','dbec95832b69f76be50f944681041011902de339ac9df8328a62d5a5daa981cc',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1007,7,53,'هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ ۚ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ ۚ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ','3b169b5b5136cf63971adf625721e8f6b3389fd0eed1e265fd33b6dd836b2491',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1008,7,54,'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ','5e6df242aa74d21c9a14f0346796f2517a97fdb632ea71fb4da438a323d9708d',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1009,7,55,'ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ','e02ade80d2198e1bf37d0a6cf6199e40b39953129c06b89f277467ff1c5e02b6',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1010,7,56,'وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ','de50eb0982f475a878cb2aa4dc3e31b094513288a29b0e683a084e0a2b47e099',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1011,7,57,'وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ ۖ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَـٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ ۚ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ','b3c310ed79ef2b3272feb6d4d9978e32164d821b822fa3fb734f9d7296829c4d',8,157,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1012,7,58,'وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ ۖ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا ۚ كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَشْكُرُونَ','518c9973a3883f1738669a24dc3abe8e81d09a6941bdfe259eb37b321b42715d',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1013,7,59,'لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ','d2e5cf0d9a13f7f6222ac2897068c54fdaf7715d552df81f71d46bc204b045b4',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1014,7,60,'قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَـٰلٍ مُّبِينٍ','0f8388a4373bd069ff6667fce0282b03590780926192cb9bb247ac05c888d3e1',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1015,7,61,'قَالَ يَـٰقَوْمِ لَيْسَ بِى ضَلَـٰلَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','ff8b2dd453ed319b40b0392a7adb06164a1cd07fa8969c99f6e181622615eb8f',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1016,7,62,'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ','0e028cecbcba79137bf4f5d49b4d0cbf9d3c9c8b10ac7db618157690b0e570ca',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1017,7,63,'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ','cd5309fbcf66144202d8ba9874dfe30b930a3dd7218f521120b6a5254e3d33ca',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1018,7,64,'فَكَذَّبُوهُ فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَآ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ','9757c326be51aa4a92859bf0ddfaa234a7cced6fe66c658e5a197f216a01c8d5',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1019,7,65,'وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ','e1a85409023919ca5e0d1c021c6e1732db0fd857b92da45ee79c8cb83d1f5614',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1020,7,66,'قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَـٰذِبِينَ','ce11cb176e025def7a71b54fd01144cd63bb723ed479ff62e0baf71c657f26de',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1021,7,67,'قَالَ يَـٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَـٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','321fa42c7c6c1ce2be4ecfe1747092a8f8811d304e09493bc2c99050adb957c9',8,158,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1022,7,68,'أُبَلِّغُكُمْ رِسَـٰلَـٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ','4b0c0efab87e6369b76675ebdc9e959462bc99c7a5f5b3fddc755d1438381fe1',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1023,7,69,'أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ ۚ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ','cecb7a03c462cd3b4edb4450694947e8fca8e189987afebdd7e327e1a6fb520d',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1024,7,70,'قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا ۖ فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','a7b0ab9dec5ac5c2cb94e4aa9b6ab06d7ebda9e810ff7ab1dfbf20113dcff28c',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1025,7,71,'قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ ۖ أَتُجَـٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَـٰنٍ ۚ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ','35ae12cbb0d417b0c2b2403673e204cfe366992f19c4d95f1c822d978b07d8ce',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1026,7,72,'فَأَنجَيْنَـٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۖ وَمَا كَانُوا۟ مُؤْمِنِينَ','7e5e7a79b9f5b740f2b14b7c3818c71580b113beb67497f20517bceebda5a5c1',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1027,7,73,'وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ','3e3a654a7fb2b545d6b1ba457b280971e0ef4d52fda973d5263392172733c4c5',8,159,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1028,7,74,'وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا ۖ فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ','cafc7d9a66e06fe3523333a69ea20f85c2256333cb7f36ac297b28f36e0b50be',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1029,7,75,'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَـٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ ۚ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ','377075eb52137b9cbc38375fcfbe7485fbc6cc328ff00a07d7e21d9ac0601e40',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1030,7,76,'قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَـٰفِرُونَ','82d6e73d45c62b51ad7d09b656d169aad68016ad7bbbb2d195274661ff5ffd11',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1031,7,77,'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَـٰصَـٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ','e41d6cff9f8b3cc68b0e592f23ffee30a7470e391a85d33965b71cdc9afe317b',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1032,7,78,'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ','486940edd10a0d362add2cd24235777d8e2040bd7b74984849411bc2e36f39ff',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1033,7,79,'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَـٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ','f0f9ae77bf153d3cc0a4c4bf09abe12d67724cb9518fe7310e89df8643e5d294',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1034,7,80,'وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَـٰلَمِينَ','eae0a8d448a92e8ff76bab5d9737682504b38218643583380f3481b2f18ca5f7',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1035,7,81,'إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ','33809f9a1953da2ee5cc6940d663fed003c628e14344707be077992a25e19593',8,160,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1036,7,82,'وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ','36821df326e49ec431d504b5df43f6717b34f1ad4c5f1054f1799068271db0d1',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1037,7,83,'فَأَنجَيْنَـٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَـٰبِرِينَ','a5ce748fd6d850f598f43a37dd13cb3bdc907d97eed5060e2093cc77c4ef5362',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1038,7,84,'وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُجْرِمِينَ','23c71bda747bf4d5583d3ee1cb1aacbaf4bcf8c80eaaf8d11681d5126b49c11c',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1039,7,85,'وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا ۗ قَالَ يَـٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَـٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَـٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ','2e6f329c82bb3264d4a678a05399ceaa622321c69c2622ae1d1a9296a5d41da6',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1040,7,86,'وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا ۚ وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ ۖ وَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ','1f252bc13544dfa73b37442ea164f565ab4b2004b4d833fea512a637e03013f4',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1041,7,87,'وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا ۚ وَهُوَ خَيْرُ ٱلْحَـٰكِمِينَ','92d5286932234b921310ca7195d36343c5e00513b4f58b5a3e6148179c548d38',8,161,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1042,7,88,'قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَـٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا ۚ قَالَ أَوَلَوْ كُنَّا كَـٰرِهِينَ','bdb1392fe1ba97bf02227bf36f28b3d139244cf6b256449b02609531b8cba14e',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1043,7,89,'قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا ۚ وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا ۚ وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا ۚ عَلَى ٱللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَـٰتِحِينَ','a87d646f6ecf670061bf9d00d2e82b02db0d010af3afccdb780c044e35fe8a6e',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1044,7,90,'وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَـٰسِرُونَ','2069d8e1dde1976649e888544574331d020e2d1f66f7785c8d65aca9da7481b4',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1045,7,91,'فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَـٰثِمِينَ','486940edd10a0d362add2cd24235777d8e2040bd7b74984849411bc2e36f39ff',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1046,7,92,'ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ۚ ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَـٰسِرِينَ','e2694cb40f2cf544a846e01188ec5124bd1fd3857da511e3b210425a74fe19f8',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1047,7,93,'فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَـٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَـٰلَـٰتِ رَبِّى وَنَصَحْتُ لَكُمْ ۖ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَـٰفِرِينَ','2cf06d37a2d8e906fcc366e196b55679726b265278e799145049e1cbb4677ee5',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1048,7,94,'وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ','f78bdbc9d1223fd2310ef3c21f2fe14a080d1bf001cf59dc0e608bd66bc733a2',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1049,7,95,'ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَـٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ','25b72d1ffa0fad404e36644a4f67be7989f9382ea145061a163917d91b0f1010',9,162,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1050,7,96,'وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَـٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَـٰكِن كَذَّبُوا۟ فَأَخَذْنَـٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ','b9a6ad37f3f627eef5452e4b88abe568094d036291271956234384ab2e41d51a',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1051,7,97,'أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَـٰتًا وَهُمْ نَآئِمُونَ','f1a13e115560213a40d85d993c1b04b5457358f8f30b779f48cb43d5b7715d7d',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1052,7,98,'أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ','68121cc1b76892f8f9837c58649baee022673815b2e8fd82517bd886065f153d',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1053,7,99,'أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ ۚ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَـٰسِرُونَ','07bf74f24f132c143e016f7e770c58e1ac36db49f747af04907c7d43e6fa322a',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1054,7,100,'أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَـٰهُم بِذُنُوبِهِمْ ۚ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ','91aac1bd6669225917aef369750e9ab8aa67a465a41d69ed7693e40c734a1011',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1055,7,101,'تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا ۚ وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ ۚ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَـٰفِرِينَ','55e8369d6f7d6d1918bf3500921347a785f346b3e40b7f0ccb0dd8c068631309',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1056,7,102,'وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ ۖ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَـٰسِقِينَ','7e7aa4a3e1855172f3dad70cb23ab023ec70f918cdb25cf3cd323072d108794f',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1057,7,103,'ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَـٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا ۖ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ','4c29d29e497c1cbd266e6b37601600930634f3ef72c61d3e90394aa12af8fda4',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1058,7,104,'وَقَالَ مُوسَىٰ يَـٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ','a9b8cc59325933167afc20d22a7e23a246ed4c29c481f020cd8f81d04250711d',9,163,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1059,7,105,'حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ','4d88704f43f91f052fad71a55477744e0ad9a7ef7cf401906fbda68cb1a64e0e',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1060,7,106,'قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ','2b88658d289120b084e9599eae8c680c0b6e6223e048aff0a8a83908f339edbe',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1061,7,107,'فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ','ca1e9a42b2bb560c3e07f5c3975985e11cbad81314678a2dd0600fee138037bc',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1062,7,108,'وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّـٰظِرِينَ','e8fff9a7116600223b8352fd2eea972161d0f3e034d0147009d01b5e36dd87e5',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1063,7,109,'قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِيمٌ','550f1f8eb6d294e86d504429edb50ace4e7b84b60d43e7ed23dbdedb2bd243a7',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1064,7,110,'يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ ۖ فَمَاذَا تَأْمُرُونَ','3f4da148a111e82f67ba225b1e7c7e92df8b008e7e2d154c6db2e3eba5bd1911',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1065,7,111,'قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَـٰشِرِينَ','e94979891f35daca17855378ef9f6bc11030292fcb3bd6297c1b8330480e6a77',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1066,7,112,'يَأْتُوكَ بِكُلِّ سَـٰحِرٍ عَلِيمٍ','4fc8820809cdbe818e9cc5554c23c212b735d8acd73e740669ec57ed449fa29d',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1067,7,113,'وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَـٰلِبِينَ','d0128b57bd81f41a1ce5628015d0b8fc2a73a5a7b932a4d92b3fae03d2afb664',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1068,7,114,'قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ','ba9fbf05ffb6e14162827c3e9944649d459ddc280b873adffe775b8817d9a817',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1069,7,115,'قَالُوا۟ يَـٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ','7813f19701b96276869ddc25687528a8e2b3e7c52f253ba33d467d46a306f20e',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1070,7,116,'قَالَ أَلْقُوا۟ ۖ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ','85d675ae8de8fd0a63bee86e5443a12467cf22bba5fe7cfc1f8154f42141a380',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1071,7,117,'وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ','525a4e33febbe5173da29e371517e248450323275947c8d1b79d73dfeddda549',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1072,7,118,'فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ','49efede1a535e62fa3db074ee83c032795385c33b0df132e766a156c689d2fbb',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1073,7,119,'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَـٰغِرِينَ','b893d09d5f9b5fea425ac33fd40549fbbe6aa5ee2516105e973d790539443dfb',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1074,7,120,'وَأُلْقِىَ ٱلسَّحَرَةُ سَـٰجِدِينَ','b6b944d63703d2601b0a9d13242a23f516a0e8b91d62064fa0aa040ed49cf084',9,164,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1075,7,121,'قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَـٰلَمِينَ','7599ad6f0e40390934d92090a4f17a65896d012df25c9d23e06bf843022f9c84',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1076,7,122,'رَبِّ مُوسَىٰ وَهَـٰرُونَ','cf6ff620bb8b6cc1b6352d612f3fcc59b2446b4e42bc446e46bdef9c475ecb9b',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1077,7,123,'قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ ۖ إِنَّ هَـٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا ۖ فَسَوْفَ تَعْلَمُونَ','b60dca475d35a82153109bf372cceeeb73e06c8bece99e043fa051fd14dc6cc3',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1078,7,124,'لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَـٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ','615f292028a89b12aa1db2e10bdb2723666796b6a389a69229427f362efa0371',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1079,7,125,'قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ','bac7bb4219968574120f1e397d954bf9496b5b0941ebd2ecaf11006c521e28db',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1080,7,126,'وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَـٰتِ رَبِّنَا لَمَّا جَآءَتْنَا ۚ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ','078fe2851576cf3722102ae964e83dd5d754cb89383dcd09574a3f15a536a232',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1081,7,127,'وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ ۚ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَـٰهِرُونَ','eea8ce0658b94afecf2b4bb41565782a64f3a490985a856d71570ebf1f98c3e3',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1082,7,128,'قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ ۖ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ ۖ وَٱلْعَـٰقِبَةُ لِلْمُتَّقِينَ','247da95cd48d17d50931eb59a836de8248f88dc8c51b2a39a1d48abd7b5bf6d6',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1083,7,129,'قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا ۚ قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ','9fbccfad41461cd7d87290f94d4e28f5c04d517b9388c97641514ccf748ca1d7',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1084,7,130,'وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ','15c94dec33ce082681d693ecb5dea1e85f8debe1fc31b80de8406eaabe4ee67f',9,165,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1085,7,131,'فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَـٰذِهِۦ ۖ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ ۗ أَلَآ إِنَّمَا طَـٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','eb50c607dab9d997a0b2f400c68538531c4fa57a19a4b37321be04f456361f4a',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1086,7,132,'وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ','a2dd973363a45fdff0c61635b782a727584f5670aa59cec237a54ef9659ac68d',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1087,7,133,'فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَـٰتٍ مُّفَصَّلَـٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ','c1d28fd697e68e6e848a353d707efcd83f8de5c882b907a16d3c15f95709710f',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1088,7,134,'وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَـٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ ۖ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ','85a654dd74a27d6d6f20abf5919c000887d06d1909156d4008704d54c76ee166',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1089,7,135,'فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَـٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ','80b19a829d888f7bc0f970e9ad5b17b6795c43e0d4521725f90a95b5cd8f2428',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1090,7,136,'فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَـٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ','9c5a414eefa0eed0f23ce9c2e6f4694c9f4371d3e9af9c0fa1c060513c351923',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1091,7,137,'وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَـٰرِقَ ٱلْأَرْضِ وَمَغَـٰرِبَهَا ٱلَّتِى بَـٰرَكْنَا فِيهَا ۖ وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ ۖ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ','707ab7b6b40dd4560e51799cd90cb485ebdc059458b16ae2f1c297a1ee5db6a7',9,166,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1092,7,138,'وَجَـٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ ۚ قَالُوا۟ يَـٰمُوسَى ٱجْعَل لَّنَآ إِلَـٰهًا كَمَا لَهُمْ ءَالِهَةٌ ۚ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ','c3d19f54a5b90842ab0193b8bbb816a9893b62b3908067064cee636a46ce7a76',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1093,7,139,'إِنَّ هَـٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَـٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ','c4ef26a444ec3b483e6f42527b05eb9c3119faac3b812d86cfdd44daf11a32a3',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1094,7,140,'قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَـٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَـٰلَمِينَ','867c80dc47d6b6bd9f02dbbe4787033b71b19fbd9add8320ffbb6adffcf59e03',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1095,7,141,'وَإِذْ أَنجَيْنَـٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ ۖ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ ۚ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ','27c12de61eba6ad588394fb0f8fb94ee634efee832c3c5b8d43baad219e75cbf',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1096,7,142,'وَوَٰعَدْنَا مُوسَىٰ ثَلَـٰثِينَ لَيْلَةً وَأَتْمَمْنَـٰهَا بِعَشْرٍ فَتَمَّ مِيقَـٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً ۚ وَقَالَ مُوسَىٰ لِأَخِيهِ هَـٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ','83d47e0afb958b82a5a454bc134bc1388564b4e85eaf29093c23078e45ea749b',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1097,7,143,'وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَـٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَـٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَـٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ','742e540d03712fddc17d6354d7a491d8ac8bfdc37180e92582f0e476d1706cd2',9,167,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1098,7,144,'قَالَ يَـٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَـٰلَـٰتِى وَبِكَلَـٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِينَ','6c26748b6495f061ff647367f38f8fc95e196ebcdc818604478ad1076057752c',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1099,7,145,'وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا ۚ سَأُو۟رِيكُمْ دَارَ ٱلْفَـٰسِقِينَ','a33be0a391e257876dafea428423ca8f62e5bf0e2d1c8c97a40323c714d64fc4',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1100,7,146,'سَأَصْرِفُ عَنْ ءَايَـٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَكَانُوا۟ عَنْهَا غَـٰفِلِينَ','5672c66373a61c9b0efa9389c84bfa11fa2a858b6fa76fb1261cc63d9990edb2',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1101,7,147,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَـٰلُهُمْ ۚ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ','5bbf948b6e8fa6c51bc90f0fc3119f0c8db2c88147ec1c64a3569e6cb56715ef',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1102,7,148,'وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ ۚ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَـٰلِمِينَ','c4324fbe354de79bdabd61bbca491bd6d8f0503651290e74defc5f3b19232a83',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1103,7,149,'وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَـٰسِرِينَ','c3e0144e54721b4f63e84d40587781a83c0c37e6fc5dfcfafae9fdf65536fc59',9,168,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1104,7,150,'وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَـٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ ۖ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ ۖ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ ۚ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ','ef5918cc62774a21d8e3ec2accc3b4d06ddef1ecb10b5d037e4ff7b931a1af6c',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1105,7,151,'قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ ۖ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ','6d3426332c2fa3f7c6cec53ac46e1cf7b2aa9d3d022c2106ca0c9d7984413535',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1106,7,152,'إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۚ وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ','e64279a39d5cb39e32559079c5b13f7e79697266333748a0922a9841ef8d8b6a',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1107,7,153,'وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ','32b8f52703ca67a5ca92e37f8653c1d6f7b486e37c593b4e67e143c47075f463',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1108,7,154,'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ ۖ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ','c095793160c56b28d9ed331f5e0aea27f9e173b61400f1a0eb9b151b87ca4347',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1109,7,155,'وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَـٰتِنَا ۖ فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّـٰىَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ ۖ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ ۖ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا ۖ وَأَنتَ خَيْرُ ٱلْغَـٰفِرِينَ','42055f52c68e8599f49cb333d58e1f79098b7f5cf481d3896e237a30858d6b4d',9,169,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1110,7,156,'وَٱكْتُبْ لَنَا فِى هَـٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ ۚ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ ۖ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ ۚ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَـٰتِنَا يُؤْمِنُونَ','2787e40c255401755fb4557c7a831077becdfdc6bd7c7a173e4e7f551f5de438',9,170,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1111,7,157,'ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَـٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَـٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَـٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ','a282dffc34195b55bc19cffbc298e546da5513e2d9d9afbba395cbf2e6bb7c60',9,170,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1112,7,158,'قُلْ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ لَآ إِلَـٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَـٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ','7f809130911c084036f1c92b5a3ef120adb908a6f38ecfd5246418b0c2b26d47',9,170,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1113,7,159,'وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ','f0aa87609e8f4c1aef6976a8bcd35346806113719f21fd1d63d561829c0bf74a',9,170,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1114,7,160,'وَقَطَّعْنَـٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا ۚ وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ ۖ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۚ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَـٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ ۖ كُلُوا۟ مِن طَيِّبَـٰتِ مَا رَزَقْنَـٰكُمْ ۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ','887b6e3f65cda8d61f392e3528ac5b4cd599e7a2f18221d52383a16660616d55',9,171,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1115,7,161,'وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَـٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٔـٰتِكُمْ ۚ سَنَزِيدُ ٱلْمُحْسِنِينَ','578f22f398083f4f3ac9b30ec78f72f6e8640d8da1d55a6325ea59a7a72cd515',9,171,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1116,7,162,'فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ','c7984d11fa5de44bad74d608137df9c9efd91e979dbd05665896fe947cc31bde',9,171,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1117,7,163,'وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ ۙ لَا تَأْتِيهِمْ ۚ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ','5aa12caaf8718920a160c247a3f9c40cfbd0c492df977ec7954979f784e415d7',9,171,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1118,7,164,'وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ۙ ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا ۖ قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ','8b29fd89a538147acf5281f8c9966d3503f5f8defd39ff9b986c1b8b65465246',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1119,7,165,'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ','58685f822c533614fa63736011d7857c1b3a24c40a6961ef8ca294a5860d00e5',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1120,7,166,'فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَـٰسِـِٔينَ','7cb80bc6c8afff8a72505e077be19fddc41115b330783dc15e89ca653188897c',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1121,7,167,'وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ ۗ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ ۖ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ','1c15b1c95af6e80d1c7f825a6292bdd6ef8211a9c40fdf42c331b8ec43a5fe07',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1122,7,168,'وَقَطَّعْنَـٰهُمْ فِى ٱلْأَرْضِ أُمَمًا ۖ مِّنْهُمُ ٱلصَّـٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ ۖ وَبَلَوْنَـٰهُم بِٱلْحَسَنَـٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ','787a5e6e5fdbd2a662b709f4a77c97bee8de61fecafc7136578675884290f6e7',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1123,7,169,'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَـٰبَ يَأْخُذُونَ عَرَضَ هَـٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ ۚ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَـٰقُ ٱلْكِتَـٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ ۗ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ ۗ أَفَلَا تَعْقِلُونَ','16245131bacc3b65618207e2bc3b12355dd115291b6a749a9bd399e5ebfd00b9',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1124,7,170,'وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَـٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ','4c0096122b70eb7461d5b7aada54d634a68f7e99e4a0c9e6551dc902b741d120',9,172,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1125,7,171,'وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَـٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ','ba7b4a718ee16f956d9597f2eabc28170fd1be7275e1b1da3a91d9cb5dcb7873',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1126,7,172,'وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ ۖ قَالُوا۟ بَلَىٰ ۛ شَهِدْنَآ ۛ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ إِنَّا كُنَّا عَنْ هَـٰذَا غَـٰفِلِينَ','9f90a6965144a167afd8b0c54949f905f6d30d805f024ce65705cb84bb5fc0dd',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1127,7,173,'أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ ۖ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ','20340391df482712858ffe110a87d7bd0d67ed3030733e5e320174653e097e9e',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1128,7,174,'وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَـٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ','a819b6950164088658cbcb5d925660d53c2ec77d7e93cffd88be24827fee19cb',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1129,7,175,'وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَـٰهُ ءَايَـٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَـٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ','2d0968713837bb515d30ad18808d6826801766a10e3338c31fd1d1f969dae66f',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1130,7,176,'وَلَوْ شِئْنَا لَرَفَعْنَـٰهُ بِهَا وَلَـٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ','7cf2ce9279556dd4276462bfbe1a8038eb0e079402c6edc0d595cf43eea0d5a3',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1131,7,177,'سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ','6a8644cd0e191d31dafa28226fe4823758e52fc6a31ff4195dd085e17b8ac424',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1132,7,178,'مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى ۖ وَمَن يُضْلِلْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','2c02395003adda7622d8d9c101f81db3115aece4fa31a4b4ce5442a74c7db5ae',9,173,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1133,7,179,'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ ۖ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ ۚ أُو۟لَـٰٓئِكَ كَٱلْأَنْعَـٰمِ بَلْ هُمْ أَضَلُّ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْغَـٰفِلُونَ','9c3075bb673d7ce5fd063705880f97db7f26b105f5d533e78a9ff3f8d8f54e34',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1134,7,180,'وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَـٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ','6808223360567892bc0ed5b0946504dc5cead56173602ca818b26c4de0331cb6',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1135,7,181,'وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ','dc1dcd8ba4a54da16568271da840a3fbd5ce329436fecad669d3ef237b6239f9',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1136,7,182,'وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ','2f08f5fd4e956b55296376aea2c8cc747738ad76b36d291a5b4a871631cb742f',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1137,7,183,'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ','37b88f8bfed5edc20c945795090e8fa093d0f0bbe98363782c0f2125af57685b',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1138,7,184,'أَوَلَمْ يَتَفَكَّرُوا۟ ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍ ۚ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ','bae6e52c8733df8d0e79b8c8c9af6785d7cf905349b3bfd243f469af636281e3',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1139,7,185,'أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ ۖ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ','c5148c649105ad644d5668e4160d98be7e20d3d82dbec5447c2717b9c28c4876',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1140,7,186,'مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ ۚ وَيَذَرُهُمْ فِى طُغْيَـٰنِهِمْ يَعْمَهُونَ','32408b8b71ce24507c20d164c9a9be15bbfbc08eb0805764813414c0001a06ea',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1141,7,187,'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى ۖ لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ۚ ثَقُلَتْ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً ۗ يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا ۖ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ','e4146e55b466e174eb73a909a88c2dab4255cf71ef11722147650262f5570fb9',9,174,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1142,7,188,'قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ ۚ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ ۚ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ','afc531b3f00b4dac4f86badb5b4a26e717c7e3a8b2c1916733e40c1b6686ff36',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1143,7,189,'هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا ۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ ۖ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَـٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ','847a626467195e66e5463c05006054a3f0807348bcab3703129ddffe9551b609',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1144,7,190,'فَلَمَّآ ءَاتَىٰهُمَا صَـٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا ۚ فَتَعَـٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ','ba545f223efb2709aac213d213ddf0fc4155c4fd14d6eeba68ff2f56b8de3847',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1145,7,191,'أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ','27bd0a394ba6c8d81f84730432bf34c009849d192654c88bbdcbe4f580f8175e',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1146,7,192,'وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ','925dcb70a3b4ff8f654da248d3c44a50c6c5d5d9a3cb51d94cf764203526da82',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1147,7,193,'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ ۚ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَـٰمِتُونَ','7d68a41eb3811a040d17cb4690acaea73b40ab00bd0b269d669a94d00fd3c74b',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1148,7,194,'إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ ۖ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَـٰدِقِينَ','661074bace5dfabd29fd15ab3ebd1e7426cf8cec87c1bfe1e0df448a741f42c0',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1149,7,195,'أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ ۖ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ ۖ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ ۖ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا ۗ قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ','066d1bdd75d583f28f0386e80498152b5b2f255bce5ad92dab4e11250a71235f',9,175,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1150,7,196,'إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَـٰبَ ۖ وَهُوَ يَتَوَلَّى ٱلصَّـٰلِحِينَ','42f914b2437905c8323e69f3f8760fbd31fd9c26d699bead5a2b63bafd7b4ae8',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1151,7,197,'وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ','73e747aef2be958d01650ca6babfc37c2c889447b71b722dcedf8ec67b4345ee',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1152,7,198,'وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ ۖ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ','1c9c05e9920aa370f97937ec84b7d547af3ac01b6d04a1330758ce8db62eb3c4',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1153,7,199,'خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَـٰهِلِينَ','ba1239ecf9a06881c9887b833dde7d566e36c495532454bb6312317c485d6bd5',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1154,7,200,'وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَـٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ ۚ إِنَّهُۥ سَمِيعٌ عَلِيمٌ','5ae580c159b220b2b3e4b454333cb7f082019a85221da6555abe6422f5a73026',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1155,7,201,'إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَـٰٓئِفٌ مِّنَ ٱلشَّيْطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ','8db7c7d1592ae585f31f2cfd933b655a68e3b6188443387fa853734c4aebccb6',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1156,7,202,'وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ','4672bc9d2361b46a2b1805858a243b0dd3e3705ae96398c6b15341b75710563a',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1157,7,203,'وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا ۚ قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى ۚ هَـٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ','3fd76a1c7b331202ffdeef19f12e72e3caaaa500557a5c722445065191a902c2',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1158,7,204,'وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ','303db4f032734fec17c45cac16840f7733d2a416e81bb2f3734de123843cd92e',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1159,7,205,'وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَـٰفِلِينَ','f5c0889c3a0269b08084442523ef46fd0e71b0c524a332784ee7903f0430b96a',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1160,7,206,'إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ ۩','43478a69e696c6833a3250395dec7fed6131aec9db0d3e8f555dd40e6c817a89',9,176,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1161,8,1,'يَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ ۖ قُلِ ٱلْأَنفَالُ لِلَّهِ وَٱلرَّسُولِ ۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصْلِحُوا۟ ذَاتَ بَيْنِكُمْ ۖ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤْمِنِينَ','9fbb96eab61fd5caeedf222f32ae3e6ed4e7a35d691f58cea9e326311f1c4544',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1162,8,2,'إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَـٰتُهُۥ زَادَتْهُمْ إِيمَـٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ','e062a4dc68099cebc3a1de15806ca50d002537d53cfe75903e02f6ab37e632d2',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1163,8,3,'ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ','3fa57a9b84286e035cc9fdf392fe98492af5e68d2bb12be1f4dcb298cd67f70b',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1164,8,4,'أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُمْ دَرَجَـٰتٌ عِندَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ','8db89000311effdfc72efba206401fa835d71ad33be8859feea3d0b2502cdf45',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1165,8,5,'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِٱلْحَقِّ وَإِنَّ فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ لَكَـٰرِهُونَ','245b580bc0313c7e51b75e91bad45e2cbc22153a198a141e5f8b122a7712e74c',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1166,8,6,'يُجَـٰدِلُونَكَ فِى ٱلْحَقِّ بَعْدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلْمَوْتِ وَهُمْ يَنظُرُونَ','59a1414e66ef786bef0e706e738b1b4acdfd06016175e130e52415c363f990b1',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1167,8,7,'وَإِذْ يَعِدُكُمُ ٱللَّهُ إِحْدَى ٱلطَّآئِفَتَيْنِ أَنَّهَا لَكُمْ وَتَوَدُّونَ أَنَّ غَيْرَ ذَاتِ ٱلشَّوْكَةِ تَكُونُ لَكُمْ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلْحَقَّ بِكَلِمَـٰتِهِۦ وَيَقْطَعَ دَابِرَ ٱلْكَـٰفِرِينَ','85c1cf6c10e9cc4e31605d7bd73844234d6eee459c765a1e2346b26c7d8563d1',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1168,8,8,'لِيُحِقَّ ٱلْحَقَّ وَيُبْطِلَ ٱلْبَـٰطِلَ وَلَوْ كَرِهَ ٱلْمُجْرِمُونَ','f4e6cd700c5aad175e0d223912f0572372a02630a7befc5a6240ad2d7d44b22a',9,177,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1169,8,9,'إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَٱسْتَجَابَ لَكُمْ أَنِّى مُمِدُّكُم بِأَلْفٍ مِّنَ ٱلْمَلَـٰٓئِكَةِ مُرْدِفِينَ','651cdce7210e39d730f9d5a396bf520e9545998b6fb6674eadf73d1c96d7fb6d',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1170,8,10,'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِۦ قُلُوبُكُمْ ۚ وَمَا ٱلنَّصْرُ إِلَّا مِنْ عِندِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','ee04c9a3dcbe028106d1d398112aace4fcd453daf88873e81e4d02f199fdc774',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1171,8,11,'إِذْ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةً مِّنْهُ وَيُنَزِّلُ عَلَيْكُم مِّنَ ٱلسَّمَآءِ مَآءً لِّيُطَهِّرَكُم بِهِۦ وَيُذْهِبَ عَنكُمْ رِجْزَ ٱلشَّيْطَـٰنِ وَلِيَرْبِطَ عَلَىٰ قُلُوبِكُمْ وَيُثَبِّتَ بِهِ ٱلْأَقْدَامَ','d0481d0d7070b7475bafabebe5ca09c0425d344a43725229a11a1ff76c33de2a',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1172,8,12,'إِذْ يُوحِى رَبُّكَ إِلَى ٱلْمَلَـٰٓئِكَةِ أَنِّى مَعَكُمْ فَثَبِّتُوا۟ ٱلَّذِينَ ءَامَنُوا۟ ۚ سَأُلْقِى فِى قُلُوبِ ٱلَّذِينَ كَفَرُوا۟ ٱلرُّعْبَ فَٱضْرِبُوا۟ فَوْقَ ٱلْأَعْنَاقِ وَٱضْرِبُوا۟ مِنْهُمْ كُلَّ بَنَانٍ','e14fa5701caa6ceafcc4ab4cd5e97d189aaf94a479783364c0f8b25ac0f56800',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1173,8,13,'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','09f23a7c416ca2b477b71cc3726fc123fcee1b0349d1e011d5f0dc546a1b3eeb',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1174,8,14,'ذَٰلِكُمْ فَذُوقُوهُ وَأَنَّ لِلْكَـٰفِرِينَ عَذَابَ ٱلنَّارِ','db10f7fddc63f5157c8727c1d1eb6da16a39dbe4ac2ec7c382e141382f647b57',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1175,8,15,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُوا۟ زَحْفًا فَلَا تُوَلُّوهُمُ ٱلْأَدْبَارَ','eb3a2dc813d59c34bc34649c24c1c9b79c69591e9ed1655add81e115471d39af',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1176,8,16,'وَمَن يُوَلِّهِمْ يَوْمَئِذٍ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفًا لِّقِتَالٍ أَوْ مُتَحَيِّزًا إِلَىٰ فِئَةٍ فَقَدْ بَآءَ بِغَضَبٍ مِّنَ ٱللَّهِ وَمَأْوَىٰهُ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ','6e4976ee2f7c4a33b6534994ca37d52cf32e44ffe59cce37c92be1c8e4b58d0e',9,178,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1177,8,17,'فَلَمْ تَقْتُلُوهُمْ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمْ ۚ وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ ۚ وَلِيُبْلِىَ ٱلْمُؤْمِنِينَ مِنْهُ بَلَآءً حَسَنًا ۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','fc2fb0392d98e44e6f1fda08abfa4bb1ee1260d99c39ccc5c04643994c47a0cd',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1178,8,18,'ذَٰلِكُمْ وَأَنَّ ٱللَّهَ مُوهِنُ كَيْدِ ٱلْكَـٰفِرِينَ','fc378f9ffdb569b8fa3efecacd1b160d12b5af23b485051a4f6c1e4f78ffd615',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1179,8,19,'إِن تَسْتَفْتِحُوا۟ فَقَدْ جَآءَكُمُ ٱلْفَتْحُ ۖ وَإِن تَنتَهُوا۟ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَعُودُوا۟ نَعُدْ وَلَن تُغْنِىَ عَنكُمْ فِئَتُكُمْ شَيْـًٔا وَلَوْ كَثُرَتْ وَأَنَّ ٱللَّهَ مَعَ ٱلْمُؤْمِنِينَ','a5cf3c125637b9c72885d7e7f1e11fedc6d20f040b28ff53e26d469e0a877092',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1180,8,20,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوْا۟ عَنْهُ وَأَنتُمْ تَسْمَعُونَ','a59630e7b14b00f35ff34e06f95ce1bfb8018f9186d8808b82742acdf412f38e',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1181,8,21,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ قَالُوا۟ سَمِعْنَا وَهُمْ لَا يَسْمَعُونَ','308e7a7307c62017f84807e931b5cd793edec534a4be0eb0e61af63f147a46bf',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1182,8,22,'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلْبُكْمُ ٱلَّذِينَ لَا يَعْقِلُونَ','7127bfd118fb07cfa955de30f8a081496677de1613b92be42fd339a01300f247',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1183,8,23,'وَلَوْ عَلِمَ ٱللَّهُ فِيهِمْ خَيْرًا لَّأَسْمَعَهُمْ ۖ وَلَوْ أَسْمَعَهُمْ لَتَوَلَّوا۟ وَّهُم مُّعْرِضُونَ','e63dd1140c1608c83ad973c8084a8da3e3f55ba75cefa310aa48d19eaeea9769',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1184,8,24,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَجِيبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَحُولُ بَيْنَ ٱلْمَرْءِ وَقَلْبِهِۦ وَأَنَّهُۥٓ إِلَيْهِ تُحْشَرُونَ','2d720d328484740bba45028be39dd0481f883f31abd47173ccf963e57f10a167',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1185,8,25,'وَٱتَّقُوا۟ فِتْنَةً لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُوا۟ مِنكُمْ خَآصَّةً ۖ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ','01003cc3e4e077782e11dc0de275dc097911d334ecd2d8d753d040f6955a8989',9,179,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1186,8,26,'وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمْ وَأَيَّدَكُم بِنَصْرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَـٰتِ لَعَلَّكُمْ تَشْكُرُونَ','4084d34d9940092cf3bef0e83c6626091789b4d7fde1d5d4d63b0a3baec9e7d3',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1187,8,27,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓا۟ أَمَـٰنَـٰتِكُمْ وَأَنتُمْ تَعْلَمُونَ','6174e34e0836ca35c0fbb211f1d2f071fad0c941615c1635f63ade70e976dd7a',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1188,8,28,'وَٱعْلَمُوٓا۟ أَنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجْرٌ عَظِيمٌ','a54e433e136128a78de8219bfbb8acb4e289cdb3f58c6a35a3100bcb88cd36e2',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1189,8,29,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَتَّقُوا۟ ٱللَّهَ يَجْعَل لَّكُمْ فُرْقَانًا وَيُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ','2015fd016041707f121a03f3f7594247ca8e9f59dc98538d4a54c4857f920e0e',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1190,8,30,'وَإِذْ يَمْكُرُ بِكَ ٱلَّذِينَ كَفَرُوا۟ لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ ۚ وَيَمْكُرُونَ وَيَمْكُرُ ٱللَّهُ ۖ وَٱللَّهُ خَيْرُ ٱلْمَـٰكِرِينَ','0102684159dbbc43c9ac76813662dd8661b016fcec8025042ba0c09787cae1a9',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1191,8,31,'وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا قَالُوا۟ قَدْ سَمِعْنَا لَوْ نَشَآءُ لَقُلْنَا مِثْلَ هَـٰذَآ ۙ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ','2303a6bfd97c56424fd6309bbd37b94ec054083505970e9fd48c1d80141a73ac',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1192,8,32,'وَإِذْ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَـٰذَا هُوَ ٱلْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ ٱلسَّمَآءِ أَوِ ٱئْتِنَا بِعَذَابٍ أَلِيمٍ','9276a18408ae32a53a3b26229baea4f5fdf652569d3e6a998cc16a01ff39a0d7',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1193,8,33,'وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمْ وَأَنتَ فِيهِمْ ۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ','857b2e9e00181af5192440317ce9d77bfc8f3d3f3fc8a13c08201968eaa26bc0',9,180,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1194,8,34,'وَمَا لَهُمْ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمْ يَصُدُّونَ عَنِ ٱلْمَسْجِدِ ٱلْحَرَامِ وَمَا كَانُوٓا۟ أَوْلِيَآءَهُۥٓ ۚ إِنْ أَوْلِيَآؤُهُۥٓ إِلَّا ٱلْمُتَّقُونَ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ','efec70bfcedfc2ca1be3f2dc4b05caee1deb17066776449ca81411cc89be0e46',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1195,8,35,'وَمَا كَانَ صَلَاتُهُمْ عِندَ ٱلْبَيْتِ إِلَّا مُكَآءً وَتَصْدِيَةً ۚ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْفُرُونَ','642d433a9c8764afd9dc9e1378b4abe3b0247eed7495765658c03d5c0aac8a95',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1196,8,36,'إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنفِقُونَ أَمْوَٰلَهُمْ لِيَصُدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ ۗ وَٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ يُحْشَرُونَ','dd9034e66e0d2a3e6c0d2954361448c65fe4e8f4b04c7214ea42a637ac1da038',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1197,8,37,'لِيَمِيزَ ٱللَّهُ ٱلْخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجْعَلَ ٱلْخَبِيثَ بَعْضَهُۥ عَلَىٰ بَعْضٍ فَيَرْكُمَهُۥ جَمِيعًا فَيَجْعَلَهُۥ فِى جَهَنَّمَ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ','57dee808e93fbf59b7e0fd94ae931bd754b05a52ee9189753a740570b4300bc0',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1198,8,38,'قُل لِّلَّذِينَ كَفَرُوٓا۟ إِن يَنتَهُوا۟ يُغْفَرْ لَهُم مَّا قَدْ سَلَفَ وَإِن يَعُودُوا۟ فَقَدْ مَضَتْ سُنَّتُ ٱلْأَوَّلِينَ','5fc7dfbebb3f4cca5b31616f2783070823192c78a4e4ccc124bee59ef7c85de3',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1199,8,39,'وَقَـٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِ ۚ فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ بِمَا يَعْمَلُونَ بَصِيرٌ','c86f58230ce9d14381386d52058c040b085561128ff6ad6999abf74ec987661f',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1200,8,40,'وَإِن تَوَلَّوْا۟ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَوْلَىٰكُمْ ۚ نِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ','32d4a75b5b97682ced289a50d73f48559b5ffdf18d1c3fe8b98b227e5633f054',9,181,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1201,8,41,'وَٱعْلَمُوٓا۟ أَنَّمَا غَنِمْتُم مِّن شَىْءٍ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ إِن كُنتُمْ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلْنَا عَلَىٰ عَبْدِنَا يَوْمَ ٱلْفُرْقَانِ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ','0ce3f0921cd184f609b4bd7ef55d928060ac9f3e11fe79bda27a189794cba142',10,182,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1202,8,42,'إِذْ أَنتُم بِٱلْعُدْوَةِ ٱلدُّنْيَا وَهُم بِٱلْعُدْوَةِ ٱلْقُصْوَىٰ وَٱلرَّكْبُ أَسْفَلَ مِنكُمْ ۚ وَلَوْ تَوَاعَدتُّمْ لَٱخْتَلَفْتُمْ فِى ٱلْمِيعَـٰدِ ۙ وَلَـٰكِن لِّيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا لِّيَهْلِكَ مَنْ هَلَكَ عَنۢ بَيِّنَةٍ وَيَحْيَىٰ مَنْ حَىَّ عَنۢ بَيِّنَةٍ ۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ','9abb8121101f2cee9fd08bd0ca3a73bb173d8ba7b15ca823292461360e5eec1d',10,182,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1203,8,43,'إِذْ يُرِيكَهُمُ ٱللَّهُ فِى مَنَامِكَ قَلِيلًا ۖ وَلَوْ أَرَىٰكَهُمْ كَثِيرًا لَّفَشِلْتُمْ وَلَتَنَـٰزَعْتُمْ فِى ٱلْأَمْرِ وَلَـٰكِنَّ ٱللَّهَ سَلَّمَ ۗ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ','d035a6bfddf045cbc74cadc81d473ab24d4201ab217d8b2970eaf222184681ee',10,182,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1204,8,44,'وَإِذْ يُرِيكُمُوهُمْ إِذِ ٱلْتَقَيْتُمْ فِىٓ أَعْيُنِكُمْ قَلِيلًا وَيُقَلِّلُكُمْ فِىٓ أَعْيُنِهِمْ لِيَقْضِىَ ٱللَّهُ أَمْرًا كَانَ مَفْعُولًا ۗ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ','80756d581ea456fd6dd0c79b518b3a6bd93e0707987d4b1ea29eda9a219e1be2',10,182,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1205,8,45,'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا لَقِيتُمْ فِئَةً فَٱثْبُتُوا۟ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ','d77c15c97b66e76bda096bc17eadc153595e2f107bfaacc6e9d264fb2cd466d5',10,182,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1206,8,46,'وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَـٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِينَ','529d22ad7df78b410cbb9bd1ab8998fd367d74f63379181312024b4f0f3177af',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1207,8,47,'وَلَا تَكُونُوا۟ كَٱلَّذِينَ خَرَجُوا۟ مِن دِيَـٰرِهِم بَطَرًا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۚ وَٱللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ','3a04548127df28222c53b2338bc2f3d4e6afb8012a54ae62845a62bb61ca2652',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1208,8,48,'وَإِذْ زَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ وَقَالَ لَا غَالِبَ لَكُمُ ٱلْيَوْمَ مِنَ ٱلنَّاسِ وَإِنِّى جَارٌ لَّكُمْ ۖ فَلَمَّا تَرَآءَتِ ٱلْفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيْهِ وَقَالَ إِنِّى بَرِىٓءٌ مِّنكُمْ إِنِّىٓ أَرَىٰ مَا لَا تَرَوْنَ إِنِّىٓ أَخَافُ ٱللَّهَ ۚ وَٱللَّهُ شَدِيدُ ٱلْعِقَابِ','c2094d2bf4dc6cbd11231e20f956fe5237a96b7c8256c947f636c470ee6de090',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1209,8,49,'إِذْ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰٓؤُلَآءِ دِينُهُمْ ۗ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ','e68d23b23589b73d761f1aa04e6ab37df1ee45ad64a75fb15cc248648528afda',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1210,8,50,'وَلَوْ تَرَىٰٓ إِذْ يَتَوَفَّى ٱلَّذِينَ كَفَرُوا۟ ۙ ٱلْمَلَـٰٓئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـٰرَهُمْ وَذُوقُوا۟ عَذَابَ ٱلْحَرِيقِ','e72af9a07d9f55b1b79778cb10f73b9d0ebc4189303284ec97d8b1d8263ec639',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1211,8,51,'ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ ٱللَّهَ لَيْسَ بِظَلَّـٰمٍ لِّلْعَبِيدِ','03de21f64d2654971d87e1feb2488f26102c04bd324cd281901a8e71bfb80a6c',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1212,8,52,'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَفَرُوا۟ بِـَٔايَـٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ ۗ إِنَّ ٱللَّهَ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ','c85b530fd76fabfbdd470dae66ad189d1389c4c859cb1aefe32f79daa8c164b5',10,183,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1213,8,53,'ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ','07aabc4119e0562ca20c1d69079da3d0e7aa5c14e099b5c80f432ba18c421365',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1214,8,54,'كَدَأْبِ ءَالِ فِرْعَوْنَ ۙ وَٱلَّذِينَ مِن قَبْلِهِمْ ۚ كَذَّبُوا۟ بِـَٔايَـٰتِ رَبِّهِمْ فَأَهْلَكْنَـٰهُم بِذُنُوبِهِمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ ۚ وَكُلٌّ كَانُوا۟ ظَـٰلِمِينَ','2f3e9a2d40a01fade4afad66eef5f9fd5646f6317119b3586dea2722dccb353a',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1215,8,55,'إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُوا۟ فَهُمْ لَا يُؤْمِنُونَ','7a77de18cd5f79402f790aa2291d84dacc05b89a372bd8963e7bcacb9d9ac3e9',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1216,8,56,'ٱلَّذِينَ عَـٰهَدتَّ مِنْهُمْ ثُمَّ يَنقُضُونَ عَهْدَهُمْ فِى كُلِّ مَرَّةٍ وَهُمْ لَا يَتَّقُونَ','e7bdc6d2133747a3188780795c2872894ab5b89067a256d6de4c81e8f076e540',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1217,8,57,'فَإِمَّا تَثْقَفَنَّهُمْ فِى ٱلْحَرْبِ فَشَرِّدْ بِهِم مَّنْ خَلْفَهُمْ لَعَلَّهُمْ يَذَّكَّرُونَ','3e05ba2946fb8ec7700f958519784e77d1e3eb1119f121f972fc71e71ec0b14c',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1218,8,58,'وَإِمَّا تَخَافَنَّ مِن قَوْمٍ خِيَانَةً فَٱنۢبِذْ إِلَيْهِمْ عَلَىٰ سَوَآءٍ ۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْخَآئِنِينَ','8befe98a78b2415ac912fd980e8eda679765361dcde775f370ea9164c0b22d5a',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1219,8,59,'وَلَا يَحْسَبَنَّ ٱلَّذِينَ كَفَرُوا۟ سَبَقُوٓا۟ ۚ إِنَّهُمْ لَا يُعْجِزُونَ','a83df433c07bedbfc2356b93dbe3c3ca0b4a1b1d1f848f8ae96304c2f8ce647d',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1220,8,60,'وَأَعِدُّوا۟ لَهُم مَّا ٱسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ ٱلْخَيْلِ تُرْهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمْ وَءَاخَرِينَ مِن دُونِهِمْ لَا تَعْلَمُونَهُمُ ٱللَّهُ يَعْلَمُهُمْ ۚ وَمَا تُنفِقُوا۟ مِن شَىْءٍ فِى سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ','97e5d34813c832f9b74371fb4a9184cad6e22fc0ed090123646c62ded9fe9fb5',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1221,8,61,'وَإِن جَنَحُوا۟ لِلسَّلْمِ فَٱجْنَحْ لَهَا وَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ','8db37c51523152e6e160785590e55f7e3f96012cb7602252b29818d32ef5c2bc',10,184,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1222,8,62,'وَإِن يُرِيدُوٓا۟ أَن يَخْدَعُوكَ فَإِنَّ حَسْبَكَ ٱللَّهُ ۚ هُوَ ٱلَّذِىٓ أَيَّدَكَ بِنَصْرِهِۦ وَبِٱلْمُؤْمِنِينَ','00080b9f4165ec4f9c452deeac9a2e6cf9fff64f21852cb39324acbf01894ad2',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1223,8,63,'وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِى ٱلْأَرْضِ جَمِيعًا مَّآ أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَـٰكِنَّ ٱللَّهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُۥ عَزِيزٌ حَكِيمٌ','d1b67e2970a457a57f891faf06a779880e5f09337d60b27f77ed3212b10d6fa9',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1224,8,64,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَسْبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلْمُؤْمِنِينَ','34ecd7aabbe649b786f353fa668f60e574ff4608ace3ca276329bff2dec79466',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1225,8,65,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ حَرِّضِ ٱلْمُؤْمِنِينَ عَلَى ٱلْقِتَالِ ۚ إِن يَكُن مِّنكُمْ عِشْرُونَ صَـٰبِرُونَ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُم مِّا۟ئَةٌ يَغْلِبُوٓا۟ أَلْفًا مِّنَ ٱلَّذِينَ كَفَرُوا۟ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ','cfe2c8e7cd3ee0c97671d61d5e88da1701c46302c6e47e98398fd36fd29a3756',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1226,8,66,'ٱلْـَٔـٰنَ خَفَّفَ ٱللَّهُ عَنكُمْ وَعَلِمَ أَنَّ فِيكُمْ ضَعْفًا ۚ فَإِن يَكُن مِّنكُم مِّا۟ئَةٌ صَابِرَةٌ يَغْلِبُوا۟ مِا۟ئَتَيْنِ ۚ وَإِن يَكُن مِّنكُمْ أَلْفٌ يَغْلِبُوٓا۟ أَلْفَيْنِ بِإِذْنِ ٱللَّهِ ۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِينَ','1da84da910c719bf468b0e649181cbe192ee8efa909a2e78d3b76854f1f05dfe',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1227,8,67,'مَا كَانَ لِنَبِىٍّ أَن يَكُونَ لَهُۥٓ أَسْرَىٰ حَتَّىٰ يُثْخِنَ فِى ٱلْأَرْضِ ۚ تُرِيدُونَ عَرَضَ ٱلدُّنْيَا وَٱللَّهُ يُرِيدُ ٱلْـَٔاخِرَةَ ۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ','c7ee0ff97ffc25ada151dd416a87d9b966eca84e07911cf9733c5163b200c74f',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1228,8,68,'لَّوْلَا كِتَـٰبٌ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمْ فِيمَآ أَخَذْتُمْ عَذَابٌ عَظِيمٌ','5d92731c1c6ae182d2e5b269ae248d10975ba38ee9b2644a72c12ab3c9fa50e4',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1229,8,69,'فَكُلُوا۟ مِمَّا غَنِمْتُمْ حَلَـٰلًا طَيِّبًا ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','8ba5155dae2555d73d996992479f97dd5f8efa6bb27c6440d8b7b5b2e2e45995',10,185,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1230,8,70,'يَـٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّمَن فِىٓ أَيْدِيكُم مِّنَ ٱلْأَسْرَىٰٓ إِن يَعْلَمِ ٱللَّهُ فِى قُلُوبِكُمْ خَيْرًا يُؤْتِكُمْ خَيْرًا مِّمَّآ أُخِذَ مِنكُمْ وَيَغْفِرْ لَكُمْ ۗ وَٱللَّهُ غَفُورٌ رَّحِيمٌ','122626620d8137651dfc1c52fc1f8edc4ea36fa574a3e4c7b95e6b5781122861',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1231,8,71,'وَإِن يُرِيدُوا۟ خِيَانَتَكَ فَقَدْ خَانُوا۟ ٱللَّهَ مِن قَبْلُ فَأَمْكَنَ مِنْهُمْ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','b0b55be4d92c48051246ae0f116e3718fd9b5667f4aca17084c4df579bd494cf',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1232,8,72,'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ وَٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يُهَاجِرُوا۟ مَا لَكُم مِّن وَلَـٰيَتِهِم مِّن شَىْءٍ حَتَّىٰ يُهَاجِرُوا۟ ۚ وَإِنِ ٱسْتَنصَرُوكُمْ فِى ٱلدِّينِ فَعَلَيْكُمُ ٱلنَّصْرُ إِلَّا عَلَىٰ قَوْمٍۭ بَيْنَكُمْ وَبَيْنَهُم مِّيثَـٰقٌ ۗ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ','8c2c9708069552eece6456eeeb9f6ef5382750f78166a6084ec4bfc126c179e6',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1233,8,73,'وَٱلَّذِينَ كَفَرُوا۟ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ إِلَّا تَفْعَلُوهُ تَكُن فِتْنَةٌ فِى ٱلْأَرْضِ وَفَسَادٌ كَبِيرٌ','6b2d7e39e069aeec59ccb01f5be9e1ffc40c38905c24a77bd7910f45d2b9d495',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1234,8,74,'وَٱلَّذِينَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا۟ وَّنَصَرُوٓا۟ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُؤْمِنُونَ حَقًّا ۚ لَّهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ','9fe171c5be818ce9e686c1e7c74e0e097d5b99efc5c1cf301d3e1e8df5c4d5e6',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1235,8,75,'وَٱلَّذِينَ ءَامَنُوا۟ مِنۢ بَعْدُ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ مَعَكُمْ فَأُو۟لَـٰٓئِكَ مِنكُمْ ۚ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَـٰبِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌۢ','805882d3708507b696d4ae4b0ad96dea6724cdd51d6fff650634eea4202da06e',10,186,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1236,9,1,'بَرَآءَةٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ','d18402a276407219dcaeb5cb91cb19ddaa8a92fe282eedc6c0028f83d40e5766',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1237,9,2,'فَسِيحُوا۟ فِى ٱلْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۙ وَأَنَّ ٱللَّهَ مُخْزِى ٱلْكَـٰفِرِينَ','9ce31acac9e11f42d5b3cea2143b73cc3a5754a0920a5f335faa75db2ecd175f',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1238,9,3,'وَأَذَٰنٌ مِّنَ ٱللَّهِ وَرَسُولِهِۦٓ إِلَى ٱلنَّاسِ يَوْمَ ٱلْحَجِّ ٱلْأَكْبَرِ أَنَّ ٱللَّهَ بَرِىٓءٌ مِّنَ ٱلْمُشْرِكِينَ ۙ وَرَسُولُهُۥ ۚ فَإِن تُبْتُمْ فَهُوَ خَيْرٌ لَّكُمْ ۖ وَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّكُمْ غَيْرُ مُعْجِزِى ٱللَّهِ ۗ وَبَشِّرِ ٱلَّذِينَ كَفَرُوا۟ بِعَذَابٍ أَلِيمٍ','c16026a10c3e20eed8732cc5fd849b1d7cbfffc977f5607d0c211402980bdf4e',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1239,9,4,'إِلَّا ٱلَّذِينَ عَـٰهَدتُّم مِّنَ ٱلْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْـًٔا وَلَمْ يُظَـٰهِرُوا۟ عَلَيْكُمْ أَحَدًا فَأَتِمُّوٓا۟ إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ','26ec70bee5576c90638cd95ab5e327608869fc0656d983c7a853e06356290a35',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1240,9,5,'فَإِذَا ٱنسَلَخَ ٱلْأَشْهُرُ ٱلْحُرُمُ فَٱقْتُلُوا۟ ٱلْمُشْرِكِينَ حَيْثُ وَجَدتُّمُوهُمْ وَخُذُوهُمْ وَٱحْصُرُوهُمْ وَٱقْعُدُوا۟ لَهُمْ كُلَّ مَرْصَدٍ ۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِيلَهُمْ ۚ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ','176ae90d0ca2542b621eeb722033a0d1816b4f6d94710fa2075054b426d47ab3',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1241,9,6,'وَإِنْ أَحَدٌ مِّنَ ٱلْمُشْرِكِينَ ٱسْتَجَارَكَ فَأَجِرْهُ حَتَّىٰ يَسْمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبْلِغْهُ مَأْمَنَهُۥ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْلَمُونَ','184272707a05504a2a7b32a70ed7726534d7c1ee13f360dfcf5df5af758fdd45',10,187,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1242,9,7,'كَيْفَ يَكُونُ لِلْمُشْرِكِينَ عَهْدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦٓ إِلَّا ٱلَّذِينَ عَـٰهَدتُّمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۖ فَمَا ٱسْتَقَـٰمُوا۟ لَكُمْ فَٱسْتَقِيمُوا۟ لَهُمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَّقِينَ','3f041c60be3186921b306fb41c5c43b2109cf957cc5916a7cc3d41a4415ccfc8',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1243,9,8,'كَيْفَ وَإِن يَظْهَرُوا۟ عَلَيْكُمْ لَا يَرْقُبُوا۟ فِيكُمْ إِلًّا وَلَا ذِمَّةً ۚ يُرْضُونَكُم بِأَفْوَٰهِهِمْ وَتَأْبَىٰ قُلُوبُهُمْ وَأَكْثَرُهُمْ فَـٰسِقُونَ','280f9830bb0d09ab760ebe12cc8c100b9dee253084a47d48af70ea862ad46a11',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1244,9,9,'ٱشْتَرَوْا۟ بِـَٔايَـٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ','cea46d37c9b8dd0b38fb1ec91682e3cd33ed8503ca1317a4f60996d91ace0051',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1245,9,10,'لَا يَرْقُبُونَ فِى مُؤْمِنٍ إِلًّا وَلَا ذِمَّةً ۚ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُعْتَدُونَ','397888e8b21daa0098f6fb52a4dd97d6c49812bb6c78c8edc94f98fd5f7d30bd',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1246,9,11,'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ ۗ وَنُفَصِّلُ ٱلْـَٔايَـٰتِ لِقَوْمٍ يَعْلَمُونَ','a123f41fbc504b52e884d8a465bacedc249cb9e742a290f5880b14a54d8f6408',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1247,9,12,'وَإِن نَّكَثُوٓا۟ أَيْمَـٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ وَطَعَنُوا۟ فِى دِينِكُمْ فَقَـٰتِلُوٓا۟ أَئِمَّةَ ٱلْكُفْرِ ۙ إِنَّهُمْ لَآ أَيْمَـٰنَ لَهُمْ لَعَلَّهُمْ يَنتَهُونَ','be866346f36f09e6984e0599d11d092ec912eebe5a3ab8429f0fd51a4e73422b',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1248,9,13,'أَلَا تُقَـٰتِلُونَ قَوْمًا نَّكَثُوٓا۟ أَيْمَـٰنَهُمْ وَهَمُّوا۟ بِإِخْرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمْ أَوَّلَ مَرَّةٍ ۚ أَتَخْشَوْنَهُمْ ۚ فَٱللَّهُ أَحَقُّ أَن تَخْشَوْهُ إِن كُنتُم مُّؤْمِنِينَ','06815976151f5a401690aadf8ab7c5b309e8212263aad5765f190ff8b3ab5a6c',10,188,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1249,9,14,'قَـٰتِلُوهُمْ يُعَذِّبْهُمُ ٱللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ','5dd745296f9e28f592eed40dfe3f5a47464dd517d3171c6b5b87e358ff190ad1',10,189,1);
insert into quran.ayahs(id,surah_id,ayah_number,text_uthmani,text_sha256,juz,page,source_id) values (1250,9,15,'وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ ۗ وَيَتُوبُ ٱللَّهُ عَلَىٰ مَن يَشَآءُ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ','45938a30d5987f1a89a0c584dd30c2aa94ac752dabc7d85c7bc61a7f7136ae43',10,189,1);
